		// MARK: Retention

		/// With the `generateDependencyTree` feature on, three in four graphs already split across modules gain the shapes the
		/// retention oracle judges (rule 3 of the seam contract: nothing is retained that inline frees). `RetainHome`, a seam
		/// of the seam's module that `RetainRoot`, a root of the roots' module, builds, binds `retainNavigator` and then
		/// builds `RetainDetail` through an instantiator; beneath it `RetainLeaf`, built by value or through an instantiator,
		/// holds a place of `RetainApi`, which `RetainLive`, beside the roots, fills. Nothing beneath `RetainDetail` reads
		/// `retainNavigator`, so once the root is released the inline build keeps none alive, whatever holds the builder of
		/// `RetainDetail`: the adopter's Navigator and Detail, which a seam whose levels' values its builder functions capture
		/// keeps alive. 35 in 100 draws make it `RetainInnerDetail`, a seam of its own that passes its place up, the shape
		/// #703 fixed, across seams; 35 in 100 make `RetainLive` read `retainNavigator`, which the inline build then
		/// keeps alive too. The instantiators are `Sendable` as the graph's sendability allows, and then the place is in the
		/// `@Sendable` family, whose cases carry no values, so the fill reads nothing. Four in ten hold `RetainLeaf`'s place in
		/// an erased instantiator, `ErasedInstantiator` or its `Sendable` twin as the instantiators are, which `RetainLive`
		/// fills forwarding `retainTicket`, so the oracle holds the builder that wrapper keeps.
		///
		/// `retentionRandom` draws only for this pass, which runs after every other pass and only in a graph another pass
		/// split, so that every graph in one module, and every other draw of a graph it draws in, draws as before.
		private mutating func addingRetentionShapes(to declarations: [TypeDeclaration]) -> [TypeDeclaration] {
			// `build()` calls this pass only for a graph split across modules.
			guard features.contains(.generateDependencyTree), retentionRandom.percentChance(75) else { return declarations }
			// Every roll is made before any is read, so that each draws as it does whatever the others draw.
			let detailIsSeam = retentionRandom.percentChance(35)
			let leafThroughInstantiator = retentionRandom.percentChance(50)
			let fillReadsNavigator = retentionRandom.percentChance(35)
			let sendableRoll = retentionRandom.percentChance(50)
			// `RetainLeaf`'s place held in an erased instantiator, which `RetainLive` fills forwarding `retainTicket`: a place
			// whose builder takes the value it forwards (`retentionSeamValueBeforeBuilderForwardingPlace`).
			let leafPlaceForwards = retentionRandom.percentChance(40)
			let isSendable = switch sendability {
			case .nonSendable: false
			case .sendable: true
			case .mixed: sendableRoll
			}
			let instantiator = isSendable ? "SendableInstantiator" : "Instantiator"
			let conformances = sendability == .mixed ? ["@unchecked Sendable"] : []
			let prefix = prefix
			func instantiable(_ suffix: String, module: GraphFuzzerModule = .seamModule, properties: [PropertyDeclaration] = []) -> TypeDeclaration {
				var declaration = TypeDeclaration(name: "\(prefix)\(suffix)", instantiableArguments: [], properties: properties, declaresHelperTypes: false, additionalConformances: conformances)
				declaration.module = module
				return declaration
			}
			let apiName = "\(prefix)RetainApi"
			let navigator = instantiable("RetainNavigator")
			let leafPlace = if leafPlaceForwards {
				PropertyDeclaration(attribute: "@Instantiated(fulfilledByType: \"\(prefix)RetainLive\")", label: "retainApiBuilder", type: "\(isSendable ? "SendableErasedInstantiator" : "ErasedInstantiator")<Int, any \(apiName)>")
			} else {
				PropertyDeclaration(attribute: "@Instantiated", label: "retainApi", type: "any \(apiName)")
			}
			let leaf = instantiable("RetainLeaf", properties: [leafPlace])
			var detail = instantiable(detailIsSeam ? "RetainInnerDetail" : "RetainDetail", properties: [
				leafThroughInstantiator
					? PropertyDeclaration(attribute: "@Instantiated", label: "retainLeafBuilder", type: "\(instantiator)<\(leaf.name)>")
					: PropertyDeclaration(attribute: "@Instantiated", label: "retainLeaf", type: leaf.name),
			])
			if detailIsSeam {
				detail.instantiableArguments = ["generateDependencyTree: true"]
			}
			var home = instantiable("RetainHome", properties: [
				PropertyDeclaration(attribute: "@Instantiated", label: "retainNavigator", type: navigator.name),
				PropertyDeclaration(attribute: "@Instantiated", label: detailIsSeam ? "retainInnerDetailBuilder" : "retainDetailBuilder", type: "\(instantiator)<\(detail.name)>"),
			])
			home.instantiableArguments = ["generateDependencyTree: true"]
			home.additionalDeclarations.append("public protocol \(apiName)\(helperTypesAreSendable ? ": Sendable" : "") {}")
			var live = instantiable("RetainLive", module: .samePackageCaller)
			live.instantiableArguments = ["fulfillingAdditionalTypes: [\(apiName).self]"]
			live.additionalConformances.append(apiName)
			live.fillsHole = true
			if leafPlaceForwards {
				live.properties.append(PropertyDeclaration(attribute: "@Forwarded", label: "retainTicket", type: "Int"))
			}
			// A fill of a place another seam passes up reads its caller's scope, which holds no navigator; nor does a place in
			// the `@Sendable` family, whose cases carry no values, so there the tool would reject the read, and with it every
			// other shape of the graph.
			if fillReadsNavigator, !detailIsSeam, !isSendable {
				live.properties.append(PropertyDeclaration(attribute: "@Received", label: "retainNavigator", type: navigator.name))
			}
			var root = instantiable("RetainRoot", module: .samePackageCaller, properties: [PropertyDeclaration(attribute: "@Instantiated", label: "retainHome", type: home.name)])
			root.instantiableArguments = ["isRoot: true"]
			return declarations + [navigator, leaf, detail, home, live, root]
		}

		private static let retentionRandomSeedMask: UInt64 = 0x726574656E74696F

		/// With the `generateDependencyTree` feature on, in two graphs in five whose seam, `HoleSeam`, builds the hole's owner,
		/// `HoleOwner`, at its first site (`holeOwner` or `holeOwnerBuilder`), labels that property as a keyword: `Type` or
		/// `Protocol`, which Swift rejects as a member's name written bare, `Self`, `init` or `default`. The property is a level
		/// of the hole's builders – a case of the seam's enum and, where the hole type takes a builder struct, a member of its
		/// struct – and, where `HoleSeam` is mocked, a field of its mock's overrides. Never `self`, which the fixture's
		/// initializer would take as the name of a parameter that hides the instance it assigns to, nor the second site,
		/// `holeSecondOwner`, whose label `holeOwnerReachedAtTwoSites` reads.
		///
		/// On a roll of its own, made whatever the first, four times in five it labels `holeServiceLazy` `Type` or `Protocol`
		/// where it is a `SendableLazilyInstantiated` of the hole: a place held in a `Sendable` wrapper, a case of the
		/// `@Sendable` enum that carries no values, which Swift rejects named `Type` or `Protocol` bare even where a case that
		/// carries values compiles. It takes the other of the two where the owner's label is the one drawn.
		///
		/// `keywordLabelRandom` draws only for this pass, which runs after every other draw and the builder surface's edit,
		/// so that every other graph, and every other draw of a graph it draws in, draws as before.
		private mutating func labelingHoleOwnersAsKeywords(in declarations: [TypeDeclaration]) -> [TypeDeclaration] {
			// Every roll is made before any is read, so that each draws as it does whatever the others draw.
			let drawsShape = keywordLabelRandom.percentChance(40)
			let keyword = keywordLabelRandom.element(of: Self.holeOwnerKeywordLabels)
			let relabelsSendablePlace = keywordLabelRandom.percentChance(80)
			let drawnPlaceKeyword = keywordLabelRandom.element(of: Self.sendablePlaceKeywordLabels)
			let ownerName = "\(prefix)HoleOwner"
			guard features.contains(.generateDependencyTree), let seamIndex = declarations.firstIndex(where: { $0.name == "\(prefix)HoleSeam" }) else { return declarations }
			var declarations = declarations
			var ownerKeyword: String?
			if drawsShape {
				for index in declarations[seamIndex].properties.indices where ["holeOwner", "holeOwnerBuilder"].contains(declarations[seamIndex].properties[index].label) {
					let property = declarations[seamIndex].properties[index]
					if property.type == ownerName || property.type.hasSuffix("<\(ownerName)>") {
						declarations[seamIndex].properties[index] = property.relabeled(keyword)
						ownerKeyword = keyword
					}
				}
			}
			if relabelsSendablePlace {
				let placeKeyword = drawnPlaceKeyword == ownerKeyword ? Self.sendablePlaceKeywordLabels.first { $0 != drawnPlaceKeyword } ?? drawnPlaceKeyword : drawnPlaceKeyword
				let sendablePlaceType = "SendableLazilyInstantiated<any \(prefix)HoleService>"
				for declarationIndex in declarations.indices where [ownerName, "\(prefix)HoleSeam"].contains(declarations[declarationIndex].name) {
					for index in declarations[declarationIndex].properties.indices where declarations[declarationIndex].properties[index].label == "holeServiceLazy" && declarations[declarationIndex].properties[index].type == sendablePlaceType {
						declarations[declarationIndex].properties[index] = declarations[declarationIndex].properties[index].relabeled(placeKeyword)
					}
				}
			}
			return declarations
		}

		/// The keywords `labelingHoleOwnersAsKeywords` labels a place held in a `Sendable` wrapper with: those Swift rejects
		/// as a case's name written bare.
		static let sendablePlaceKeywordLabels = ["`Type`", "`Protocol`"]

		/// The keywords `labelingHoleOwnersAsKeywords` labels the seam's property that builds `HoleOwner` with.
		static let holeOwnerKeywordLabels = ["`Type`", "`Protocol`", "`Self`", "`init`", "`default`"]

		private static let keywordLabelRandomSeedMask: UInt64 = 0x6B6579776F72644C

		/// With the `generateDependencyTree` feature on, half the graphs already split across modules gain a loop of builders
		/// inside a seam, the shape of an app's screens that open one another: `RetainLoopHome`, a seam of the seam's module
		/// that `RetainLoopRoot`, a root of the roots' module, builds, instantiates the builders of `RetainLoopA`,
		/// `RetainLoopB`, `RetainLoopC` and, four times in ten, `RetainLoopD`; each receives the next one's builder and holds a
		/// place of `RetainLoopApi`, which `RetainLoopLive`, beside the root, fills. The seam's initializer binds each member's
		/// level before the loop's first function, in one box that every member's function captures; the retention oracle
		/// judges that what a member's builder keeps alive once the root is released is what the inline build keeps. Four times
		/// in ten `RetainLoopFlow`, which the seam builds by value, declares the loop, so the levels are its level's. The
		/// builders are `Sendable` as the graph's sendability allows. No member receives a second builder, as an app's screens
		/// do: the comparator calls each builder it meets twice, so a loop whose members each open two others has more paths
		/// than a probe's traversals reach; unit tests cover that shape (`SafeDIToolSeamLoopLevelsTests`,
		/// `SafeDIToolReceivedBuilderCycleRetentionTests`).
		///
		/// `retentionLoopRandom` draws only for this pass, which runs after every other pass of a split graph but the seam calls
		/// inside fills, which draw after it from streams of their own, and only in a graph another pass split, so that every
		/// graph in one module, and every other draw of a graph it draws in, draws as before.
		private mutating func addingRetentionLoopShapes(to declarations: [TypeDeclaration]) -> [TypeDeclaration] {
			// `build()` calls this pass only for a graph split across modules.
			guard features.contains(.generateDependencyTree), retentionLoopRandom.percentChance(50) else { return declarations }
			// Every roll is made before any is read, so that each draws as it does whatever the others draw.
			let hasFourthMember = retentionLoopRandom.percentChance(40)
			let isBeneathSeam = retentionLoopRandom.percentChance(40)
			let sendableRoll = retentionLoopRandom.percentChance(50)
			let isSendable = switch sendability {
			case .nonSendable: false
			case .sendable: true
			case .mixed: sendableRoll
			}
			let instantiator = isSendable ? "SendableInstantiator" : "Instantiator"
			let conformances = sendability == .mixed ? ["@unchecked Sendable"] : []
			let prefix = prefix
			func instantiable(_ suffix: String, module: GraphFuzzerModule = .seamModule, properties: [PropertyDeclaration] = []) -> TypeDeclaration {
				var declaration = TypeDeclaration(name: "\(prefix)\(suffix)", instantiableArguments: [], properties: properties, declaresHelperTypes: false, additionalConformances: conformances)
				declaration.module = module
				return declaration
			}
			let apiName = "\(prefix)RetainLoopApi"
			let suffixes = hasFourthMember ? ["A", "B", "C", "D"] : ["A", "B", "C"]
			func builderProperty(_ suffix: String, attribute: String) -> PropertyDeclaration {
				PropertyDeclaration(attribute: attribute, label: "retainLoop\(suffix)Builder", type: "\(instantiator)<\(prefix)RetainLoop\(suffix)>")
			}
			var added = [TypeDeclaration]()
			for (position, suffix) in suffixes.enumerated() {
				let properties = [
					PropertyDeclaration(attribute: "@Instantiated", label: "retainLoopApi", type: "any \(apiName)"),
					builderProperty(suffixes[(position + 1) % suffixes.count], attribute: "@Received"),
				]
				added.append(instantiable("RetainLoop" + suffix, properties: properties))
			}
			let builders = suffixes.map { builderProperty($0, attribute: "@Instantiated") }
			var home = instantiable("RetainLoopHome")
			if isBeneathSeam {
				let flow = instantiable("RetainLoopFlow", properties: builders)
				home.properties.append(PropertyDeclaration(attribute: "@Instantiated", label: "retainLoopFlow", type: flow.name))
				added.append(flow)
			} else {
				home.properties = builders
			}
			home.instantiableArguments = ["generateDependencyTree: true"]
			home.additionalDeclarations.append("public protocol \(apiName)\(helperTypesAreSendable ? ": Sendable" : "") {}")
			var live = instantiable("RetainLoopLive", module: .samePackageCaller)
			live.instantiableArguments = ["fulfillingAdditionalTypes: [\(apiName).self]"]
			live.additionalConformances.append(apiName)
			live.fillsHole = true
			var root = instantiable("RetainLoopRoot", module: .samePackageCaller, properties: [PropertyDeclaration(attribute: "@Instantiated", label: "retainLoopHome", type: home.name)])
			root.instantiableArguments = ["isRoot: true"]
			return declarations + added + [home, live, root]
		}

