				features.insert(.holeLazyRouteSendableWrapper)
			}
			if properties(of: "HoleRouteImpl").contains(where: { $0.type.hasSuffix("?") }) {
				features.insert(.holeLazyRouteReadOnlyIfAvailable)
			}
			if properties(of: "HoleRouteDesk").contains(where: { $0.label == "holeRouteModelBuilder" }) {
				features.insert(.holeLazyRouteBeneathInstantiator)
			}
			if declares("HoleRoutePanel") {
				features.insert(.holeLazyRouteNestedSeamFillRequiresValue)
			}
			if declares("HoleRouteShelf") {
				features.insert(.holeLazyRouteSecondFormPlace)
			}
			if declares("HoleRouteWing") {
				features.insert(.holeLazyRouteSecondFormBeneathLevel)
			}
		}
		if declares("HoleTangleT") {
			features.insert(.holeTangleOfCycles)
			if properties(of: "HoleTangleImpl").contains(where: { $0.label == "holeTangleC" }) {
				features.insert(.holeTangleReadsInstantiator)
			}
			if declares("HoleTangleReader") {
				features.insert(.holeTangleTReadsMark)
			}
			if properties(of: "HoleSeam").contains(where: { $0.label == "holeTangleTValue" }) {
				features.insert(.holeTangleTBuiltByValue)
			}
		}
		if declares("HoleNest") {
			features.insert(.holePlaceInsidePlainFill)
			let nestLabels = Set(properties(of: "HoleNest").map(\.label))
			if nestLabels.isSuperset(of: ["holeNestService", "holeNestScreenBuilder"]) {
				features.insert(.holePlaceInsidePlainFillOnTwoInnerRoutes)
			}
			if nestLabels.contains("holeNestScreenBuilder"), properties(of: "HoleImpl").contains(where: { $0.label == "holeNestId" }) {
				features.insert(.holePlaceInsidePlainFillReadsInnerLevel)
			}
			if declares("HoleNestWidget") {
				features.insert(.holePlaceInsidePlainFillTwoTypesDeep)
			}
			if Set(seamProperties.map(\.label)).isSuperset(of: ["holeNest", "holeNestBuilder"]) {
				features.insert(.holePlaceInsidePlainFillTwoCalls)
			}
			if nestLabels.contains("holeNestScreenBuilder"), properties(of: "HoleNestImpl").contains(where: { $0.label == "holeNestId" }) {
				features.insert(.holePlaceInsidePlainFillFulfillerReadsInnerLevel)
			}
		}
		if declares("HoleScreen") {
			features.insert(.holeScreenPlace)
			let seamLabels = Set(seamProperties.map(\.label))
			// The seam opened again beneath the fill: by `HoleImpl`, `HoleMiddle` or `HoleTrackerImpl`, which fills a hole of a
			// seam `HoleImpl` builds.
			let reenters = (properties(of: "HoleImpl") + properties(of: "HoleMiddle") + properties(of: "HoleTrackerImpl")).contains { $0.label == "holeSeamBuilder" }
			let read = properties(of: "HoleImpl").first { $0.label == "holeScreenTag" }
			if seamProperties.contains(where: { $0.label == "holeScreenTag" && $0.attribute.hasPrefix("@Received") }) {
				features.insert(.holeScreenValueReceivedBySeam)
			} else if seamLabels.contains("holeScreenTag") {
				features.insert(.holeScreenValueBuiltBySeam)
			} else if !reenters {
				features.insert(.holeScreenValueReadWithoutReentry)
			} else if read?.attribute == "@Received" {
				features.insert(.holeScreenValueRequiredLostOnReentry)
			} else {
				features.insert(.holeScreenValueLostOnReentry)
			}
		}
		if declares("HoleRingA") {
			features.insert(.holeUnderLaterLoopMember)
			let placeLabels: Set = ["holeService", "holeRingLeaf"]
			if properties(of: "HoleRingA").contains(where: { placeLabels.contains($0.label) }) {
				features.insert(.holeUnderEveryLoopMember)
			}
			if declares("HoleRingC") {
				features.insert(.holeLoopOfThreeMembers)
			}
			if declares("HoleRingLeaf") {
				features.insert(.holeLoopPlaceThroughSharedLeaf)
			}
			if declares("HoleRingFlow") {
				features.insert(.holeLoopBeneathSeam)
			}
			if properties(of: "HoleImpl").contains(where: { $0.label == "holeRingMark" }) {
				features.insert(.holeLoopMemberLevelReadByFill)
			}
			if (seamProperties + properties(of: "HoleRingFlow")).contains(where: { $0.label == "holeRingAValue" }) {
				features.insert(.holeLoopMemberAlsoBuiltByValue)
			}
		}
		if properties(of: "HoleNestImpl").contains(where: { $0.label == "holeErasure" }) {
			features.insert(.holeErasureInsidePlainFill)
		}
		let spelledPlaceTypes = Set(properties(of: "HoleNestImpl").filter { $0.label.hasSuffix("Spelled") }.map(\.type))
		if spelledPlaceTypes.count == 2 {
			features.insert(.holePlacesInsideFillSpellTypeWithAndWithoutAny)
		}
		if properties(of: "HoleDeepImpl").contains(where: { $0.label == "holeErasure" }) {
			features.insert(.holeErasureInsideSendableFill)
		}
		if declares("HoleErasureOwner") {
			features.insert(.holeErasureBeneathSeamInSendableFamily)
		}
		if declares("HoleMiddle") {
			features.insert(.holeReentersSeamBeneathRedeclaredLabel)
		}
		if declares("HoleLoop") {
			features.insert(.holeSeamReentersItself)
			if properties(of: "HoleLoop").contains(where: { $0.label == "holeLogger" }) {
				features.insert(.holeSeamReentersItselfBeneathBoundLabel)
			}
		}
		return features
	}

	/// The shapes `addingAccessProofShapes` draws, read from the access levels the fixture spells on the `Proof` types'
	/// declarations and initializers, and from their properties.
	private static func accessProofDrawFeatures(of fixture: GraphFuzzerFixture) -> Set<GraphFuzzerSeamDrawFeature> {
		let prefix = fixture.typeNamePrefix
		/// Each class's spelled access and its initializer's, by name, and each extension line, from every file.
		var classAccess = [String: String]()
		var initializerAccess = [String: String]()
		var extensionLines = [String]()
		var currentClass: String?
		for content in fixture.swiftFileContent {
			for rawLine in content.split(separator: "\n") {
				let line = rawLine.trimmingCharacters(in: .whitespaces)
				let access = ["public", "package"].first { line.hasPrefix($0 + " ") } ?? "internal"
				let declaration = access == "internal" ? Substring(line) : line.dropFirst(access.count + 1)
				if declaration.hasPrefix("final class ") {
					let name = String(declaration.dropFirst("final class ".count).prefix { $0.isLetter || $0.isNumber || $0 == "_" })
					classAccess[name] = access
					currentClass = name
				} else if declaration.hasPrefix("init("), let currentClass, initializerAccess[currentClass] == nil {
					initializerAccess[currentClass] = access
				} else if declaration.hasPrefix("extension ") {
					extensionLines.append(line)
				}
			}
		}
		func properties(of typeSuffix: String) -> [(attribute: String, label: String, type: String)] {
			fixture.swiftFileContent.flatMap { content -> [(attribute: String, label: String, type: String)] in
				var isInType = false
				var properties = [(attribute: String, label: String, type: String)]()
				for line in GraphFuzzerSourceLine.lines(of: content) {
					switch line {
					case let .typeDeclaration(name):
						isInType = name == prefix + typeSuffix
					case let .property(attribute, label, type) where isInType:
						properties.append((attribute, label, type))
					case .instantiableAttribute, .instantiateMethod, .property, .other:
						break
					}
				}
				return properties
			}
		}
		let order = ["internal", "package", "public"]
		func isNarrower(_ access: String?, than otherAccess: String?) -> Bool {
			guard let access, let otherAccess, let index = order.firstIndex(of: access), let otherIndex = order.firstIndex(of: otherAccess) else { return false }
			return index < otherIndex
		}
		var features = Set<GraphFuzzerSeamDrawFeature>()
		let seamName = prefix + "ProofSeam"
		guard classAccess[seamName] != nil else { return features }
		if classAccess[seamName] != "public" {
			features.insert(.seamTypeNarrowerThanPublic)
		}
		let seamProperties = properties(of: "ProofSeam")
		let seamInitializerIsNarrower = isNarrower(initializerAccess[seamName], than: classAccess[seamName])
		if seamInitializerIsNarrower, classAccess[prefix + "ProofCog"] != nil, seamProperties.allSatisfy({ $0.label == "proofCog" }) {
			features.insert(.ownInitializerNarrowerWithNoPassThrough)
		}
		if seamInitializerIsNarrower, classAccess[prefix + "ProofVane"] != nil {
			features.insert(.ownInitializerNarrowerWithOnlyOptionalNarrowerPassThroughs)
		}
		if seamInitializerIsNarrower, classAccess[prefix + "ProofDial"] != nil {
			features.insert(.ownInitializerNarrowerThanTwoParameterLevels)
		}
		if isNarrower(initializerAccess[prefix + "ProofBadge"], than: classAccess[prefix + "ProofTheme"]) {
			features.insert(.receiverNarrowerThanType)
		}
		if isNarrower(classAccess[prefix + "ProofVault"], than: initializerAccess[prefix + "ProofVault"]) {
			features.insert(.receiverTypeNarrowerThanItsInitializer)
		}
		if properties(of: "ProofLock").contains(where: { $0.attribute == "@Received" }), isNarrower(classAccess[prefix + "ProofPin"], than: classAccess[seamName]) {
			features.insert(.requiredParameterNarrowerThanSeamType)
		}
		if seamProperties.contains(where: { $0.label == "proofOwn" && $0.attribute == "@Received(onlyIfAvailable: true)" }) {
			features.insert(.ownOnlyIfAvailableParameter)
			if isNarrower(classAccess[prefix + "ProofOwn"], than: classAccess[seamName]) {
				features.insert(.ownOnlyIfAvailableParameterNarrowerThanSeam)
			}
		}
		let hostProperties = properties(of: "ProofHost") + properties(of: "ProofOtherHost")
		if classAccess[prefix + "ProofPanel"] != nil {
			features.insert(hostProperties.contains { $0.label == "proofModel" } ? .providedValueHeldByCaller : .providedValueHeldByNoCaller)
		}
		if let alias = properties(of: "ProofConsumer").first(where: { $0.label == "proofAuth" }) {
			if fixture.swiftFileContent.contains(where: { $0.contains("@Instantiable\npackage final class \(prefix)ProofSession:") }) {
				features.insert(.aliasOfNarrowerInstantiableType)
			} else {
				features.insert(alias.attribute.contains("onlyIfAvailable: true") ? .unprovenAliasTypeOnlyIfAvailable : .unprovenAliasType)
			}
		}
		if properties(of: "ProofLedger").contains(where: { $0.label == "proofSession" }) {
			features.insert(.aliasFulfillingTypeAlsoReceived)
		}
		let namespaceExtensions = extensionLines.filter { $0.contains(prefix + "ProofSpace ") || $0.contains(prefix + "ProofSpace{") }
		if namespaceExtensions.contains(where: { $0.hasPrefix("extension ") }) {
			features.insert(.namespaceExtensionUnspelled)
		}
		if namespaceExtensions.contains(where: { !$0.hasPrefix("extension ") }) {
			features.insert(.namespaceExtensionSpelled)
		}
		if seamProperties.contains(where: { $0.label == "proofShelf" && $0.attribute.contains("erasedToConcreteExistential: true") }) {
			features.insert(.namespaceTypeOnlyThroughExistential)
		}
		if fixture.swiftFileContent.contains(where: { $0.contains("public enum \(prefix)ProofSpace {}") }) {
			features.insert(.publicNamespace)
		}
		if fixture.swiftFileContent.contains(where: { $0.contains("enum \(prefix)ProofSpace {}") && !$0.contains("@Instantiable") }) {
			features.insert(.namespaceInMarkerFreeFile)
		}
		if extensionLines.contains("extension \(prefix)ProofRack: Instantiable {") {
			features.insert(.instantiableExtensionOfNarrowerType)
		}
		if properties(of: "ProofMeter").contains(where: { $0.type.hasPrefix("Swift.") }) {
			features.insert(.qualifiedAllowlistMention)
		}
		if fixture.swiftFileContent.contains(where: { $0.contains("public static func mock(proofBolt: ") }) {
			features.insert(.mockInInstantiableExtension)
		}
		if extensionLines.contains("extension \(prefix)ProofShed: Instantiable {"), fixture.swiftFileContent.contains(where: { $0.contains("public static func mock(proofPlank: ") }) {
			features.insert(.mockCappedByItsExtension)
		}
		if properties(of: "ProofYard").contains(where: { $0.label == "proofShed" }) {
			features.insert(.mockCapRaisedByUnreachedMention)
		}
		if extensionLines.contains("extension \(seamName) {") {
			features.insert(.typeInExtensionOfSeam)
		}
		if extensionLines.contains("extension \(prefix)ProofSettings {"), classAccess[prefix + "ProofSettings"] == "package" {
			features.insert(.typeInExtensionOfNarrowerRecordedType)
		}
		for hostSuffix in ["ProofHost", "ProofOtherHost"] {
			let hostProperties = properties(of: hostSuffix)
			if let seamIndex = hostProperties.firstIndex(where: { $0.label == "proofSeam" }), hostProperties[(seamIndex + 1)...].contains(where: { $0.attribute == "@Instantiated" }) {
				features.insert(.valueDeclaredAfterSeam)
			}
		}
		if properties(of: "ProofMeter").contains(where: { $0.type.hasPrefix("Foundation.") }) {
			features.insert(.foundationQualifiedAllowlistMention)
		}
		if fixture.swiftFileContent.contains(where: { $0.contains("struct \(prefix)ProofFake {") }) {
			features.insert(.mockOnlyFakeMentionsReceivedType)
		}
		for hostSuffix in ["ProofHost", "ProofOtherHost"] {
			let hostProperties = properties(of: hostSuffix)
			if hostProperties.contains(where: { $0.type.contains("LazilyInstantiated<") }) {
				features.insert(.lazilyInstantiatedProvider)
			}
			if hostProperties.contains(where: { $0.attribute == "@Received(onlyIfAvailable: true)" }) {
				features.insert(.hostReceivesValuesOnlyIfAvailable)
			}
			if hostProperties.contains(where: { $0.label == "proofSeamHolder" }) {
				features.insert(.seamReachedThroughHolder)
			}
			if fixture.seamTypeNames.contains(prefix + hostSuffix) {
				features.insert(hostSuffix == "ProofHost" ? .samePackageHostIsSeam : .otherPackageHostIsSeam)
			}
		}
		if fixture.modules != nil {
			features.insert(.moduleSplit)
			let seamDependencyDraw = GraphFuzzerSeamDependencyDraw.drawn(in: fixture)
			let readsThroughView = (seamDependencyDraw.movesDeclaration || seamDependencyDraw.drawsChain) && !GraphFuzzerSeamDependencyDraw.callersReadingThroughView(of: fixture).isEmpty
			if seamDependencyDraw.movesDeclaration {
				features.insert(.seamDependency)
				if readsThroughView {
					features.insert(.seamDependencyReadThroughView)
				}
			}
			if seamDependencyDraw.drawsChain {
				features.insert(.seamDependencyChain)
				if readsThroughView {
					features.insert(.seamDependencyChainReadThroughView)
				}
			}
		}
		if classAccess[prefix + "ProofOtherRoot"] != nil {
			features.insert(.otherPackageCaller)
		}
		if fixture.modulesOmittingPackageName.contains(.samePackageCaller) {
			features.insert(.samePackageCallerRunWithoutPackageName)
		}
		if fixture.modulesOmittingPackageName.contains(.seamModule) {
			features.insert(.seamModuleRunWithoutPackageName)
		}
		return features
	}

	/// The name of the type an `@Instantiated` property of `type` with `attribute` builds: its `fulfilledByType:`,
	/// the generic of its wrapper, or its type.
	fileprivate static func builtTypeName(ofPropertyWithAttribute attribute: String, type: String) -> String {
		if let fulfilledByTypeRange = attribute.range(of: "fulfilledByType: \"") {
			String(attribute[fulfilledByTypeRange.upperBound...].prefix { $0 != "\"" })
		} else if let genericStart = type.firstIndex(of: "<"), let genericEnd = type.lastIndex(of: ">") {
			String(type[type.index(after: genericStart)..<genericEnd])
		} else {
			type
		}
	}

	/// What a seam's generated initializer takes, read from the widest tier in the seam's generated file, so that a
	/// generator which stops drawing a shape cannot hide it: `generatedFiles` is an accepted graph's output and
	/// `fixture` the graph, whose declarations tell a parameter received only if available from a required one
	/// (`GraphFuzzerSeamParameterKinds`), which the generated initializer spells alike.
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	static func seamOutputFeatures(of fixture: GraphFuzzerFixture, generatedFiles: [String: String]) -> Set<GraphFuzzerSeamOutputFeature> {
		let parameterKinds = GraphFuzzerSeamParameterKinds(fixture: fixture)
		var features = Set<GraphFuzzerSeamOutputFeature>()
		// The widest tier of each seam: the first of its initializers a file declares.
		var widestTiers = [(seamTypeName: String, parameters: [String])]()
		// The labels of each seam's builders, which the initializer only generated code calls takes over a scope type, where
		// the plain one can take a closure that takes nothing.
		var builderLabelsBySeam = [String: Set<String>]()
		for contents in generatedFiles.values where contents.contains("enum __safeDI_") {
			for initializer in GraphFuzzerOracle.seamInitializerParameters(inGeneratedFile: contents) where !widestTiers.contains(where: { $0.seamTypeName == initializer.seamTypeName }) {
				widestTiers.append(initializer)
			}
			for initializer in GraphFuzzerOracle.seamInitializers(inGeneratedFile: contents, keepsGeneratedOnlySpelling: true) {
				for parameter in initializer.parameters where parameter.contains("SafeDIScope_") || parameter.contains("SafeDISendableScope_") {
					builderLabelsBySeam[initializer.seamTypeName, default: []].formUnion(GraphFuzzerOracle.generatedOnlyLabel(of: parameter).map { [$0] } ?? [])
				}
			}
		}
		for (seamTypeName, parameters) in widestTiers {
			// A builder for a hole is no pass-through: `holeOutputFeatures` reads it.
			for parameter in parameters where !builderLabelsBySeam[seamTypeName, default: []].contains(parameter.prefix { $0 != ":" }.trimmingCharacters(in: .whitespaces)) {
				let label = parameter.prefix { $0 != ":" }.trimmingCharacters(in: .whitespaces)
				let type = parameter.drop { $0 != ":" }.dropFirst().trimmingCharacters(in: .whitespaces)
				if parameterKinds.isOnlyIfAvailable(label: label, ofSeam: seamTypeName) {
					features.insert(.optionalPassThrough)
				} else if parameterKinds.isRequiredPassThrough(label: label, type: type, ofSeam: seamTypeName) {
					features.insert(.requiredPassThrough)
				}
				if type.hasPrefix("@escaping @") {
					features.insert(.escapingAttributedSeamParameter)
				} else if type.hasPrefix("@escaping ") {
					features.insert(.escapingSeamParameter)
				} else if type.hasSuffix("?"), type.contains("->") {
					features.insert(.optionalClosureSeamParameter)
				}
			}
		}
		// A call of a generated initializer follows the line referring to its guard enum.
		for contents in generatedFiles.values {
			let lines = contents.split(separator: "\n", omittingEmptySubsequences: false)
			for (line, nextLine) in zip(lines, lines.dropFirst()) where line.contains(".__safeDI_") && nextLine.contains(".instance") {
				features.insert(.instanceReadAtCall)
			}
		}
		if generatedFiles.values.contains(where: { $0.contains("// SafeDI counts `") }) {
			features.insert(.unreadTypeComment)
		}
		let seamTypeNames = Set(widestTiers.map(\.seamTypeName))
		if generatedFiles.values.contains(where: { seamOwnMockTakesBuilder(in: $0, seamTypeNames: seamTypeNames) }) {
			features.insert(.seamOwnMockBuilder)
		}
		return features
	}

	/// Whether `contents`, a generated file, holds the `mock()` of one of `seamTypeNames` taking a builder as a closure that
	/// takes nothing (`GraphFuzzerSeamOutputFeature.seamOwnMockBuilder`).
	static func seamOwnMockTakesBuilder(in contents: String, seamTypeNames: Set<String>) -> Bool {
		var extendedType: String?
		var isInSeamMockParameters = false
		for line in contents.split(separator: "\n") {
			let trimmed = line.trimmingCharacters(in: .whitespaces)
			if trimmed.hasPrefix("extension "), trimmed.hasSuffix(" {") {
				extendedType = String(trimmed.dropFirst("extension ".count).dropLast(2))
			}
			if trimmed.hasSuffix("static func mock(") {
				isInSeamMockParameters = extendedType.map(seamTypeNames.contains) ?? false
			} else if trimmed.hasPrefix(")") {
				isInSeamMockParameters = false
			} else if isInSeamMockParameters, trimmed.range(of: #"^\w*Builder\w*: @escaping \(\) -> "#, options: .regularExpression) != nil {
				return true
			}
		}
		return false
	}

	/// What the code generated for a graph with a hole shows (`GraphFuzzerHoleOutputFeature`), read from
	/// `generatedFiles`, an accepted graph's output.
	static func holeOutputFeatures(generatedFiles: [String: String]) -> Set<GraphFuzzerHoleOutputFeature> {
		var features = Set<GraphFuzzerHoleOutputFeature>()
		// A builder over a scope enum, or a builder struct, which an initializer only generated code calls takes.
		let builderParameter = try! NSRegularExpression(pattern: #"\b\w+Builder\w*: (?:@escaping (@Sendable )?\((\w+\.)?SafeDI(?:Sendable)?Scope_|(\w+\.)?SafeDI(?:Sendable)?Scope_\w+\.__safeDI_Builder<|(\w+\.)?__safeDI_\w+Carrier<)"#)
		let otherSeamsStruct = try! NSRegularExpression(pattern: #"@escaping (?:@Sendable )?\((\w+)\.SafeDI(?:Sendable)?Scope_"#)
		let enumCaseOfInnerSeam = try! NSRegularExpression(pattern: #"^ +(?:indirect )?case \w+\((?:\w+, )?\w+\.SafeDI(?:Sendable)?Scope_"#)
		// A builder struct's member that builds another seam's builder struct, as an enum's case holding another seam's enum did.
		let structMemberOfInnerSeam = try! NSRegularExpression(pattern: #"^ +public let \w+: (?:@Sendable )?\(\w+_Values\) -> (\w+)\.SafeDI(?:Sendable)?Scope_"#)
		// A carrier's member that holds or forms another seam's carrier (or its builder struct), which the seam passes up.
		let carrierMemberOfInnerSeam = try! NSRegularExpression(pattern: #"^ +public let \w+: (?:@Sendable )?(?:\([^)]*\) -> )?(\w+)\.(?:__safeDI_\w+Carrier|SafeDI(?:Sendable)?Scope_)"#)
		// A function that returns a level's builder struct: its indentation, its name, the seam, the struct's path in the seam,
		// and the struct's generic argument.
		let levelFunction = try! NSRegularExpression(pattern: #"^( *)(?:@Sendable )?(?:nonisolated )?func (__safeDI_\w+)\([^)]*\) -> (\w+)\.(SafeDI(?:Sendable)?Scope_\w+(?:\.\w+_Scope)*\.__safeDI_Builder|__safeDI_\w+Carrier(?:_\w+)?)<(.*) \{$"#)
		let calledLevelFunction = try! NSRegularExpression(pattern: #"(?:\bin |: )(__safeDI_\w+)\("#)
		// A fill takes a case's payload; a dispatcher, the enum, which is no fill.
		let fillDeclaration = try! NSRegularExpression(pattern: #"^( *)(@Sendable nonisolated )?func (__safeDI_\w+)\(_ scope: (\w+)\.SafeDI(?:Sendable)?Scope_\w+(?:\.\w+_Scope_*)?\.\w+_Values"#)
		let dispatcherDeclaration = try! NSRegularExpression(pattern: #"^ *(?:@Sendable nonisolated )?func (__safeDI_\w+)\(_ scope: (\w+)\.SafeDI(?:Sendable)?Scope_\w+(?:\.\w+)?(?:, [^)]*)?\) -> "#)
		// A dispatcher that returns a level's builder struct, which a call passes by calling it.
		let levelFunctionDeclaration = try! NSRegularExpression(pattern: #"^ *(?:@Sendable (?:nonisolated )?)?func (__safeDI_\w+)\([^)]*\) -> (\w+)\.(?:SafeDI(?:Sendable)?Scope_\w+(?:\.\w+)?\.__safeDI_Builder|__safeDI_\w+Carrier(?:_\w+)?)<"#)
		// A carrier's level function, and its member that a caller fills: a closure whose body builds the place, which its
		// line opens and lines after it close (`.init(api: { scope in`, `holeRouteService: {`).
		let carrierLevelFunction = try! NSRegularExpression(pattern: #"^( *)(@Sendable )?(?:nonisolated )?func __safeDI_\w+\([^)]*\) -> \w+\.__safeDI_\w+Carrier(?:_\w+)?<"#)
		let carrierFillMember = try! NSRegularExpression(pattern: #"(?:\.init\(|, |^ *)\w+: \{(?: \w+ in)?$"#)
		let enclosingDispatcherDeclaration = try! NSRegularExpression(pattern: #"^( *)(@Sendable nonisolated )?func __safeDI_\w+\(_ scope: (\w+)\.SafeDI(?:Sendable)?Scope_\w+(?:\.\w+)?(?:, [^)]*)?\) -> "#)
		// A case holding its fill's body ends its line at the colon; one that calls a fill or a dispatcher returns on its line.
		let inlinedFillCase = try! NSRegularExpression(pattern: #"^( *)case (?:let )?\.[^:]+:$"#)
		func firstMatch(_ expression: NSRegularExpression, in line: String) -> [String]? {
			let range = NSRange(line.startIndex..., in: line)
			guard let match = expression.firstMatch(in: line, range: range) else { return nil }
			return (0..<match.numberOfRanges).map { index in
				Range(match.range(at: index), in: line).map { String(line[$0]) } ?? ""
			}
		}
		for (_, contents) in generatedFiles.sorted(by: { $0.key < $1.key }) where !contents.isEmpty {
			let lines = contents.components(separatedBy: "\n")
			var extendedType: String?
			// A call inside a fill passes the seam's dispatcher, which reaches the fill.
			var dispatcherNamesBySeam = [String: Set<String>]()
			var currentDispatcher: (indentation: String, isSendable: Bool, seam: String)?
			var currentCarrierLevelFunction: (indentation: String, isSendable: Bool)?
			for line in lines {
				if let dispatcher = firstMatch(dispatcherDeclaration, in: line) ?? firstMatch(levelFunctionDeclaration, in: line) {
					dispatcherNamesBySeam[dispatcher[2], default: []].insert(dispatcher[1])
				}
			}
			for (index, line) in lines.enumerated() {
				if firstMatch(enumCaseOfInnerSeam, in: line) != nil {
					features.insert(.passedUpBuilder)
				}
				if line.hasPrefix("extension "), line.hasSuffix(" {") {
					extendedType = String(line.dropFirst("extension ".count).dropLast(2))
				} else if line.hasPrefix("}") {
					extendedType = nil
				}
				if let extendedType, let member = firstMatch(structMemberOfInnerSeam, in: line) ?? firstMatch(carrierMemberOfInnerSeam, in: line), member[1] != extendedType {
					features.insert(.passedUpBuilder)
				}
				if line.contains("init("), firstMatch(builderParameter, in: line) != nil {
					features.insert(.builderParameter)
					if line.contains("@Sendable (SafeDISendableScope_") || line.contains(": SafeDISendableScope_") || line.range(of: #"\b__safeDI_\w+SendableCarrier<"#, options: .regularExpression) != nil {
						features.insert(.sendableBuilder)
					}
					if let extendedType, let match = firstMatch(otherSeamsStruct, in: line), match[1] != extendedType {
						features.insert(.passedUpBuilder)
					}
				}
				if let dispatcher = firstMatch(enclosingDispatcherDeclaration, in: line) {
					currentDispatcher = (indentation: dispatcher[1], isSendable: !dispatcher[2].isEmpty, seam: dispatcher[3])
				}
				// A member closure of a carrier's level function that builds a place is a fill.
				if let levelFunction = firstMatch(carrierLevelFunction, in: line) {
					currentCarrierLevelFunction = (indentation: levelFunction[1], isSendable: !levelFunction[2].isEmpty)
				} else if let levelFunction = currentCarrierLevelFunction, line == levelFunction.indentation + "}" {
					currentCarrierLevelFunction = nil
				}
				if let levelFunction = currentCarrierLevelFunction, firstMatch(carrierFillMember, in: line) != nil {
					features.insert(.fill)
					if levelFunction.isSendable {
						features.insert(.sendableFill)
					}
				}
				// A fill is a function of its own, or the body of the one dispatcher case that calls it.
				let indentation: String
				let fillNames: [String]
				let scopeSeam: String
				let callIndentation: String
				let end: Int
				if let fill = firstMatch(fillDeclaration, in: line) {
					features.insert(.fill)
					if !fill[2].isEmpty {
						features.insert(.sendableFill)
					}
					// The fill's body, up to the line closing it at its indentation, and the call that passes it after it.
					indentation = fill[1]
					fillNames = [fill[3]]
					scopeSeam = fill[4]
					callIndentation = indentation
					guard let fillEnd = lines[(index + 1)...].firstIndex(of: indentation + "}") else { continue }
					end = fillEnd
				} else if let currentDispatcher, let inlinedCase = firstMatch(inlinedFillCase, in: line), inlinedCase[1] == currentDispatcher.indentation + "    " {
					features.insert(.fill)
					if currentDispatcher.isSendable {
						features.insert(.sendableFill)
					}
					indentation = inlinedCase[1]
					fillNames = []
					scopeSeam = currentDispatcher.seam
					callIndentation = currentDispatcher.indentation
					// The case's body, up to the next case or the end of the switch.
					guard let caseEnd = lines[(index + 1)...].firstIndex(where: { $0.hasPrefix(indentation) && !$0.dropFirst(indentation.count).hasPrefix(" ") }) else { continue }
					end = caseEnd
				} else {
					continue
				}
				var namesPassed = fillNames + (dispatcherNamesBySeam[scopeSeam] ?? []).sorted()
				// A dispatcher declared inside the fill, for a seam that passes the site up, whose case forwards to the
				// seam's own dispatcher, passes the fill too.
				for (dispatcherIndex, dispatcherLine) in lines[(index + 1)..<end].enumerated() {
					guard let dispatcher = firstMatch(enclosingDispatcherDeclaration, in: dispatcherLine),
					      let name = firstMatch(dispatcherDeclaration, in: dispatcherLine)?[1]
					else { continue }
					let bodyStart = index + 1 + dispatcherIndex + 1
					let bodyEnd = lines[bodyStart..<end].firstIndex(of: dispatcher[1] + "}") ?? end
					if lines[bodyStart..<bodyEnd].contains(where: { line in namesPassed.contains { line.contains("return \($0)(scope)") } }) {
						namesPassed.append(name)
					}
				}
				// A builder struct converted from a dispatcher calls it with each case its members rebuild (`.init(` on the call's
				// line, its members on the lines after it).
				let passesFill = { (body: String) in
					namesPassed.contains { body.contains(": \($0))") || body.contains(": \($0),") || body.contains(": \($0)())") || body.contains(": \($0)(),") || body.contains(" \($0)(.") }
				}
				let callsInside = lines[(index + 1)..<end].indices.compactMap { callIndex -> String? in
					let line = lines[callIndex]
					guard line.contains("return ") else { return nil }
					var call = line
					if line.hasSuffix(".init(") {
						let callLineIndentation = line.prefix { $0 == " " }
						let closing = lines[(callIndex + 1)..<end].firstIndex { $0.hasPrefix(callLineIndentation + ")") } ?? end
						call = lines[callIndex..<closing].joined(separator: "\n")
					}
					return passesFill(call) ? line : nil
				}
				guard !callsInside.isEmpty else { continue }
				features.insert(.fillPassedToItsSeam)
				let calledInside = callsInside.compactMap { call in call.range(of: "return ").map { String(call[$0.upperBound...].prefix { $0 != "(" }) } }
				// The call the fill is declared for passes the dispatcher that reaches it, not the fill.
				let callAfter = lines[(end + 1)...].first { $0.hasPrefix(callIndentation + "return ") && $0.contains(": __safeDI_") }
				if let callAfter, calledInside.contains(scopeSeam), !callAfter.contains("return \(scopeSeam)(") {
					features.insert(.fillOfPassedUpBuilderPassedToItsSeam)
				}
				if let callAfter, calledInside.contains(where: { $0 != scopeSeam && !callAfter.contains("return \($0)(") }) {
					features.insert(.fillPassedToSeamPassingItsSiteUp)
				}
			}
			// The same call where the fill is a level function: the struct of a fill's own level of seam `S`'s place, which the
			// builder struct of the seam the fill is declared for is over, builds, in a member, the struct of seam `B`, which
			// passes the place up, where `B` is neither `S` nor that seam.
			struct LevelFunction {
				let seam: String
				let structPath: String
				let genericArgument: String
				let calledFunctions: [String]
			}
			var levelFunctionsByName = [String: LevelFunction]()
			for (index, line) in lines.enumerated() {
				guard let function = firstMatch(levelFunction, in: line) else { continue }
				let bodyEnd = lines[(index + 1)...].firstIndex(of: function[1] + "}") ?? lines.count
				let calledFunctions = lines[(index + 1)..<bodyEnd].flatMap { bodyLine in
					calledLevelFunction.matches(in: bodyLine, range: NSRange(bodyLine.startIndex..., in: bodyLine)).compactMap { match in
						Range(match.range(at: 1), in: bodyLine).map { String(bodyLine[$0]) }
					}
				}
				levelFunctionsByName[function[2]] = LevelFunction(seam: function[3], structPath: function[3] + "." + function[4], genericArgument: function[5], calledFunctions: calledFunctions)
			}
			for function in levelFunctionsByName.values {
				let seamsTheFillIsDeclaredFor = Set(levelFunctionsByName.values.filter { $0.genericArgument.hasPrefix(function.structPath + "<") }.map(\.seam))
				guard !seamsTheFillIsDeclaredFor.isEmpty else { continue }
				let calledSeams = function.calledFunctions.compactMap { levelFunctionsByName[$0]?.seam }
				if calledSeams.contains(where: { $0 != function.seam && !seamsTheFillIsDeclaredFor.contains($0) }) {
					features.insert(.fillPassedToSeamPassingItsSiteUp)
				}
			}
		}
		return features
	}

	private static func features(ofPropertyWithAttribute attribute: String, type: String) -> Set<GraphFuzzerFeature> {
		var features = Set<GraphFuzzerFeature>()
		let isErased = attribute.contains("erasedToConcreteExistential: true")
		if type.hasPrefix("Instantiator<") {
			features.insert(.instantiatorProperty)
		} else if type.hasPrefix("SendableInstantiator<") {
			features.insert(.sendableInstantiatorProperty)
		} else if type.hasPrefix("ErasedInstantiator<") {
			features.insert(.erasedInstantiatorProperty)
		} else if type.hasPrefix("SendableErasedInstantiator<") {
			features.insert(.sendableErasedInstantiatorProperty)
		} else if type.hasPrefix("LazilyInstantiated<") || type.hasPrefix("SendableLazilyInstantiated<") {
			if attribute.hasPrefix("@Instantiated") {
				features.insert(isErased ? .erasedLazilyInstantiatedProperty : type.hasPrefix("Sendable") ? .sendableLazilyInstantiatedProperty : .lazilyInstantiatedProperty)
			} else if attribute == "@Forwarded" {
				features.insert(.forwardedLazilyInstantiatedProperty)
			}
		}
		if type.hasPrefix("ErasedInstantiator<") || type.hasPrefix("SendableErasedInstantiator<") {
			if attribute.hasPrefix("@Received") {
				features.insert(.receivedErasedInstantiator)
			} else if attribute == "@Forwarded" {
				features.insert(.forwardedErasedInstantiator)
			}
		}
		if attribute.hasPrefix("@Instantiated"), !type.contains("<") {
			features.insert(isErased ? .erasedConstantProperty : .constantProperty)
		} else if attribute == "@Forwarded" {
			features.insert(type.hasSuffix("?") ? .optionalForwardedProperty : .forwardedProperty)
		} else if attribute == "@Received" {
			features.insert(type.hasSuffix("?") ? .requiredOptionalReceive : .requiredReceive)
		} else if attribute == "@Received(onlyIfAvailable: true)" {
			features.insert(.onlyIfAvailableReceive)
		} else if attribute.hasPrefix("@Received(fulfilledByDependencyNamed:") {
			features.insert(attribute.contains("onlyIfAvailable: true") ? .onlyIfAvailableAlias : .requiredAlias)
			if isErased {
				// No emitted type holds a period, so only an optional `ofType:` argument ends in `?.self`.
				features.insert(attribute.contains("?.self") ? .erasedRenameOfOptionalDependency : .erasedAlias)
			}
		}
		return features
	}

	/// `T` for `LazilyInstantiated<T>` or `SendableLazilyInstantiated<T>`, and otherwise `nil`.
	private static func lazilyInstantiatedInstanceType(of type: String) -> String? {
		for wrapper in ["SendableLazilyInstantiated<", "LazilyInstantiated<"] where type.hasPrefix(wrapper) && type.hasSuffix(">") {
			return String(type.dropFirst(wrapper.count).dropLast())
		}
		return nil
	}

	private static func instantiatedTypeName(attribute: String, type: String) -> String {
		if let fulfilledByTypeRange = attribute.range(of: "fulfilledByType: \"") {
			String(attribute[fulfilledByTypeRange.upperBound...].prefix { $0 != "\"" })
		} else if let genericStart = type.firstIndex(of: "<"), let genericEnd = type.lastIndex(of: ">") {
			String(type[type.index(after: genericStart)..<genericEnd])
		} else {
			type
		}
	}
}

private struct GraphFuzzerInstantiationEdge {
	let source: String
	let target: String
	let isLazy: Bool

	/// Whether a lazy edge closes a cycle: its target reaches its source.
	static func containsLazyCycle(_ edges: [GraphFuzzerInstantiationEdge]) -> Bool {
		edges.contains { edge in
			edge.isLazy && reaches(from: edge.target, to: edge.source, through: edges)
		}
	}

	/// Whether `typeName` is on a cycle that a lazy edge closes.
	static func isOnLazyCycle(_ typeName: String, edges: [GraphFuzzerInstantiationEdge]) -> Bool {
		edges.contains { edge in
			edge.isLazy && reaches(from: edge.target, to: typeName, through: edges) && reaches(from: typeName, to: edge.source, through: edges)
		}
	}

	fileprivate static func reaches(from start: String, to destination: String, through edges: [GraphFuzzerInstantiationEdge]) -> Bool {
		var visited = Set<String>()
		var stack = [start]
		while let current = stack.popLast() {
			guard current != destination else { return true }
			guard visited.insert(current).inserted else { continue }
			stack += edges.filter { $0.source == current }.map(\.target)
		}
		return false
	}
}

/// Which parameters of a graph's seams are received only if available, read from the graph's declarations: a seam's
/// generated initializer spells such a parameter `T?` with no default, as it spells a required parameter of optional
/// type, so only the declarations tell the two apart. The seam's own `@Received(onlyIfAvailable: true)` property is
/// one. A pass-through is one when every receive of its label by a type in the seam's tree – each type the seam builds,
/// followed through `@Instantiated` – is only if available, and is required when every such receive is required or
/// its type is not optional; a receive is a `@Received` property, an alias's fulfilling property, or an
/// `instantiate(…)` parameter, which is required. A label the tree receives both ways is neither, as far as the
/// declarations tell: the receive of the other kind may sit beneath a declaration of the label inside the tree.
struct GraphFuzzerSeamParameterKinds {
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	init(fixture: GraphFuzzerFixture) {
		var ownLabelsBySeam = [String: Set<String>]()
		var ownOnlyIfAvailableLabelsBySeam = [String: Set<String>]()
		var receivesByType = [String: [(label: String, isOnlyIfAvailable: Bool)]]()
		var builtTypeNamesByType = [String: Set<String>]()
		for content in fixture.swiftFileContent {
			var nextTypeIsSeam = false
			var nextTypeIsMockOnly = false
			// The type whose declarations follow, or `nil` after an `@Instantiable` attribute until the declaration it
			// decorates: a `mockOnly` declaration, or one `GraphFuzzerSourceLine` does not read, receives nothing in a tree.
			var currentType: String?
			var currentTypeIsSeam = false
			for line in GraphFuzzerSourceLine.lines(of: content) {
				switch line {
				case let .instantiableAttribute(arguments):
					nextTypeIsSeam = arguments.contains("generateDependencyTree: true")
					nextTypeIsMockOnly = arguments.contains("mockOnly: true")
					currentType = nil
				case let .typeDeclaration(name):
					currentType = nextTypeIsMockOnly ? nil : name
					currentTypeIsSeam = nextTypeIsSeam
					nextTypeIsSeam = false
					nextTypeIsMockOnly = false
				case let .instantiateMethod(parameters):
					guard let currentType else { continue }
					for parameter in GraphFuzzerOracle.topLevelParameters(parameters) where !parameter.contains(" = ") {
						if let name = parameter.prefix(while: { $0 != ":" }).split(separator: " ").last {
							receivesByType[currentType, default: []].append((String(name), false))
						}
					}
				case let .property(attribute, label, type):
					guard let currentType else { continue }
					let isOnlyIfAvailable = attribute.contains("onlyIfAvailable: true")
					if attribute.hasPrefix("@Instantiated") {
						// By its last component, as a type declared in an extension of a namespace is declared.
						let builtTypeName = GraphFuzzerFeature.builtTypeName(ofPropertyWithAttribute: attribute, type: type)
						builtTypeNamesByType[currentType, default: []].insert(String(builtTypeName.split(separator: ".").last ?? Substring(builtTypeName)))
					} else if let range = attribute.range(of: "fulfilledByDependencyNamed: \"") {
						receivesByType[currentType, default: []].append((String(attribute[range.upperBound...].prefix { $0 != "\"" }), isOnlyIfAvailable))
					} else if attribute.hasPrefix("@Received") {
						// A seam's own receive is a receive of the seams whose trees build it, which pass it through.
						receivesByType[currentType, default: []].append((label, isOnlyIfAvailable))
						if currentTypeIsSeam {
							ownLabelsBySeam[currentType, default: []].insert(label)
							if isOnlyIfAvailable {
								ownOnlyIfAvailableLabelsBySeam[currentType, default: []].insert(label)
							}
						}
					} else if attribute == "@Forwarded", currentTypeIsSeam {
						ownLabelsBySeam[currentType, default: []].insert(label)
					}
				case .other:
					break
				}
			}
		}
		self.ownLabelsBySeam = ownLabelsBySeam
		self.ownOnlyIfAvailableLabelsBySeam = ownOnlyIfAvailableLabelsBySeam
		self.receivesByType = receivesByType
		self.builtTypeNamesByType = builtTypeNamesByType
	}

	/// Whether the parameter `label` of the seam named `seamTypeName` is received only if available.
	func isOnlyIfAvailable(label: String, ofSeam seamTypeName: String) -> Bool {
		if ownLabelsBySeam[seamTypeName, default: []].contains(label) {
			ownOnlyIfAvailableLabelsBySeam[seamTypeName, default: []].contains(label)
		} else {
			kindsOfReceives(of: label, inTreeOf: seamTypeName) == [true]
		}
	}

	/// Whether the parameter `label: type` of the seam named `seamTypeName` is a pass-through some receiver requires.
	func isRequiredPassThrough(label: String, type: String, ofSeam seamTypeName: String) -> Bool {
		guard !ownLabelsBySeam[seamTypeName, default: []].contains(label) else { return false }
		return !type.hasSuffix("?") || kindsOfReceives(of: label, inTreeOf: seamTypeName) == [false]
	}

	/// Whether each receive of `label` by a type in the tree of the seam named `seamTypeName` is only if available: the
	/// seam itself, for its aliases, and each type it builds, followed through `@Instantiated`.
	private func kindsOfReceives(of label: String, inTreeOf seamTypeName: String) -> Set<Bool> {
		var kinds = Set<Bool>()
		var visited = Set<String>()
		var typeNamesToVisit = [seamTypeName]
		while let typeName = typeNamesToVisit.popLast() {
			guard visited.insert(typeName).inserted else { continue }
			for receive in receivesByType[typeName, default: []] where receive.label == label {
				kinds.insert(receive.isOnlyIfAvailable)
			}
			typeNamesToVisit.append(contentsOf: builtTypeNamesByType[typeName, default: []])
		}
		return kinds
	}

	private let ownLabelsBySeam: [String: Set<String>]
	private let ownOnlyIfAvailableLabelsBySeam: [String: Set<String>]
	/// The receives each type declares.
	private let receivesByType: [String: [(label: String, isOnlyIfAvailable: Bool)]]
	private let builtTypeNamesByType: [String: Set<String>]
}

/// One line of a generated fixture, in the shape `GraphFuzzerGenerator` emits it.
enum GraphFuzzerSourceLine: Equatable {
	case instantiableAttribute(arguments: String)
	/// A `public final class` or an `extension … : Instantiable` that an `@Instantiable` attribute decorates.
	case typeDeclaration(name: String)
	/// An extension's `instantiate(…)` method, with the source of its parameters.
	case instantiateMethod(parameters: String)
	case property(attribute: String, label: String, type: String)
	case other

	var declaredTypeName: String? {
		switch self {
		case let .typeDeclaration(name):
			name
		case .instantiableAttribute, .instantiateMethod, .property, .other:
			nil
		}
	}

	/// `line` without the access modifier it begins with, or `line` itself when it begins with none. `nil` never: the
	/// optional lets a condition bind it.
	private static func droppingAccessModifier(from line: String) -> Substring? {
		// A global actor precedes the access modifier, as `GraphFuzzerPublicMockDraw` spells it.
		let line = line.hasPrefix("@MainActor ") ? String(line.dropFirst("@MainActor ".count)) : line
		for modifier in ["public ", "package ", "internal "] where line.hasPrefix(modifier) {
			return line.dropFirst(modifier.count)
		}
		return Substring(line)
	}

	/// The names of the `actor` types `@Instantiable` attributes decorate in `contents`, which only `addingActorArgumentShapes`
	/// draws.
	static func actorTypeNames(in contents: [String]) -> Set<String> {
		var names = Set<String>()
		for content in contents {
			var previousLineWasInstantiableAttribute = false
			for rawLine in content.split(separator: "\n", omittingEmptySubsequences: false) {
				let line = rawLine.trimmingCharacters(in: .whitespaces)
				if previousLineWasInstantiableAttribute, let declaration = droppingAccessModifier(from: line), declaration.hasPrefix("actor ") {
					names.insert(String(declaration.dropFirst("actor ".count).prefix { $0.isLetter || $0.isNumber || $0 == "_" }))
				}
				previousLineWasInstantiableAttribute = line.hasPrefix("@Instantiable")
			}
		}
		return names
	}

	static func lines(of content: String) -> [GraphFuzzerSourceLine] {
		var lines = [GraphFuzzerSourceLine]()
		var previousLineWasInstantiableAttribute = false
		for rawLine in content.split(separator: "\n", omittingEmptySubsequences: false) {
			let line = rawLine.trimmingCharacters(in: .whitespaces)
			let parsedLine: GraphFuzzerSourceLine
			if line.hasPrefix("@Instantiable") {
				parsedLine = .instantiableAttribute(arguments: String(line.dropFirst("@Instantiable".count)))
			} else if previousLineWasInstantiableAttribute, let declaration = droppingAccessModifier(from: line), let keyword = ["final class ", "actor "].first(where: { declaration.hasPrefix($0) }) {
				// Only `addingActorArgumentShapes` draws an actor, so reading one changes no other graph's files or model.
				let name = declaration.dropFirst(keyword.count).prefix { $0.isLetter || $0.isNumber || $0 == "_" }
				parsedLine = .typeDeclaration(name: String(name))
			} else if previousLineWasInstantiableAttribute, let declaration = droppingAccessModifier(from: line), declaration.hasPrefix("extension ") {
				// The extended type's last component: a nested extended type's file is named after it.
				let extendedType = declaration.dropFirst("extension ".count).prefix { $0.isLetter || $0.isNumber || $0 == "_" || $0 == "." }
				parsedLine = .typeDeclaration(name: String(extendedType.split(separator: ".").last ?? extendedType))
			} else if let declaration = droppingAccessModifier(from: line), declaration.hasPrefix("static func instantiate("), let parametersEnd = declaration.range(of: ") -> ", options: .backwards) {
				parsedLine = .instantiateMethod(parameters: String(declaration[declaration.index(declaration.startIndex, offsetBy: "static func instantiate(".count)..<parametersEnd.lowerBound]))
			} else if line.hasPrefix("@Instantiated") || line.hasPrefix("@Received") || line.hasPrefix("@Forwarded"),
			          let letRange = line.range(of: " let ", options: .backwards),
			          let colonIndex = line[letRange.upperBound...].firstIndex(of: ":")
			{
				parsedLine = .property(
					attribute: String(line[..<letRange.lowerBound]),
					label: String(line[letRange.upperBound..<colonIndex]),
					type: line[line.index(after: colonIndex)...].trimmingCharacters(in: .whitespaces),
				)
			} else {
				parsedLine = .other
			}
			lines.append(parsedLine)
			if case .instantiableAttribute = parsedLine {
				previousLineWasInstantiableAttribute = true
			} else {
				previousLineWasInstantiableAttribute = false
			}
		}
		return lines
	}
}

// MARK: - Oracle

/// One way two outcomes of the tool differ.
struct GraphFuzzerOutcomeDifference: Equatable {
	/// What differs, which is how a known issue names a difference. A generated file's code is classified in one place,
	/// `aspects(ofCodeInFileNamed:code:otherCode:comparedBy:)`, so a finer shape of a file's difference is one more case
	/// and one more branch there.
	enum Aspect: String, Equatable {
		case verdict = "its verdict"
		case diagnostics = "its diagnostics"
		case generatedFileNames = "the names of its generated files"
		case unreadTypeComments = "the comments naming the types it counts as `public` because it reads no declaration of them"
		/// A generated mock file's code differs, in a way neither of the two known reasons explains.
		case mockCode = "its generated mock code"
		/// The generated configuration file's code differs, in a way neither of the two known reasons explains.
		case mockConfigurationCode = "its generated mock configuration code"
		/// A mock's parameters or fields hold the same content in another order, in a mock's file or the configuration file.
		case mockParameterAndFieldOrder = "the order of its generated mock's parameters and fields"
		/// A configuration struct's field is present in one outcome and absent from the other, in a mock's file or the
		/// configuration file, along with the reads of it.
		case mockConfigurationFieldPresence = "which configuration fields its generated mock has"
		case dependencyTreeCode = "its generated dependency tree code"
		/// A dependency tree file's code holds the same items of its lists in another order, under a renaming that reorders
		/// type names or labels: the order of the lists SafeDI sorts by label, such as a seam's builders and pass-throughs.
		/// Compared with the items of each list and each block sorted, recursively (`listsInCanonicalOrder(of:)`), so only
		/// siblings within one list or one block may move: a seam's builders and pass-throughs, the declarations and cases
		/// of its builders, and the statements that bind its values, across line boundaries too. Only while that code, with its
		/// renaming undone, compiles with the graph and ends its value comparison as the graph's own does; otherwise the
		/// difference is the file's code (`GraphFuzzerToolRuns.renamedGraphFailures(refutingOrderOf:)`). That check alone
		/// judges what the sorted form also finds equal: a statement moved between two `case` bodies of one `switch`, and
		/// swapped unlabeled arguments.
		case dependencyTreeListOrder = "the order of the label-sorted lists in its generated dependency tree code"
		case warnings = "its warnings"
	}

	let aspect: Aspect
	/// The generated file whose code differs, when `aspect` is the code of a file.
	var fileName: String?
	/// Whether the file's code, compared byte for byte, differs in nothing but the order of its extensions.
	var differsOnlyInOrderOfExtensions = false

	var description: String {
		if let fileName {
			"\(aspect.rawValue)\(differsOnlyInOrderOfExtensions ? " (the order of its extensions only)" : ""), in \(fileName)"
		} else {
			aspect.rawValue
		}
	}

	/// The aspects of the difference between `code` and `otherCode`, the code of the generated file named `fileName` in
	/// each outcome: one for each known reason a mock file's difference shows, the order of a dependency tree file's
	/// label-sorted lists where `renaming` reorders type names or labels and nothing but order differs
	/// (`dependencyTreeListOrder`), or, when anything else differs, the aspect of the file's code as a whole, which no
	/// shape that names a reason documents.
	static func aspects(ofCodeInFileNamed fileName: String, code: String, otherCode: String, comparedBy mockDifference: GraphFuzzerMockDifference, renaming: GraphFuzzerRenaming?) -> [Aspect] {
		let codeAspect: Aspect = if fileName.hasSuffix("+SafeDIMock.swift") {
			.mockCode
		} else if fileName.hasSuffix("SafeDIMockConfiguration.swift") {
			.mockConfigurationCode
		} else {
			.dependencyTreeCode
		}
		guard codeAspect != .dependencyTreeCode else {
			// A renaming of file names alone moves no label sort, so it never explains a difference of order.
			guard let renaming, renaming.changesOrderOfTypeNames || renaming.reversesLabels, listsInCanonicalOrder(of: code) == listsInCanonicalOrder(of: otherCode) else {
				return [codeAspect]
			}
			return [.dependencyTreeListOrder]
		}
		let reasons = mockDifference.reasons(forDifferenceBetween: code, and: otherCode).map { reason -> Aspect in
			switch reason {
			case .orderOfParametersAndFields:
				.mockParameterAndFieldOrder
			case .presenceOfConfigurationFields:
				.mockConfigurationFieldPresence
			}
		}
		return reasons.isEmpty ? [codeAspect] : reasons
	}

	/// `code` with the items of each of its lists and blocks in sorted order: each balanced `(…)`, `[…]` and generic `<…>`
	/// group split at its own top-level commas, and each `{…}` block split at its own newlines and semicolons into its
	/// declarations and statements (a multi-line one, whose other lines are inside a nested group or block, stays one
	/// item, as does an `#if` region with everything up to its `#endif` and a `#sourceLocation(file:…)` run up to its
	/// `#sourceLocation()`), each item put in this form itself and trimmed,
	/// and the items sorted, while everything outside the groups and blocks keeps its order. So two files compare equal
	/// when they differ only in the order of siblings within one list or one block, recursively: an item moved to
	/// another list or block, a value swapped between two calls, a changed nesting, a respelled type or a value moved to
	/// another label still differs. Some moves this form finds equal are not sibling order: a statement moved from one
	/// `case` body of a `switch` to another, whose lines are siblings of the block, and swapped unlabeled arguments or case
	/// bindings, items of one list. Those, with statement order inside one block, are left to a check apart: a renamed graph
	/// whose code this form finds equal is compiled, with its renaming undone, with the graph, and compared with the graph's
	/// own code by its values, and must end as the graph's own comparison does
	/// (`GraphFuzzerOracle.listOrderRefutation(of:by:)`), so a use before a declaration, or a move that changes what is
	/// built, is the file's code (`GraphFuzzerToolRuns.renamedGraphFailures(refutingOrderOf:)`). A run without compile
	/// verification makes no such check. A run of whitespace that holds a newline reads as one space inside a list.
	static func listsInCanonicalOrder(of code: String) -> String {
		var canonicalizer = GraphFuzzerListOrderCanonicalizer(characters: Array(code))
		return canonicalizer.sequence()
	}
}

/// Puts a generated file's lists and blocks in canonical order (`GraphFuzzerOutcomeDifference.listsInCanonicalOrder(of:)`).
private struct GraphFuzzerListOrderCanonicalizer {
	let characters: [Character]
	var index = 0

	/// The text from `index` to the end, its groups and blocks in canonical form.
	mutating func sequence() -> String {
		var text = ""
		while index < characters.count {
			appendNext(to: &text)
		}
		return text
	}

	/// Appends the character at `index`, or the canonical form of the group or block it opens, to `text`, and moves past
	/// it. A run of whitespace that holds a newline is appended as one space.
	private mutating func appendNext(to text: inout String) {
		let character = characters[index]
		if let closer = closer(openedAt: index) {
			let start = index
			index += 1
			if let contents = closer == "}" ? block(isArgumentNamedByLabel: text.hasSuffix(": ")) : group(closedBy: closer) {
				text += "\(character)\(contents)\(closer)"
				return
			}
			// Not a group: the opener is text, and the scan resumes after it.
			index = start + 1
			text.append(character)
		} else if character.isWhitespace {
			let run = whitespaceRun()
			text += run.contains(where: \.isNewline) ? " " : run
		} else {
			text.append(character)
			index += 1
		}
	}

	/// The run of whitespace at `index`, moving past it.
	private mutating func whitespaceRun() -> String {
		var run = ""
		while index < characters.count, characters[index].isWhitespace {
			run.append(characters[index])
			index += 1
		}
		return run
	}

	/// The closer of the group or block the character at `position` opens, or `nil`: `(`, `[` and `{` always open one, and
	/// `<` where it follows a name, as a generic argument list does.
	private func closer(openedAt position: Int) -> Character? {
		switch characters[position] {
		case "(":
			")"
		case "[":
			"]"
		case "{":
			"}"
		case "<":
			position > 0 && (characters[position - 1].isLetter || characters[position - 1].isNumber || characters[position - 1] == "_") ? ">" : nil
		default:
			nil
		}
	}

	/// The items of the group whose opener `index` follows, sorted and joined, with `index` moved past `closer`; or `nil`
	/// where no `closer` balances it: a generic argument list ends at a newline or a brace.
	private mutating func group(closedBy closer: Character) -> String? {
		var items = [String]()
		var item = ""
		while index < characters.count {
			let character = characters[index]
			if character == closer, closer != ">" || characters[index - 1] != "-" {
				index += 1
				items.append(item.trimmingCharacters(in: .whitespaces))
				return items.sorted().joined(separator: ", ")
			} else if character == "," {
				items.append(item.trimmingCharacters(in: .whitespaces))
				item = ""
				index += 1
			} else if ")]}".contains(character) || (closer == ">" && (character == "{" || character.isNewline)) {
				return nil
			} else {
				appendNext(to: &item)
			}
		}
		return nil
	}

	/// The items of the block whose `{` `index` follows, an `#if` region joined into one, sorted and joined, with `index`
	/// moved past its `}`; or `nil` where no `}` balances it. A block passed under an argument label
	/// (`isArgumentNamedByLabel`) may be a caller's closure for a carrier's member, whose parameter names are sorted.
	private mutating func block(isArgumentNamedByLabel: Bool = false) -> String? {
		var items = [String]()
		var item = ""
		while index < characters.count {
			let character = characters[index]
			if character == "}" {
				index += 1
				items.append(item.trimmingCharacters(in: .whitespaces))
				if isArgumentNamedByLabel, let first = items.first {
					items[0] = Self.carrierMemberClosureParametersInCanonicalOrder(of: first)
				}
				return Self.joiningRegions(of: items.filter { !$0.isEmpty }).sorted().joined(separator: "; ")
			} else if character == ";" {
				items.append(item.trimmingCharacters(in: .whitespaces))
				item = ""
				index += 1
			} else if character == ")" || character == "]" {
				return nil
			} else if character.isWhitespace {
				let run = whitespaceRun()
				if run.contains(where: \.isNewline) {
					items.append(item.trimmingCharacters(in: .whitespaces))
					item = ""
				} else {
					item += run
				}
			} else {
				appendNext(to: &item)
			}
		}
		return nil
	}

	/// `item`, the first item of a closure passed under an argument label, with the names of its parameter clause sorted
	/// where it is a caller's closure for a carrier's member (`{ scope_a, scope_b, scope in`): every name is a payload
	/// name `P` joined with a value's label, `P_<label>` (`SeamHoles.argumentName(of:inPayloadNamed:)`), for one `P`, or `P`
	/// itself, the run struct. Such a member takes a level's values positionally in the order the level binds them, which
	/// for a seam's root is its pass-throughs' label order: the label sort of equivalent parameters `CLAUDE.md`'s "What may
	/// follow names" allows. No other list is touched: a closure whose names are not of that form, or that is not passed
	/// under a label, keeps its order, and swapped names are left to the compile and value check, as swapped unlabeled
	/// arguments are.
	private static func carrierMemberClosureParametersInCanonicalOrder(of item: String) -> String {
		guard let inRange = item.range(of: " in"), inRange.upperBound == item.endIndex || item[inRange.upperBound] == " " else {
			return item
		}
		let names = item[..<inRange.lowerBound].components(separatedBy: ", ")
		guard names.count > 1,
		      names.allSatisfy({ name in name.allSatisfy { $0.isLetter || $0.isNumber || $0 == "_" } && name.first?.isLetter == true }),
		      let payloadName = names.first(where: { $0.contains("_") }).map({ String($0.prefix { $0 != "_" }) }),
		      names.allSatisfy({ $0 == payloadName || ($0.hasPrefix(payloadName + "_") && $0.count > payloadName.count + 1) })
		else {
			return item
		}
		return names.sorted().joined(separator: ", ") + item[inRange.lowerBound...]
	}

	/// `items` with each `#if` item and those after it up to its `#endif`, and each `#sourceLocation(file:…)` item and those
	/// after it up to the `#sourceLocation()` that ends it, joined into one, in their order.
	private static func joiningRegions(of items: [String]) -> [String] {
		var joined = [String]()
		var region = [String]()
		var depth = 0
		for item in items {
			let opensRegion = item.hasPrefix("#if") || (item.hasPrefix("#sourceLocation(") && item != "#sourceLocation()")
			if opensRegion {
				depth += 1
			}
			if depth > 0 {
				region.append(item)
			} else {
				joined.append(item)
			}
			if item.hasPrefix("#endif") || item == "#sourceLocation()", depth > 0 {
				depth -= 1
				if depth == 0 {
					joined.append(region.joined(separator: "; "))
					region = []
				}
			}
		}
		return joined + region
	}
}

/// What one run of SafeDITool did with a graph, with the per-run fixture directory replaced by a placeholder so
/// two runs compare equal exactly when they produced the same diagnostics and code.
enum GraphFuzzerToolOutcome: Equatable {
	case rejected(diagnostics: String)
	case accepted(generatedFiles: [String: String], warnings: [String])

	/// How the code of a file both outcomes generated is compared.
	enum CodeComparison {
		case byteForByte
		/// Byte for byte, but for the order of the file's extensions, across `#if` blocks of exactly one condition too: the
		/// order a renamed graph may change, which is presentation and changes nothing a user does.
		case inAnyOrderOfExtensions
	}

	/// Every aspect in which two outcomes differ, or nothing when they agree: their verdict or their diagnostics in any
	/// order; or the names of their generated files, the code of each file both generated (compared as `codeComparison`
	/// says), and their warnings in any order, each a difference of its own. Paths to fixture files are compared by file
	/// name, and the suggestions a diagnostic lists ("Did you mean one of …"), the forms of a label one cycle parameter cannot
	/// carry, and the declarations it lists as proving a type's access, in any order: the order inside a message is
	/// presentation and changes nothing a user does.
	/// - Parameter renaming: The renaming that separates the two outcomes, which decides which known reason can explain a
	///   mock's difference (`GraphFuzzerMockDifference`). With none, neither can, and the difference is the file's code.
	/// - Parameter fixture: The graph both outcomes are of, whose types can decide which field of a lazy cycle a mock drops
	///   though no generated code names them.
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	static func differences(between outcome: GraphFuzzerToolOutcome, and otherOutcome: GraphFuzzerToolOutcome, comparingCode codeComparison: CodeComparison = .byteForByte, renaming: GraphFuzzerRenaming? = nil, of fixture: GraphFuzzerFixture? = nil) -> [GraphFuzzerOutcomeDifference] {
		// A seam's guard enum is named after a hash of its signature, which names its parameters' types, so a
		// renaming changes it as it changes the types: a hash restored textually cannot match, and is reduced away, to
		// what is still an identifier, so that the code still parses.
		let reduce = { (text: String) in
			GraphFuzzerRenaming.reducingFixturePathsToFileNames(in: text)
				.replacingOccurrences(of: #"(__safeDI_[A-Za-z0-9_]+_)[0-9A-F]{16}\b"#, with: "$1hash", options: .regularExpression)
		}
		// A run without a target graph writes one comment per combined output, above the first `public` declaration that
		// names a type SafeDI counts as `public` because it reads no declaration of it. Which declaration is first follows
		// the order of type names, so the comment can move to another of the module's files: each module's count of them is
		// compared, and their places are not.
		func isUnreadTypeComment(_ line: Substring) -> Bool {
			line.trimmingCharacters(in: .whitespaces).hasPrefix(GraphFuzzerOracle.unreadTypeCommentPrefix)
		}
		// A module with no such comment has no count, so a file only one outcome generates is only a difference in names.
		func unreadTypeCommentCountsByModule(_ generatedFiles: [String: String]) -> [Substring: Int] {
			generatedFiles.reduce(into: [Substring: Int]()) { counts, file in
				counts[file.key.prefix { $0 != "/" }, default: 0] += file.value.split(separator: "\n").filter(isUnreadTypeComment).count
			}.filter { $0.value > 0 }
		}
		func withoutUnreadTypeComments(_ code: String) -> String {
			code.split(separator: "\n", omittingEmptySubsequences: false).filter { !isUnreadTypeComment($0) }.joined(separator: "\n")
		}
		switch (outcome, otherOutcome) {
		case let (.rejected(diagnostics), .rejected(otherDiagnostics)):
			return diagnosticEntries(of: reduce(diagnostics)) == diagnosticEntries(of: reduce(otherDiagnostics)) ? [] : [GraphFuzzerOutcomeDifference(aspect: .diagnostics)]
		case let (.accepted(generatedFiles, warnings), .accepted(otherGeneratedFiles, otherWarnings)):
			var differences = [GraphFuzzerOutcomeDifference]()
			lazy var mockDifference = GraphFuzzerMockDifference(generatedFiles: generatedFiles, otherGeneratedFiles: otherGeneratedFiles, renaming: renaming, instantiableTypeNames: fixture?.instantiableTypeNames ?? [])
			if Set(generatedFiles.keys) != Set(otherGeneratedFiles.keys) {
				differences.append(GraphFuzzerOutcomeDifference(aspect: .generatedFileNames))
			}
			if unreadTypeCommentCountsByModule(generatedFiles) != unreadTypeCommentCountsByModule(otherGeneratedFiles) {
				differences.append(GraphFuzzerOutcomeDifference(aspect: .unreadTypeComments))
			}
			for fileName in Set(generatedFiles.keys).intersection(otherGeneratedFiles.keys).sorted() {
				let code = reduce(withoutUnreadTypeComments(generatedFiles[fileName, default: ""]))
				let otherCode = reduce(withoutUnreadTypeComments(otherGeneratedFiles[fileName, default: ""]))
				// By their UTF-8, since `String`'s `!=` calls canonically equivalent spellings equal while Swift reads them as two names.
				guard !code.utf8.elementsEqual(otherCode.utf8) else { continue }
				let differsOnlyInOrderOfExtensions = GraphFuzzerExtensionOrder.sortingExtensionsWithinTheirPlaces(in: code) == GraphFuzzerExtensionOrder.sortingExtensionsWithinTheirPlaces(in: otherCode)
				guard codeComparison == .byteForByte || !differsOnlyInOrderOfExtensions else { continue }
				differences += GraphFuzzerOutcomeDifference.aspects(ofCodeInFileNamed: fileName, code: code, otherCode: otherCode, comparedBy: mockDifference, renaming: renaming).map { aspect in
					GraphFuzzerOutcomeDifference(aspect: aspect, fileName: fileName, differsOnlyInOrderOfExtensions: differsOnlyInOrderOfExtensions)
				}
			}
			if warnings.sorted() != otherWarnings.sorted() {
				differences.append(GraphFuzzerOutcomeDifference(aspect: .warnings))
			}
			return differences
		case (.accepted, .rejected), (.rejected, .accepted):
			return [GraphFuzzerOutcomeDifference(aspect: .verdict)]
		}
	}

	/// The first of `differences(between:and:comparingCode:)`, with code compared byte for byte, described, or `nil` when
	/// the outcomes agree.
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	static func difference(between outcome: GraphFuzzerToolOutcome, and otherOutcome: GraphFuzzerToolOutcome) -> String? {
		differences(between: outcome, and: otherOutcome).first?.description
	}

	/// The diagnostics, each with the notes after it, in any order, and with its suggestions sorted, sorted. A note is a
	/// diagnostic of its own at its own location, which says all it means, so no note's place among an error's notes
	/// carries meaning: SafeDI emits them in source order (a file-name reversal swaps them), in name order, or along a
	/// cycle whose chain the error itself spells. Each note keeps the lines that follow it, its fix-its, and the lines
	/// before an error's first note stay with the error.
	static func diagnosticEntries(of diagnostics: String) -> [String] {
		var entries = [[[Substring]]]()
		for line in diagnostics.split(separator: "\n", omittingEmptySubsequences: false) {
			if line.contains(": error: ") || line.contains(": warning: ") || entries.isEmpty {
				entries.append([[line]])
			} else if line.contains(": note: ") {
				entries[entries.count - 1].append([line])
			} else {
				entries[entries.count - 1][entries[entries.count - 1].count - 1].append(line)
			}
		}
		return entries.map { groups in
			let head = groups[0].joined(separator: "\n")
			let notes = groups.dropFirst().map { $0.joined(separator: "\n") }.sorted()
			return sortingSuggestions(in: ([head] + notes).joined(separator: "\n"))
		}.sorted()
	}

	/// `diagnostic` with the items of each list of suggestions it makes – "Did you mean one of `a: A`, `b: B`?",
	/// which SafeDI sorts by `Property.<` – and of each parenthesized list of the declarations that prove a seam
	/// parameter's access – "(`Host.init(key:seam:)`, `Vault.init(key:)`)", which SafeDI lists in source order, so a
	/// file-name reversal reorders them – and of the two lists of the forms of a label one cycle parameter cannot carry
	/// ("receive `x` as `x: X?` and `x: LazilyInstantiated<X>?`, which one value cannot carry together. Receive `x: X?`
	/// and `x: LazilyInstantiated<X>?` under different labels to fix.", `unpassableCycleLabel`), and of each list of the
	/// places one fill finding holds for ("the builders for `A`’s `x: X` (`x` of `xBuilder`) and `B`’s `y: Y`",
	/// "the builder `Seam` takes for `A`’s `x: X`, `B`’s `y: Y`, and `B`’s `z: Z` on unchanged", `FillFinding`), each of
	/// which SafeDI lists in the order of their types' names, and of each list of the types a `@Sendable` capture error
	/// tells to declare a wrapper `Sendable` ("Declare `x` on `A`, `B`, and `C`, and this property, as
	/// `SendableInstantiator<X>` to fix."), which SafeDI lists in source order, so a file-name reversal reorders them,
	/// and of the lists a merged fill finding prints, in name
	/// order: the seams whose calls present its places ("which `Mid` builds where it calls `Hub` and `Hub2`, but"), the
	/// seams a remedy names ("Declare `@Received let tag: Tag` on `Hub` and `Hub2`, so SafeDI hands it to the builders"), its
	/// fulfil remedies ("declare an @Instantiable type that fulfills `Api` in module `Middle` or a module it lists among its
	/// SafeDI dependencies, so `Mid` fills the builders itself, and declare … that fulfills `Gadget` …", `boundByPassingUpSeam`),
	/// and, where a declaration hides a value on the paths to a call that re-enters a seam
	/// (`declarationBoundOnPathToReenteringCall`), its clauses ("which `MiddleAlpha` declares on the path from the builder
	/// for `Profile`’s `router: any Router` (`router` of `routerBuilder`) to the call by which
	/// `MiddleAlpha` instantiates `Flow` again (`flowBuilder`) and `MiddleZed` declares …, but"), each clause's places, and
	/// its declaring types ("cannot hand it `MiddleAlpha`’s and `MiddleZed`’s values"), and, where a fill's seam opened again
	/// loses a value (`fieldOfReenteringPlace`), the types the places carry it from ("carries from `AScreen` and `BScreen`,
	/// and"), the calls that open it again ("instantiates `Seam` again (`aBuilder` and `bBuilder`)", or, through seams that
	/// build it, "instantiates `ARelay` and `BRelay` (`aBuilder` and `bBuilder`), which instantiate `Seam` again", or both,
	/// the direct call first: "instantiates `Seam` again (`seamBuilder`) and `ARelay` and `BRelay` (`aBuilder` and
	/// `bBuilder`), which instantiate `Seam` again"), and the alternatives inline reads ("would read `AScreen`’s or
	/// `BScreen`’s `id` inside that `Seam`", the seam built again) – sorted as text, each item in its
	/// place among the list's separators, so two diagnostics that list the same items in another order compare equal, and
	/// any other difference, including an item added, removed or changed, still tells them apart. A place keeps its owner,
	/// its case and the seam whose tree holds it in one item, so a place moved to another seam's tree still differs; a
	/// list inside a clause is sorted before the clauses are. A new merged message adds its lists here.
	private static func sortingSuggestions(in diagnostic: String) -> String {
		// Each item is a property's or a declaration's source between backticks, and no fuzzer label or type contains one.
		let backtickedItem = "`[^`]*`"
		// A place is the type that declares it and its property, then the member of the builder that holds it
		// and the seam whose tree holds it, where the message names them.
		let place = "`[^`]*`’s `[^`]*`(?: \\(`[^`]*` of `[^`]*`\\))?(?: in `[^`]*`’s tree)?"
		let separator = "(?:, and |, | and )"
		// A remedy that fulfills one type of a merged fill finding's places.
		let fulfillRemedy = "declare an @Instantiable type that fulfills `[^`]*` in (?:module `[^`]*`|this module) or a module it lists among its SafeDI dependencies, so `[^`]*` fills the builders? itself"
		// A clause of a declaration that hides a value on the paths from its places to a call that re-enters a seam: a call of
		// the seam itself, or of a seam that builds it, such as one that passes its place up.
		let reenteringCallClause = "`[^`]*` declares on the paths? from the builders? for \(place)(?:\(separator)\(place))* to the call by which `[^`]*` instantiates `[^`]*`(?: again \\(`[^`]*`\\)| \\(`[^`]*`\\), which instantiates `[^`]*` again)"
		var diagnostic = diagnostic
		for (list, item) in [
			("(?<=Did you mean one of )`[^`]*`(?:, `[^`]*`)+(?=\\?)", backtickedItem),
			("(?<=\\()`[^`]*`(?:, `[^`]*`)+(?=\\))", backtickedItem),
			("(?<= as )`[^`]*`(?:(?:, and |, | and )`[^`]*`)+(?=, which one value cannot carry together\\.)", backtickedItem),
			("(?<=which one value cannot carry together\\. Receive )`[^`]*`(?:(?:, and |, | and )`[^`]*`)+(?= under different labels to fix\\.)", backtickedItem),
			("(?<=builder for |builders for |takes for )\(place)(?:(?:, and |, | and )\(place))+", place),
			("(?<= calls )`[^`]*`(?:\(separator)`[^`]*`)+(?=, but |, because )", backtickedItem),
			("(?<= on )`[^`]*`(?:\(separator)`[^`]*`)+(?=, so SafeDI hands )", backtickedItem),
			("\(fulfillRemedy)(?:\(separator)\(fulfillRemedy))+", fulfillRemedy),
			("(?<=, which )\(reenteringCallClause)(?:\(separator)\(reenteringCallClause))+(?=, but )", reenteringCallClause),
			("(?<=cannot hand it |cannot hand them )`[^`]*`’s(?:\(separator)`[^`]*`’s)+(?= values)", "`[^`]*`’s"),
			// The error about a value a fill's seam, opened again, loses (`fieldOfReenteringPlace`): the types the places carry
			// the value from, the seams their fills open again and the calls that open them, the types whose value inline
			// reads, and the seams inline reads it inside. The seams its remedy declares the value on are the remedy's list
			// above.
			("(?<= carries from | carry from )`[^`]*`(?:\(separator)`[^`]*`)+(?=, and )", backtickedItem),
			("(?<= instantiates )`[^`]*`(?:\(separator)`[^`]*`)+(?= again \\(| \\(`)", backtickedItem),
			// The seams that build it, after a direct call of it.
			("(?<=\\) and )`[^`]*`(?:\(separator)`[^`]*`)+(?= \\(`[^`]*`(?:\(separator)`[^`]*`)*\\), which instantiate )", backtickedItem),
			("(?<= again \\(|` \\()`[^`]*`(?:\(separator)`[^`]*`)+(?=\\))", backtickedItem),
			("(?<=would read )`[^`]*`’s(?:(?:, or |, | or )`[^`]*`’s)+(?= `)", "`[^`]*`’s"),
			("(?<=inside that )`[^`]*`(?:(?:, or |, | or )`[^`]*`)+(?=, but )", backtickedItem),
			("(?<=` on )`[^`]*`(?:(?:, and |, | and )`[^`]*`)+(?=(?:, and this property,)? as `Sendable[^`]*` to fix\\.)", backtickedItem),
		] {
			diagnostic = sortingItems(ofListsMatching: try! NSRegularExpression(pattern: list), item: try! NSRegularExpression(pattern: item), in: diagnostic)
		}
		return diagnostic
	}

	/// `diagnostic` with the items `item` matches in each list `list` matches sorted as text, each in its place among the
	/// list's separators.
	private static func sortingItems(ofListsMatching list: NSRegularExpression, item: NSRegularExpression, in diagnostic: String) -> String {
		let source = diagnostic as NSString
		var result = ""
		var location = 0
		for match in list.matches(in: diagnostic, range: NSRange(location: 0, length: source.length)) {
			let list = source.substring(with: match.range) as NSString
			let itemRanges = item.matches(in: list as String, range: NSRange(location: 0, length: list.length)).map(\.range)
			let sortedItems = itemRanges.map { list.substring(with: $0) }.sorted()
			result += source.substring(with: NSRange(location: location, length: match.range.location - location))
			var listLocation = 0
			for (itemRange, sortedItem) in zip(itemRanges, sortedItems) {
				result += list.substring(with: NSRange(location: listLocation, length: itemRange.location - listLocation)) + sortedItem
				listLocation = itemRange.location + itemRange.length
			}
			result += list.substring(from: listLocation)
			location = match.range.location + match.range.length
		}
		return result + source.substring(from: location)
	}

	var description: String {
		switch self {
		case let .rejected(diagnostics):
			"rejected:\n\(diagnostics)"
		case let .accepted(generatedFiles, warnings):
			"accepted with warnings \(warnings):\n"
				+ generatedFiles.keys.sorted().map { "// \($0)\n\(generatedFiles[$0, default: ""])" }.joined(separator: "\n")
		}
	}
}

/// A graph the oracle does not accept: the tool succeeded and the output does not compile or draws a compiler
/// warning, the fixture itself does not compile (a defect in the fuzzer), two runs of the tool differ, a renamed
/// graph gives other results, or the graph split across modules gives other results under one multi-module
/// integration than under the other.
struct GraphFuzzerFailure: Equatable {
	enum Kind: String, Equatable {
		case generatedCodeDoesNotCompile = "generated code does not compile"
		/// The generated code compiles, and the compiler reports a warning in it that the fixture does not draw
		/// itself: a build that treats warnings as errors fails on it, and its author cannot edit generated code.
		case generatedCodeDrawsWarning = "generated code draws a compiler warning"
		case fixtureDoesNotCompile = "fixture does not compile on its own"
		case runsDiffer = "two runs of the tool differ"
		/// The run that skips no clean subtree in the validation walk gives other results than the run that skips them
		/// (`GraphFuzzerToolRuns.cleanSubtreeSkipFailure`).
		case cleanSubtreeSkipChangesOutcome = "skipping clean subtrees in the validation walk changes the tool's outcome"
		case runsDifferAcrossProcesses = "the tool's output differs between two processes"
		case compilerCrashedOnGeneratedCode = "the Swift compiler crashed on generated code"
		case renamedGraphDiffers = "the graph renamed to change an order gives other results"
		case mockTakesWrapperParameterForReceive = "a generated internal mock takes a LazilyInstantiated parameter for a receive"
		/// Generated code calls a function SafeDI generates for code people write – a generated `mock()` or a seam's plain
		/// initializer – rather than the one only generated code calls (`GraphFuzzerOracle.callsOfEntriesMeantForPeople(in:)`).
		case generatedCodeCallsEntryMeantForPeople = "generated code calls a generated mock() or plain initializer meant for code people write"
		/// An initializer only generated code calls – a seam tier's, or a builder struct's – gives a parameter a default
		/// (`GraphFuzzerGeneratedOnlyInitializerDefaults.parametersWithDefaults(in:)`).
		case generatedOnlyInitializerTakesDefault = "an initializer only generated code calls gives a parameter a default"
		case carrierMemberReadApart = "generated code reads a closure member of a seam’s carrier apart from its carrier"
		/// A base corpus graph's generated mock builds a type that has a hand-written mock with the type's initializer,
		/// where it calls the hand-written mock.
		case generatedMockBypassesHandWrittenMock = "a generated mock builds a type with its initializer rather than its hand-written mock"
		case integrationsDiffer = "the graph split across modules gives other results under the two multi-module integrations"
		case seamRejectsGraphInlineAccepts = "the tool rejects the graph with an error that is not a seam's own, and accepts it with no seam"
		/// The tool accepts a graph in one module with its seam and rejects it with no seam. In one module the seam world is
		/// the inlined validation and the seam rules: it adds rules and removes none, so what the inline build rejects, the
		/// seam must reject too. Across modules the inline build cannot construct another module's `internal` types, so a
		/// graph split across modules is not judged this way.
		case seamAcceptsGraphInlineRejects = "the tool accepts the graph with its seam and rejects it with no seam, in one module"
		/// A graph split across modules gets another verdict, other diagnostics, or other generated declarations when the
		/// tool runs as the SwiftPM plugin runs it (`MultiModuleIntegration.swiftPackagePlugin`), which computes every seam
		/// signature, tier and public mock from source, than when it runs as Bazel runs it, reading the dependencies'
		/// `.safedi` files (`.moduleInfo`).
		case integrationsDisagree = "the SwiftPM plugin flow and the module-info flow give other results"
		/// The module-info flow gives a split graph other results when each module reads the signatures of the seams it
		/// calls from their modules' `.safedi` files than when it computes them again from the declarations.
		case storedSeamSignaturesDisagree = "reading the stored seam signatures and computing them again give other results"
		case seamPassesNilWhereInlinePassesValue = "the generated code passes a literal nil more often with the seam than without it"
		/// The tool rejects the alias draw's seam, with an error about that seam, where it accepts the graph with no seam.
		case seamRejectedWhereInlineAccepts = "the tool rejects the alias draw's seam where it accepts the graph with no seam"
		/// The differential value comparator describes other values for a probe of the seam build than for the same
		/// probe of the inline build, beyond the documented divergences.
		case seamBuildsOtherValuesThanInline = "the seam build constructs other values than the inline build"
		/// The comparator could not describe the seam build or the inline build: a path or its probes did not compile
		/// or run.
		case valueComparatorCouldNotDescribeGraph = "the differential value comparator could not describe the graph"
		/// A seam's generated tier is wider than a type one of its parameters names, by the access the generator gave
		/// the type: a tier SafeDI proved from the wrong declaration, which the seam's own module may not compile.
		case seamTierWiderThanParameterType = "a seam's generated tier is wider than a type one of its parameters names"
		/// A caller in another module calls a tier that omits a parameter some receiver of which the caller's module's
		/// inline build passes a value, and the tool reports no error: the seam passes `nil` where inline passes a value.
		case seamTierOmitsValueInlinePasses = "a caller's tier omits a parameter its inline build passes a receiver a value for, with no error"
		/// The tool reports that a caller holds a value its tier omits, where the caller's module's inline build passes
		/// every receiver of that parameter `nil`.
		case seamTierOmitsProvidedValueReportedWhereInlinePassesNil = "the tool reports a value a caller's tier omits where its inline build passes every receiver nil"
		/// The differential value comparator describes other values for a probe of a graph whose seam takes a builder
		/// for a hole than for the same probe of its visible build (`GraphFuzzerFixture.withoutHoles`), in which the
		/// seam's module sees the fulfilling type and builds it inline.
		case holeBuildsOtherValuesThanVisibleBuild = "the build that fills a hole constructs other values than the visible build"
		/// The tool accepts a graph whose seam takes a builder for a hole and rejects its visible build: the fill
		/// accepts what the seam's module, building the fulfilling type inline, rejects.
		case holeAcceptedWhereVisibleBuildRejects = "the tool accepts a graph with a hole and rejects its visible build"
		/// The tool rejects a `generateMockPublic` graph with an error that is not a public mock's own, and accepts its
		/// known-right path: the same graph with every declaration `public` and every `.public` mock `true`.
		case publicMockRejectsGraphKnownRightAccepts = "the tool rejects the graph with an error that is not a public mock's own, and accepts its known-right path"
		/// The tool accepts a `generateMockPublic` graph and rejects its known-right path.
		case knownRightRejectsGraphPublicMockAccepts = "the tool accepts the graph and rejects its known-right path"
		/// A `public` or `package` declaration in generated code names a type narrower than the declaration, by the access
		/// the generator gave the type: a public mock, override or configuration SafeDI proved from the wrong declaration.
		case publicMockDeclarationWiderThanNamedType = "a generated public or package declaration is wider than a type it names"
		/// A consumer's mock in a `generateMockPublic` graph takes a builder of `T6`'s places, which the fill its module declares
		/// fills from what `T6`'s mock binds before its tree (`GraphFuzzerToolRuns.publicMockRootLevelFailure`).
		case publicMockPassesUpPlaceItsRootLevelFills = "a consumer passes up a public mock's place its fill fills from what the public mock binds before its tree"
		/// A consumer's overrides in a `generateMockPublic` graph hold a closure that builds a called public mock whose call can
		/// hand it no builder a person writes, or hold none where the call can (`GraphFuzzerToolRuns.publicMockOverrideClosureFailure`).
		case publicMockOffersOverrideClosureItsCallCannotHand = "a consumer's overrides hold a closure that builds a called public mock its call can hand no builder a person writes"
		case publicMockDropsOverrideClosureItsCallCanHand = "a consumer's overrides hold no closure that builds a called public mock its call can hand a builder a person writes"
		/// A public mock's `SafeDIOverrides`, or a module-level configuration, in a `generateMockPublic` graph takes a holder of
		/// a place and its siblings in another order than they are declared (`GraphFuzzerToolRuns.publicMockOverridesOrderFailure`).
		case publicMockOverridesFollowBuildOrder = "a public mock's overrides take a holder of a place and its siblings in another order than they are declared"
		/// The differential value comparator describes other values for a probe of a `generateMockPublic` graph than for
		/// the same probe of its known-right path, beyond the stated divergences.
		case publicMockBuildsOtherValuesThanKnownRight = "the graph builds other values than its known-right path"
		/// The retention oracle (rule 3 of the seam contract: nothing is retained that inline frees): a probe of a graph with
		/// a hole, built with its seam, keeps more instances of a type alive than the same probe of its inline build, once the
		/// probe's value is released while one wrapper it held, and what one call of that wrapper builds, are held
		/// (`DifferentialValueRetentionDifference`).
		case seamRetainsWhatInlineFrees = "the seam build keeps alive what the inline build frees"
		/// The retention oracle on a `generateMockPublic` graph with a hole: a probe keeps more instances of a type alive than
		/// the same probe of its known-right path, once the probe's value is released while one wrapper it held is held.
		case publicMockRetainsWhatKnownRightFrees = "the graph keeps alive what its known-right path frees"
		/// A base corpus graph's generated `mock()` – a root's, or a mocked type's beside its mirror – builds other values
		/// than the production build of the same tree (`GraphFuzzerValueOraclePlan`).
		case mockBuildsOtherValuesThanProduction = "a generated mock builds other values than the production build of the same tree"
		/// The tool rejects the value-oracle fixture of a base corpus graph it accepts: a mirror the model got wrong, a mock
		/// accepting a tree production rejects, or a root's mock rejected where the root is accepted.
		case valueOracleFixtureRejected = "the tool rejects the value-oracle fixture of a graph it accepts"
		/// The value-oracle fixture of a base corpus graph does not compile, or its probes do not run.
		case valueOracleFixtureDoesNotCompile = "the value-oracle fixture does not compile or run"
		/// The mirror model disagrees with a generated mock about what it builds beside the mocked type: a model left behind
		/// by a change to what a mock promotes, or a mock that promotes another set than the rules state.
		case mirrorModelDisagreesWithMock = "the mirror model disagrees with a generated mock about what it builds"
		/// The value-oracle run generates another mock for a type the graph mocks than the corpus run does, so the oracle
		/// would judge other code than the corpus's.
		case valueOracleFixtureChangesDrawnMocks = "the value-oracle fixture changes a mock the graph generates"
		/// A root's generated `mock()` takes a parameter: a root receives nothing and forwards nothing, so its mock takes
		/// none but its overrides.
		case rootMockTakesParameter = "a root's generated mock takes a parameter"
		/// `query graph` names other suppliers for a receive than the generated code hands it, or the oracle cannot follow
		/// a read of the generated code (`GraphFuzzerToolRuns.querySuppliersFailure`).
		case querySuppliersDifferFromGeneratedCode = "query graph names other suppliers for a receive than the generated code hands it"
		/// The graph names a type no declaration SafeDI reads declares, and its read twin (`GraphFuzzerFixture.readTwin`),
		/// which declares that type `public` where SafeDI reads it, gets another verdict, other diagnostics, or other
		/// generated code: SafeDI counts the type otherwise than as `public` (decision 54).
		case readTwinDiffers = "the graph with each type SafeDI reads no declaration of declared public where SafeDI reads it gives other results"
		/// The tool accepts a graph with a hole and the same graph without its second place of a hole
		/// (`GraphFuzzerGenerator.fixtureWithoutSecondHolePlace`), and a builder label, scope type or case name it generates
		/// for the graph without the place is gone from what it generates for the graph with it: a hand-written caller that
		/// names it stops compiling when a place is added beneath the seam it calls.
		case holeNamesChangeWithSecondPlace = "a builder label or case name of the graph without its second place of a hole changes when the place is added"
		/// A seam's readable initializer or a generated `mock()` takes a parameter that names a type SafeDI generates – a
		/// scope enum, a scope's `_Values` struct or a generated builder struct – or a builder the fuzzer writes by hand
		/// takes a scope (`GraphFuzzerToolRuns.builderSurfaceFailure`): what a person writes would name generated code.
		case builderSurfaceNamesGeneratedType = "a seam's readable initializer or a mock takes a parameter naming a generated type, or a hand-written builder takes a scope"
		/// The graph's generated code compiles, and a call a person writes of a seam's readable initializer – each builder
		/// that takes a builder struct passed `{ make() }` or a stored `make` of the family the struct names
		/// (`GraphFuzzerBuilderSurface.addingBuilderCalls(to:seamTypeAccess:modules:)`) – does not compile against it. No
		/// known issue lists it, and no known failure masks it (`GraphFuzzerFinding`).
		case builderCallDoesNotCompile = "a hand-written call of a seam's readable initializer does not compile"
		/// A call written against the graph's readable initializers and mocks stops compiling against the graph with an edit
		/// that keeps every builder's places (`GraphFuzzerToolRuns.sameSupplyFailure`).
		case sameSupplyCallStopsCompiling = "a call of a readable initializer or a mock stops compiling when an edit keeps every builder's places"
		/// The tool rejects a graph edited to keep every builder's places, or the graph it is edited from
		/// (`GraphFuzzerToolRuns.sameSupplyEditRejectedFailure`): the calls are never judged.
		case sameSupplyEditRejected = "the tool rejects a graph edited to keep every builder's places"
		/// Adding a place of a new builder whose filling type is an existing builder's renames, retypes or reorders an
		/// existing builder (`GraphFuzzerToolRuns.addedSupplyFailure`).
		case addedBuilderChangesExistingBuilder = "adding a builder of an existing filling type changes an existing builder's label or type"
		/// The tool accepts a graph whose places of one builder forward other values, or rejects it only outside the module
		/// where the places meet (`GraphFuzzerToolRuns.forwardedValuesFailure`).
		case placesForwardingOtherValuesAccepted = "places of one builder that forward other values are accepted, or rejected only outside the module where they meet"
		/// The tool accepts the remedy of places of one builder that forward other values with other builders than the drawn
		/// graph's (`GraphFuzzerToolRuns.remedyBuildersFailure`). Known issues list it only for the transitional builder-kind
		/// flip (`GraphFuzzerFailure.knownBuilderSurfaceKinds`).
		case remedyAddsBuilder = "the remedy of places of one builder that forward other values takes other builders than the drawn graph"
		/// A second call of another module's public mock renames, retypes or reorders a builder a calling mock takes
		/// (`GraphFuzzerToolRuns.callingMockFailure`).
		case callingMockChangesBuilder = "a second call of a public mock changes a builder of the calling mock"
		/// A builder a seam's readable initializer or a generated `mock()` takes, which takes no scope, is labeled otherwise than
		/// contract rule 8 says (`GraphFuzzerToolRuns.builderLabelFailure`).
		case builderLabelBreaksContract = "a builder's label is not the one the contract gives its filling type, returned type and family"
		/// The tool rejects the remedy of places of one builder that forward other values, whose places forward the same
		/// values (`GraphFuzzerToolRuns.forwardingRemedyFailure`). No known issue lists it.
		case remedyOfPlacesForwardingOtherValuesRejected = "the remedy of places of one builder that forward other values is rejected"
		/// Two builds of one type in a seam's tree bind other values before the same property (`SeamPlaceLevels.levelDisagreements()`):
		/// the levels a scope enum would nest by type would depend on the path.
		case placeLevelsDifferBetweenBuildsOfType = "two builds of one type in a seam's tree bind other values before the same property"
		case rootFunctionTextDiffersForOneKey = "two root functions of one root with one key have different text"
		/// A seam call judged the places of one case with other fills than one for each kind of place
		/// (`GraphFuzzerToolRuns.placesJudgedByAnotherPlacesFillFailure`). No known issue lists it.
		case placesJudgedByAnotherPlacesFill = "a seam call judges places of one case by another fill than one per kind of place"
		/// A place's path in a seam's tree repeats a declaration (`GraphFuzzerPlaceFacts.chainRepeats`): a scope value's
		/// chain would repeat one, which a build that closes a cycle, being the first build, never makes.
		case placeChainRepeatsDeclaration = "a place's path in a seam's tree repeats a declaration"
		/// A second path to a type that holds a place adds or changes a level, or, where the generator nests by type, an
		/// enum, a case, a struct or a field, besides its own property's case (`GraphFuzzerToolRuns.secondPathFailure`).
		case secondPathChangesScope = "a second path to a type that holds a place changes the scope beyond its own case"
		/// A case a place's path produces that no generated scope enum declares
		/// (`GraphFuzzerScopeDeclarations.undeclaredProducedCases(of:)`).
		case producedCaseUndeclared = "a place's path produces a case no scope enum declares"
		/// A generated scope enum or case of its own that no place's path produces, in a graph without a tangle of cycles
		/// (`GraphFuzzerScopeDeclarations.unproducedDeclaredCases(of:)`).
		case declaredCaseNeverProduced = "a scope enum or case no place's path produces, without a tangle of cycles"
		/// A case of a scope enum that names no property of the type the enum describes
		/// (`GraphFuzzerScopeDeclarations.casesNamingNoPropertyOfTheirType(of:)`).
		case scopeCaseNamesNoProperty = "a scope enum's case names no property of the type it describes"
		/// The tool rejects a base corpus graph, and applying a remedy one of its errors states
		/// (`GraphFuzzerRemedies`) leaves an error at the declaration the error is at: the remedy does not fix the error, or
		/// trades it for another there.
		case remedyLeavesErrorAtSite = "a remedy an error states leaves an error at the declaration the error is at"
		/// A calling mock (`GraphFuzzerCallingMockCheck`) is accepted where its production twin, the same sources with the
		/// caller declared `generateDependencyTree: true`, reports one of the four shape errors, other than the outcome rule 7
		/// lists, a seam built again that passes its builder on unchanged, which a graph that states probes judges by values.
		case callingMockAcceptedWhereTwinReportsShapeError = "a calling mock is accepted where its production twin reports a shape error"
		/// A calling mock reports an error at other sites than its production twin's shape error.
		case callingMockReportsOtherErrorThanTwin = "a calling mock reports another error than its production twin"
		/// A calling mock is rejected where its production twin is accepted, but with the one error of its own its graph
		/// states (`GraphFuzzerCallingMockGraph.expectedMockOwnErrorSite`).
		case callingMockRejectsWhereTwinAccepts = "a calling mock is rejected where its production twin is accepted"
		/// A calling mock is accepted, in a build that compiles the generated mocks, where its fill calls a hand-written mock
		/// its module cannot reach, which its production twin does not call (contract rule 7).
		case callingMockAcceptedWhereItsFillCallsMockItCannotReach = "a calling mock is accepted where its fill calls a hand-written mock its module cannot reach"
		/// A calling mock is rejected in a build that leaves the mock condition inactive, where its graph's twin error is one
		/// the tool checks only where the generated mocks compile (`GraphFuzzerCallingMockGraph.MockBuild`).
		case callingMockRejectedWhereMockConditionIsInactive = "a calling mock is rejected in a build that leaves the mock condition inactive"
		/// A calling mock passes a place up that none of contract rule 7's permanent reasons explains.
		case callingMockPassesUpUnclassifiedPlace = "a calling mock passes up a place no permanent reason explains"
		/// A calling mock takes no parameter for a value its graph says the mock's tree cannot build, which its production
		/// twin takes.
		case callingMockLacksFlatParameter = "a calling mock takes no parameter for a value its tree cannot build"
		/// A calling mock that mirrors its production twin, passing up no place without a reason, does not compile
		/// (`GraphFuzzerCallingMockCheck.valueFailure`): where the twin is accepted, or where it reports that a seam built
		/// again passes its builder on unchanged. Only a run that compiles shows it.
		case callingMockDoesNotCompile = "a calling mock does not compile where it mirrors its production twin"
		/// A calling mock that mirrors its accepted production twin builds other values than the twin
		/// (`GraphFuzzerCallingMockCheck.valueFailure`).
		case callingMockBuildsOtherValuesThanTwin = "a calling mock builds other values than its production twin"
		/// A calling mock accepted where its production twin reports that a seam built again passes its builder on unchanged
		/// builds other values than the same types built inline (`GraphFuzzerCallingMockCheck.valueFailure`), the only way
		/// rule 7 lets that outcome agree, or one whose graph compares it with the same types built inline where its twin is
		/// accepted (`GraphFuzzerCallingMockGraph.comparesValuesWithInline`) builds other values than they do.
		case callingMockBuildsOtherValuesThanInline = "a calling mock builds other values than the same types built inline"
		/// A calling mock that mirrors its production twin compiles, and its probe traps or does not finish
		/// (`GraphFuzzerCallingMockCheck.valueFailure`).
		case callingMockFailsWhenRun = "a calling mock traps or does not finish where it mirrors its production twin"
		/// A generated `SafeDIOverrides`, `SafeDIMockConfiguration` or public mock's module-level configuration stores
		/// another configuration by value (`GraphFuzzerToolRuns.configurationStorageFailure`), which every builder function
		/// that captures it copies whole.
		case configurationStoresAnotherByValue = "a generated configuration stores another configuration by value"
		/// A closure a caller's level function returns, or a fill function such a closure hands its values to, keeps a
		/// level's values struct alive, or a level function takes one (`GraphFuzzerLevelFunctionCaptures`): what the
		/// closure builds would keep alive values its fill does not read.
		case levelFunctionKeepsValues = "a closure a level function returns keeps a level's values struct alive"
	}

	let seed: UInt64
	let kind: Kind
	let details: String
	/// For `seamBuildsOtherValuesThanInline` and the other value and retention kinds, each difference's description: a
	/// known issue of that kind documents the failure only when every one of them matches one of its signatures.
	var valueDifferences: [String] = []
	/// For `valueOracleFixtureRejected`, each line of the tool's diagnostics that reports an error: a known issue of that
	/// kind documents the failure only when every one of them contains the text of one of its rejection signatures.
	var rejectionErrorLines: [String] = []
	/// For `renamedGraphDiffers`, what differs: a known issue of that kind documents the failure only when one of its
	/// signatures names exactly this.
	var renamedGraphDifference: GraphFuzzerOutcomeDifference.Aspect?
	/// For `remedyLeavesErrorAtSite`, a line for each remedy that leaves an error at its site: a known issue of that kind
	/// documents the failure only when every one of them contains the text of one of its remedy signatures.
	var remedyFailures: [String] = []

	static func reproductionCommand(forSeed seed: UInt64, features: Set<GraphFuzzerGeneratorFeature>) -> String {
		let featuresVariable = features.isEmpty ? "" : "SAFEDI_GRAPH_FUZZER_FEATURES=\(features.sorted().map(\.rawValue).joined(separator: ",")) "
		return "\(featuresVariable)SAFEDI_GRAPH_FUZZER_STARTING_SEED=\(seed) SAFEDI_GRAPH_FUZZER_ITERATIONS=1 swift test --traits sourceBuild --filter SafeDIToolGraphFuzzerTests/longRun"
	}

	func issueComment(fixture: GraphFuzzerFixture) -> Comment {
		"""
		Graph fuzzer seed \(seed): \(kind.rawValue).
		Reproduce with: \(Self.reproductionCommand(forSeed: seed, features: GraphFuzzerGeneratorFeature.features(drawnIn: fixture)))
		\(details)
		Fixture:
		\(fixture.description)
		"""
	}
}

/// What the retention oracle judged, of one graph or added up over a corpus, which each corpus pins (`retention` in the
/// long run's report): a change that judges fewer graphs, or pairs fewer experiments, fails the pin.
@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
struct GraphFuzzerRetentionCounts: Equatable {
	/// The graphs with a hole whose retention the oracle judged: both paths ran an experiment holding a wrapper of one of
	/// its probes' values.
	var judged = 0
	/// The judged graphs that draw the retention oracle's own shape (`addingRetentionShapes`, `drawRetentionPublicMock`).
	var judgedDrawingRetentionShape = 0
	/// The judged graphs whose probe through a hand-written builder (`handWrittenRetentionProbe`) the oracle judged.
	var judgedThroughHandWrittenBuilder = 0
	/// The retention experiments only one path ran, over every probe of every judged graph: each a wrapper one path's value
	/// holds where the other's holds none, which judges nothing.
	var unpairedExperiments = 0
	/// The judged graphs in which both paths ran an experiment holding a place held in an instantiator, by the wrapper the
	/// place is held in (`forwardingWrapperName(ofHeldLabels:in:)`): an experiment that holds such a wrapper judges what the
	/// builder the wrapper keeps keeps alive.
	var judgedHoldingForwardingWrapper = [String: Int]()

	/// The wrappers `judgedHoldingForwardingWrapper` counts graphs by, in the order the report writes them.
	static let forwardingWrapperNames = ["ErasedInstantiator", "SendableErasedInstantiator", "Instantiator", "SendableInstantiator"]

	/// The labels of the places held in an instantiator that `addingHoleShapes` and `addingRetentionShapes` draw, which an
	/// experiment holding one counts in `judgedHoldingForwardingWrapper`.
	static let forwardingPlaceLabels: Set = ["holeTicketBuilder", "holeTicketOther", "holeHandedBuilder", "holeHandedErased", "holeHandedLater", "holeLaterBuilder", "holeServiceLater", "retainApiBuilder"]

	/// The counts as the long run's report and `combine-graph-fuzzer-reports.py` write them.
	var reportField: String {
		var field = "judged=\(judged),drawJudged=\(judgedDrawingRetentionShape),handWrittenJudged=\(judgedThroughHandWrittenBuilder),unpairedExperiments=\(unpairedExperiments)"
		for wrapperName in Self.forwardingWrapperNames {
			field += ",forwardingJudged\(wrapperName)=\(judgedHoldingForwardingWrapper[wrapperName, default: 0])"
		}
		return field
	}

	mutating func add(_ other: GraphFuzzerRetentionCounts) {
		judged += other.judged
		judgedDrawingRetentionShape += other.judgedDrawingRetentionShape
		judgedThroughHandWrittenBuilder += other.judgedThroughHandWrittenBuilder
		unpairedExperiments += other.unpairedExperiments
		judgedHoldingForwardingWrapper.merge(other.judgedHoldingForwardingWrapper, uniquingKeysWith: +)
	}

	/// The wrappers of the places held in an instantiator among `heldLabels`, the labels experiments held, each once, as
	/// `fixture` declares them: `ErasedInstantiator` for `holeTicketBuilder: ErasedInstantiator<Int, any HoleTicketService>`.
	static func forwardingWrapperNames(ofHeldLabels heldLabels: Set<String>, in fixture: GraphFuzzerFixture) -> Set<String> {
		var wrapperNames = Set<String>()
		for content in fixture.swiftFileContent {
			for line in GraphFuzzerSourceLine.lines(of: content) {
				guard case let .property(_, label, type) = line, forwardingPlaceLabels.contains(label), heldLabels.contains(label) else { continue }
				let wrapperName = String(type.prefix { $0 != "<" })
				if forwardingWrapperNames.contains(wrapperName) {
					wrapperNames.insert(wrapperName)
				}
			}
		}
		return wrapperNames
	}

	/// Whether `fixture` draws the retention oracle's own shape, in the seam corpus or the public mock corpus.
	static func drawsRetentionShape(_ fixture: GraphFuzzerFixture) -> Bool {
		GraphFuzzerFeature.seamDrawFeatures(of: fixture).contains(where: \.isRetentionShape)
			|| GraphFuzzerPublicMockDraw.drawFeatures(of: fixture).contains(.retentionPublicMockValueBeforeBuilder)
	}
}

/// The oracle's verdict on one graph.
@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
struct GraphFuzzerResult {
	init(
		fixture: GraphFuzzerFixture,
		outcome: GraphFuzzerToolOutcome,
		failure: GraphFuzzerFailure?,
		laterFailures: [GraphFuzzerFailure] = [],
		renamedGraphFailures: [GraphFuzzerFailure] = [],
		multiModuleRuns: [GraphFuzzerMultiModuleRuns] = [],
		isInspectedByValueOracle: Bool = false,
		isComparedByValueOracle: Bool = false,
		isComparedAcrossIntegrations: Bool = false,
		isComparedWithRecomputedSignatures: Bool = false,
		isComparedWithReadTwin: Bool = false,
		isJudgedByQueryOracle: Bool = false,
		isComparedWithoutSecondHolePlace: Bool = false,
		isComparedWithoutSecondPath: Bool = false,
		isComparedWithCleanSubtreeSkipOff: Bool = false,
		retentionCounts: GraphFuzzerRetentionCounts = GraphFuzzerRetentionCounts(),
		valueOracle: GraphFuzzerValueOracleRun? = nil,
		remedyRuns: [GraphFuzzerRemedyRun] = [],
		builderSurfaceFloorKinds: [String] = [],
		levelFunctionCaptures: GraphFuzzerLevelFunctionCaptures? = nil,
	) {
		self.retentionCounts = retentionCounts
		self.levelFunctionCaptures = levelFunctionCaptures
		self.builderSurfaceFloorKinds = builderSurfaceFloorKinds
		self.isComparedWithoutSecondHolePlace = isComparedWithoutSecondHolePlace
		self.isComparedWithoutSecondPath = isComparedWithoutSecondPath
		self.isComparedWithCleanSubtreeSkipOff = isComparedWithCleanSubtreeSkipOff
		self.remedyRuns = remedyRuns
		self.fixture = fixture
		self.outcome = outcome
		self.failure = failure
		self.laterFailures = laterFailures
		self.renamedGraphFailures = renamedGraphFailures
		self.multiModuleRuns = multiModuleRuns
		self.isInspectedByValueOracle = isInspectedByValueOracle
		self.isComparedByValueOracle = isComparedByValueOracle
		self.isComparedAcrossIntegrations = isComparedAcrossIntegrations
		self.isComparedWithRecomputedSignatures = isComparedWithRecomputedSignatures
		self.isComparedWithReadTwin = isComparedWithReadTwin
		self.isJudgedByQueryOracle = isJudgedByQueryOracle
		self.valueOracle = valueOracle
	}

	let fixture: GraphFuzzerFixture
	let outcome: GraphFuzzerToolOutcome
	/// The first way the graph fails the oracle: its runs differ, it does not compile or its generated code draws a
	/// compiler warning, a generated mock takes a `LazilyInstantiated` parameter for a receive, the graph split across
	/// modules gives other results under one multi-module integration than under the other, or, failing none of those
	/// ways, a renamed graph gives other results.
	let failure: GraphFuzzerFailure?
	/// The ways the graph fails after `failure` in the oracle's chain, every difference of a renamed graph among them,
	/// which a known value failure, or a known failure of a base corpus graph's value-oracle fixture, does not mask.
	let laterFailures: [GraphFuzzerFailure]
	/// Each way a renamed graph gives other results, a failure per difference, in the order of
	/// `GraphFuzzerRenaming.all`, whether or not the graph also fails another way.
	let renamedGraphFailures: [GraphFuzzerFailure]
	/// What the two multi-module integrations produced for the graph split across modules, in the order of
	/// `GraphFuzzerOracle.multiModuleRenamings`.
	let multiModuleRuns: [GraphFuzzerMultiModuleRuns]
	/// Whether the value oracle compared the graph's generated code with its inline build's: the tool accepts the
	/// graph with its seam and without it.
	let isInspectedByValueOracle: Bool
	/// Whether the comparator did compare the two builds: the graph is inspected, its runs agree, and its generated
	/// code compiles cleanly, since `results(of:)` hands the comparator no graph with a compilation failure. A base
	/// corpus graph is compared when, besides, its value-oracle fixture is accepted as planned and its comparison ran.
	let isComparedByValueOracle: Bool
	/// Whether the oracle ran the graph as the SwiftPM plugin runs the tool too, and compared the two flows
	/// (`GraphFuzzerToolRuns.integrationsDisagreeFailure`): the graph is split across modules, and no module of it is run
	/// without its package's name.
	let isComparedAcrossIntegrations: Bool
	/// Whether the oracle ran the graph with every module info's seam signatures and public mock plans discarded and
	/// compared the two runs (`GraphFuzzerToolRuns.storedSeamSignaturesDisagreeFailure`): the graph is split across
	/// modules and declares a seam or a public mock.
	let isComparedWithRecomputedSignatures: Bool
	/// Whether the oracle ran the graph's read twin and compared it with the graph (`GraphFuzzerToolRuns.readTwinFailure`):
	/// the graph names a type no declaration SafeDI reads declares.
	let isComparedWithReadTwin: Bool
	/// Whether the query oracle compared the suppliers `query graph` exports with the generated code
	/// (`GraphFuzzerToolRuns.querySuppliersFailure`): the tool accepts the graph, which is in one module and no public mock's.
	let isJudgedByQueryOracle: Bool
	/// Whether the oracle compared the builder labels and case names the tool generates for the graph with those it generates
	/// for the graph without its second place of a hole (`GraphFuzzerToolRuns.holeNameStabilityFailure`): the tool accepts
	/// both.
	let isComparedWithoutSecondHolePlace: Bool
	/// Whether the oracle compared the levels, and where the generator nests by type the scope enums, the tool computes for
	/// the graph with those of the graph without its second path to a type that holds a place
	/// (`GraphFuzzerToolRuns.secondPathFailure`): the tool accepts both.
	let isComparedWithoutSecondPath: Bool
	/// Whether the oracle ran the graph again with no skip of a clean subtree in the validation walk and compared the two
	/// (`GraphFuzzerToolRuns.cleanSubtreeSkipFailure`): its first run skipped one.
	let isComparedWithCleanSubtreeSkipOff: Bool
	/// What the retention oracle judged of the graph (`GraphFuzzerOracle.ValueComparisons.retentionCounts`), each count
	/// 0 or 1 but the unpaired experiments'.
	let retentionCounts: GraphFuzzerRetentionCounts

	/// Whether the retention oracle judged what the graph's probes keep alive against its inline build's, or its
	/// known-right path's (`GraphFuzzerOracle.ValueComparisons.retentionFailures`): the graph has a hole, the comparator
	/// compared its two builds, and both ran an experiment holding a wrapper.
	var isJudgedForRetention: Bool {
		retentionCounts.judged > 0
	}

	/// Whether the graph passes every oracle but the builder surface (`passesBesidesBuilderSurface`) and the retention
	/// oracle, whose failure `knownIssue` documents: counts of what passing graphs show (the spellings the long run
	/// counts, the shapes of the seam smoke batch) count it as passing while the builder structs and the leak fix it awaits
	/// are not built.
	/// - Parameter builderOrder: The shape of the builder label sort alone, which orders a seam's builders by label, as its
	///   seed's entry lists it, or `nil`. A difference of a renamed graph it documents passes too, since the order is
	///   sanctioned and the graph exercises its shapes as any graph does; the caller passes no other shape, so that no other
	///   difference of a renamed graph passes.
	func passes(butForRetentionDocumentedBy knownIssue: GraphFuzzerKnownIssue?, butForBuilderOrderDocumentedBy builderOrder: GraphFuzzerKnownIssue? = nil) -> Bool {
		([failure] + laterFailures).compactMap(\.self).allSatisfy { failure in
			GraphFuzzerFailure.knownBuilderSurfaceKinds.contains(failure.kind)
				|| [.seamRetainsWhatInlineFrees, .publicMockRetainsWhatKnownRightFrees].contains(failure.kind) && knownIssue?.matches(failure) == true
				|| failure.kind == .renamedGraphDiffers && builderOrder?.matches(failure) == true
		}
	}

	/// A base corpus graph's value-oracle run, whose pairs and skips the long run counts.
	let valueOracle: GraphFuzzerValueOracleRun?
	/// The remedies the errors of a rejected base corpus graph state, applied, which the long run counts by kind.
	let remedyRuns: [GraphFuzzerRemedyRun]
	/// The kinds the graph counts toward the builder surface's floors (`GraphFuzzerToolRuns.builderSurfaceFloorKinds`).
	let builderSurfaceFloorKinds: [String]
	/// What the level function capture check found in the graph's generated code, or `nil` when the tool rejected it.
	let levelFunctionCaptures: GraphFuzzerLevelFunctionCaptures?

	/// What the level function capture check judged of the graph, which the long run adds up per corpus.
	var levelFunctionCaptureCounts: GraphFuzzerLevelFunctionCaptureCounts {
		levelFunctionCaptures.map(GraphFuzzerLevelFunctionCaptureCounts.init) ?? GraphFuzzerLevelFunctionCaptureCounts()
	}

	/// How each partitioned run that gives other results under the two multi-module integrations differs, whether or
	/// not the graph also fails another way.
	var multiModuleFailures: [GraphFuzzerFailure] {
		multiModuleRuns.compactMap(\.failure)
	}

	var isAccepted: Bool {
		switch outcome {
		case .accepted:
			true
		case .rejected:
			false
		}
	}
}

/// A known open defect: the seeds whose graphs fail today with one shape, and a one-line reason naming it.
struct GraphFuzzerKnownIssue: Equatable {
	/// How a failure of a known shape shows itself. Toolchains word the same defect differently, or crash on it,
	/// so a shape lists each way it is known to fail; a known seed that fails any other way is a new failure.
	enum Signature: Equatable {
		/// The generated code fails to compile with an error whose message contains this text.
		case compilerError(containing: String)
		/// The generated code compiles, drawing a warning whose message contains this text.
		case compilerWarning(containing: String)
		/// The Swift compiler crashes while compiling a generated mock.
		case compilerCrashInGeneratedMock
		/// A renamed graph gives other results, in exactly this aspect. Each difference is its own failure, so a graph
		/// that differs in two aspects is documented only by a shape that lists both.
		case renamedGraphDiffers(GraphFuzzerOutcomeDifference.Aspect)
		/// The fixture itself fails to compile, with an error whose message contains this text: the macro rejects
		/// a shape the generator emits before the macro accepts it.
		case macroRejectsFixture(containing: String)
		/// The graph split across modules gives other results under the two multi-module integrations, in the
		/// aspect whose description contains this text.
		case integrationsDiffer(containing: String)
		/// The tool rejects the graph with the seam, with an error whose text contains this, and accepts it without.
		case seamRejectsGraphInlineAccepts(containing: String)
		/// The tool accepts a graph in one module with its seam, and rejects it without, with an error whose text contains
		/// this.
		case seamAcceptsGraphInlineRejects(containing: String)
		/// The SwiftPM plugin flow and the module-info flow give a split graph other results, with details containing this,
		/// such as the first declaration only one of them generates.
		case integrationsDisagree(containing: String)
		/// The generated code passes a literal `nil` more often with the seam than without it, to an argument whose
		/// description contains this text.
		case seamPassesNilWhereInlinePassesValue(containing: String)
		/// The seam build constructs other values than the inline build, with a difference whose description
		/// contains this text.
		case seamBuildsOtherValuesThanInline(containing: String)
		/// The build that fills a hole constructs other values than its visible build, with a difference whose description
		/// contains this text.
		case holeBuildsOtherValuesThanVisibleBuild(containing: String)
		/// The tool accepts a graph with a hole and rejects its visible build, with an error whose text contains this.
		case holeAcceptedWhereVisibleBuildRejects(containing: String)
		/// The value comparator could not describe the graph, with details containing this text, such as the error of
		/// an inline build that does not compile.
		case valueComparatorCouldNotDescribeGraph(containing: String)
		/// The tool rejects a `generateMockPublic` graph, with an error whose text contains this, and accepts its
		/// known-right path.
		case publicMockRejectsGraphKnownRightAccepts(containing: String)
		/// A `generateMockPublic` graph builds other values than its known-right path, with a difference whose
		/// description contains this text.
		case publicMockBuildsOtherValuesThanKnownRight(containing: String)
		/// The seam build keeps alive what the inline build frees, with a retention difference whose description contains
		/// this text, such as the labels of the wrapper held (`holding <labels>`) or a probe's name. As for the value
		/// signatures, every difference must match one of the shape's retention signatures.
		case seamRetainsWhatInlineFrees(containing: String)
		/// A `generateMockPublic` graph keeps alive what its known-right path frees, with a retention difference whose
		/// description contains this text. Every difference must match one of the shape's retention signatures.
		case publicMockRetainsWhatKnownRightFrees(containing: String)
		/// A base corpus graph's generated mock builds other values than the production build of the same tree, with a
		/// difference whose description contains this text.
		case mockBuildsOtherValuesThanProduction(containing: String)
		/// A base corpus graph's value-oracle fixture does not compile, with an error containing this text, such as the
		/// error a root's generated mock reproduces of a mock shape the corpus run lists. A seed listed with this
		/// signature is compared on its own, outside the value batch, so that its known failure does not make the batch
		/// compile every graph again on its own.
		case valueOracleFixtureDoesNotCompile(containing: String)
		/// The tool rejects a base corpus graph's value-oracle fixture, with errors each of whose text contains this or the
		/// text of another of the shape's rejection signatures, and accepts the graph.
		case valueOracleFixtureRejected(containing: String)
		/// A builder label, scope type or case name of the graph without its second place of a hole changes when the place is
		/// added, with details containing this text, such as the second place's label.
		case holeNamesChangeWithSecondPlace(containing: String)
		/// A failure of the builder surface of this kind (`GraphFuzzerFailure.knownBuilderSurfaceKinds`): what a person
		/// writes names a generated type, breaks the label rule, or stops compiling when the supply is kept or added to. A
		/// rejected remedy has no signature, so no listed seed hides it.
		case builderSurface(GraphFuzzerFailure.Kind)
		/// A remedy of this kind, which an error of a base corpus graph states, leaves an error at the declaration the error
		/// is at, with a line (`GraphFuzzerFailure.remedyFailures`) containing this text, or matching another of the shape's
		/// remedy signatures, for each remedy that does: the text names the error the remedy leaves, which tells the shapes of
		/// one kind apart.
		case remedyLeavesErrorAtSite(GraphFuzzerRemedyKind, containing: String)
		/// A calling mock is accepted where its production twin reports one of the four shape errors.
		case callingMockAcceptedWhereTwinReportsShapeError
		/// A calling mock passes up a place that none of contract rule 7's permanent reasons explains.
		case callingMockPassesUpUnclassifiedPlace
		/// A calling mock that mirrors its production twin does not compile, which only a run that compiles shows, so a run
		/// with compile verification off cannot call such an issue stale.
		case callingMockDoesNotCompile
	}

	let reason: String
	let signatures: [Signature]
	/// In increasing order. The ordinary suite checks the first; the long run checks every one it reaches.
	let seeds: [UInt64]

	/// Whether only the base corpus's value oracle shows the shape, which no other corpus runs, so that the seam corpus
	/// inherits no such shape. The remedy oracle runs in the seam corpus too, so its shapes are inherited.
	var isBaseCorpusValueOracleShape: Bool {
		signatures.allSatisfy { signature in
			switch signature {
			case .mockBuildsOtherValuesThanProduction, .valueOracleFixtureDoesNotCompile, .valueOracleFixtureRejected:
				true
			case .remedyLeavesErrorAtSite, .compilerError, .compilerWarning, .compilerCrashInGeneratedMock, .renamedGraphDiffers, .integrationsDiffer, .macroRejectsFixture, .seamRejectsGraphInlineAccepts, .seamAcceptsGraphInlineRejects, .integrationsDisagree, .seamPassesNilWhereInlinePassesValue, .seamBuildsOtherValuesThanInline, .holeBuildsOtherValuesThanVisibleBuild, .holeAcceptedWhereVisibleBuildRejects, .valueComparatorCouldNotDescribeGraph, .publicMockRejectsGraphKnownRightAccepts, .publicMockBuildsOtherValuesThanKnownRight, .seamRetainsWhatInlineFrees, .publicMockRetainsWhatKnownRightFrees, .holeNamesChangeWithSecondPlace, .callingMockAcceptedWhereTwinReportsShapeError, .callingMockPassesUpUnclassifiedPlace, .callingMockDoesNotCompile:
				false
			case .builderSurface:
				false
			}
		}
	}

	/// Whether every signature documents what the retention oracle finds, which only a run that compiles and runs the
	/// graph's code judges: a run that does not judge the graph's retention cannot call such an issue stale.
	var documentsOnlyRetention: Bool {
		signatures.allSatisfy { signature in
			switch signature {
			case .seamRetainsWhatInlineFrees, .publicMockRetainsWhatKnownRightFrees:
				true
			case .seamBuildsOtherValuesThanInline, .holeBuildsOtherValuesThanVisibleBuild, .holeAcceptedWhereVisibleBuildRejects, .publicMockBuildsOtherValuesThanKnownRight, .mockBuildsOtherValuesThanProduction, .valueOracleFixtureRejected, .valueOracleFixtureDoesNotCompile, .compilerError, .compilerWarning, .compilerCrashInGeneratedMock, .renamedGraphDiffers, .integrationsDiffer, .macroRejectsFixture, .seamRejectsGraphInlineAccepts, .seamAcceptsGraphInlineRejects, .integrationsDisagree, .seamPassesNilWhereInlinePassesValue, .valueComparatorCouldNotDescribeGraph, .publicMockRejectsGraphKnownRightAccepts, .holeNamesChangeWithSecondPlace, .remedyLeavesErrorAtSite, .callingMockAcceptedWhereTwinReportsShapeError, .callingMockPassesUpUnclassifiedPlace, .callingMockDoesNotCompile:
				false
			case .builderSurface:
				false
			}
		}
	}

	/// Whether some signature documents what the retention oracle finds: the issue combines a leak's entry, which goes stale
	/// on its own when the leak is gone (`GraphFuzzerFinding.staleLeakEntry`).
	var documentsLeak: Bool {
		signatures.contains { signature in
			switch signature {
			case .seamRetainsWhatInlineFrees, .publicMockRetainsWhatKnownRightFrees:
				true
			case .seamBuildsOtherValuesThanInline, .holeBuildsOtherValuesThanVisibleBuild, .holeAcceptedWhereVisibleBuildRejects, .publicMockBuildsOtherValuesThanKnownRight, .mockBuildsOtherValuesThanProduction, .valueOracleFixtureRejected, .valueOracleFixtureDoesNotCompile, .compilerError, .compilerWarning, .compilerCrashInGeneratedMock, .renamedGraphDiffers, .integrationsDiffer, .macroRejectsFixture, .seamRejectsGraphInlineAccepts, .seamAcceptsGraphInlineRejects, .integrationsDisagree, .seamPassesNilWhereInlinePassesValue, .valueComparatorCouldNotDescribeGraph, .publicMockRejectsGraphKnownRightAccepts, .holeNamesChangeWithSecondPlace, .remedyLeavesErrorAtSite, .builderSurface, .callingMockAcceptedWhereTwinReportsShapeError, .callingMockPassesUpUnclassifiedPlace, .callingMockDoesNotCompile:
				false
			}
		}
	}

	/// Whether every shape of the issue is a value, retention or builder-surface difference, or a difference of a renamed
	/// graph, which documents only the differences its signatures match and masks no later failure of the oracle's chain
	/// (`GraphFuzzerFinding`): a graph listed under such an issue still reports a new failure of any oracle, so the gating
	/// draws count it as judged. The chain judges a renamed graph after every oracle but retention, so a graph whose first
	/// failure is a renamed difference passed every earlier oracle, and `GraphFuzzerFinding` masks no later failure of
	/// such a known difference.
	var masksNoLaterFailure: Bool {
		signatures.allSatisfy { signature in
			switch signature {
			case .seamBuildsOtherValuesThanInline, .holeBuildsOtherValuesThanVisibleBuild, .publicMockBuildsOtherValuesThanKnownRight, .seamRetainsWhatInlineFrees, .publicMockRetainsWhatKnownRightFrees, .mockBuildsOtherValuesThanProduction, .valueOracleFixtureRejected, .valueOracleFixtureDoesNotCompile, .builderSurface, .renamedGraphDiffers:
				true
			case .compilerError, .compilerWarning, .compilerCrashInGeneratedMock, .integrationsDiffer, .macroRejectsFixture, .seamRejectsGraphInlineAccepts, .seamAcceptsGraphInlineRejects, .holeAcceptedWhereVisibleBuildRejects, .integrationsDisagree, .seamPassesNilWhereInlinePassesValue, .valueComparatorCouldNotDescribeGraph, .publicMockRejectsGraphKnownRightAccepts, .holeNamesChangeWithSecondPlace, .remedyLeavesErrorAtSite, .callingMockAcceptedWhereTwinReportsShapeError, .callingMockPassesUpUnclassifiedPlace, .callingMockDoesNotCompile:
				false
			}
		}
	}

	/// Whether `failure` is the failure this issue documents.
	func matches(_ failure: GraphFuzzerFailure) -> Bool {
		signatures.contains { signature in
			switch signature {
			case let .compilerError(text):
				failure.kind == .generatedCodeDoesNotCompile && failure.details.contains(text)
			case let .compilerWarning(text):
				failure.kind == .generatedCodeDrawsWarning && failure.details.contains(text)
			case .compilerCrashInGeneratedMock:
				failure.kind == .compilerCrashedOnGeneratedCode && failure.details.contains("+SafeDIMock.swift")
			case let .renamedGraphDiffers(aspect):
				failure.kind == .renamedGraphDiffers && failure.renamedGraphDifference == aspect
			case let .macroRejectsFixture(text):
				failure.kind == .fixtureDoesNotCompile && failure.details.contains(text)
			case let .integrationsDiffer(text):
				failure.kind == .integrationsDiffer && failure.details.prefix { $0 != "\n" }.contains(text)
			case let .seamRejectsGraphInlineAccepts(text):
				failure.kind == .seamRejectsGraphInlineAccepts && failure.details.contains(text)
			case let .seamAcceptsGraphInlineRejects(text):
				failure.kind == .seamAcceptsGraphInlineRejects && failure.details.contains(text)
			case let .integrationsDisagree(text):
				failure.kind == .integrationsDisagree && failure.details.contains(text)
			case let .seamPassesNilWhereInlinePassesValue(text):
				failure.kind == .seamPassesNilWhereInlinePassesValue && failure.details.contains(text)
			case let .valueComparatorCouldNotDescribeGraph(text):
				failure.kind == .valueComparatorCouldNotDescribeGraph && failure.details.contains(text)
			case .seamBuildsOtherValuesThanInline:
				// Every difference must match one of the shape's value signatures: a documented divergence beside an
				// undocumented difference is a new failure, not a known one.
				failure.kind == .seamBuildsOtherValuesThanInline && !failure.valueDifferences.isEmpty && failure.valueDifferences.allSatisfy { difference in
					signatures.contains { signature in
						if case let .seamBuildsOtherValuesThanInline(text) = signature {
							difference.contains(text)
						} else {
							false
						}
					}
				}
			case .holeBuildsOtherValuesThanVisibleBuild:
				// As for the seam's value signatures, every difference must match one.
				failure.kind == .holeBuildsOtherValuesThanVisibleBuild && !failure.valueDifferences.isEmpty && failure.valueDifferences.allSatisfy { difference in
					signatures.contains { signature in
						if case let .holeBuildsOtherValuesThanVisibleBuild(text) = signature {
							difference.contains(text)
						} else {
							false
						}
					}
				}
			case let .holeAcceptedWhereVisibleBuildRejects(text):
				failure.kind == .holeAcceptedWhereVisibleBuildRejects && failure.details.contains(text)
			case let .publicMockRejectsGraphKnownRightAccepts(text):
				failure.kind == .publicMockRejectsGraphKnownRightAccepts && failure.details.contains(text)
			case .publicMockBuildsOtherValuesThanKnownRight:
				// As for the seam's value signatures, every difference must match one.
				failure.kind == .publicMockBuildsOtherValuesThanKnownRight && !failure.valueDifferences.isEmpty && failure.valueDifferences.allSatisfy { difference in
					signatures.contains { signature in
						if case let .publicMockBuildsOtherValuesThanKnownRight(text) = signature {
							difference.contains(text)
						} else {
							false
						}
					}
				}
			case .seamRetainsWhatInlineFrees:
				// As for the value signatures, every retention difference must match one: a documented retention beside an
				// undocumented one is a new failure.
				failure.kind == .seamRetainsWhatInlineFrees && !failure.valueDifferences.isEmpty && failure.valueDifferences.allSatisfy { difference in
					signatures.contains { signature in
						if case let .seamRetainsWhatInlineFrees(text) = signature {
							difference.contains(text)
						} else {
							false
						}
					}
				}
			case .publicMockRetainsWhatKnownRightFrees:
				// As for the seam's retention signatures, every difference must match one.
				failure.kind == .publicMockRetainsWhatKnownRightFrees && !failure.valueDifferences.isEmpty && failure.valueDifferences.allSatisfy { difference in
					signatures.contains { signature in
						if case let .publicMockRetainsWhatKnownRightFrees(text) = signature {
							difference.contains(text)
						} else {
							false
						}
					}
				}
			case .mockBuildsOtherValuesThanProduction:
				// As for the seam's value signatures, every difference must match one.
				failure.kind == .mockBuildsOtherValuesThanProduction && !failure.valueDifferences.isEmpty && failure.valueDifferences.allSatisfy { difference in
					signatures.contains { signature in
						if case let .mockBuildsOtherValuesThanProduction(text) = signature {
							difference.contains(text)
						} else {
							false
						}
					}
				}
			case let .valueOracleFixtureDoesNotCompile(text):
				failure.kind == .valueOracleFixtureDoesNotCompile && failure.details.contains(text)
			case let .holeNamesChangeWithSecondPlace(text):
				failure.kind == .holeNamesChangeWithSecondPlace && failure.details.prefix { $0 != "\n" }.contains(text)
			case let .builderSurface(kind):
				GraphFuzzerFailure.knownBuilderSurfaceKinds.contains(kind) && failure.kind == kind
			case .remedyLeavesErrorAtSite:
				// As for the value signatures, every remedy that leaves an error must match one.
				failure.kind == .remedyLeavesErrorAtSite && !failure.remedyFailures.isEmpty && failure.remedyFailures.allSatisfy { remedyFailure in
					signatures.contains { signature in
						if case let .remedyLeavesErrorAtSite(kind, text) = signature {
							remedyFailure.hasPrefix(kind.failureLinePrefix) && remedyFailure.contains(text)
						} else {
							false
						}
					}
				}
			case .valueOracleFixtureRejected:
				// As for the value signatures, every error the tool reports must match one: a documented rejection beside
				// an undocumented error is a new failure.
				failure.kind == .valueOracleFixtureRejected && !failure.rejectionErrorLines.isEmpty && failure.rejectionErrorLines.allSatisfy { errorLine in
					signatures.contains { signature in
						if case let .valueOracleFixtureRejected(text) = signature {
							errorLine.contains(text)
						} else {
							false
						}
					}
				}
			case .callingMockAcceptedWhereTwinReportsShapeError:
				failure.kind == .callingMockAcceptedWhereTwinReportsShapeError
			case .callingMockPassesUpUnclassifiedPlace:
				failure.kind == .callingMockPassesUpUnclassifiedPlace
			case .callingMockDoesNotCompile:
				failure.kind == .callingMockDoesNotCompile
			}
		}
	}
}

/// A crash of the Swift compiler, read from its standard error.
struct GraphFuzzerCompilerCrash: Equatable {
	/// The file holding the declaration the compiler was compiling when it crashed, from the stack dump's
	/// `for '<declaration>' (at <path>:<line>:<column>)` line, if the dump names one.
	let fileName: String?
	/// What the compiler was doing when it crashed, without the stack frames.
	let summary: String

	/// `nil` unless `standardError` holds a compiler stack dump.
	init?(standardError: String) {
		guard standardError.contains("Stack dump:") else { return nil }
		let lines = standardError.split(separator: "\n", omittingEmptySubsequences: false)
		var summaryLines = ["The Swift compiler crashed."]
		var fileName: String?
		for line in lines {
			let trimmedLine = line.trimmingCharacters(in: .whitespaces)
			if trimmedLine.hasPrefix("for '"), let locationStart = trimmedLine.range(of: "' (at ") {
				let location = trimmedLine[locationStart.upperBound...].prefix { $0 != ")" }
				let path = location.prefix { $0 != ":" }
				fileName = path.split(separator: "/").last.map(String.init)
				summaryLines.append("In \(trimmedLine[..<locationStart.lowerBound].dropFirst("for '".count)) at \(fileName ?? String(path))\(location.dropFirst(path.count)).")
			} else if let first = trimmedLine.first, first.isNumber, trimmedLine.contains(".\t") || trimmedLine.contains(". "),
			          !trimmedLine.hasPrefix("0.")
			{
				// The numbered lines after `Stack dump:`, other than the program arguments: the compiler version and
				// what it was doing.
				summaryLines.append(String(trimmedLine))
			}
		}
		self.fileName = fileName
		summary = summaryLines.joined(separator: "\n")
	}
}

/// What the fuzzer concludes about one graph, given the known issue listing its seed, if any.
enum GraphFuzzerFinding: Equatable {
	case passed
	/// The graph fails the way its known issue documents.
	case knownIssue(GraphFuzzerKnownIssue, GraphFuzzerFailure)
	/// The graph's seed is a known issue, but the graph no longer fails.
	case staleKnownIssue(GraphFuzzerKnownIssue)
	/// The graph's seed is a known issue, and the issue lists this difference of a renamed graph, which the graph does not
	/// show: a seed sits on an entry only for what its difference shows, so it belongs on the entry that names exactly that.
	/// The graph still fails, so the report calls the seed misfiled, not stale.
	case staleRenamedGraphDifference(GraphFuzzerKnownIssue, GraphFuzzerOutcomeDifference.Aspect)
	/// The graph's seed is a known issue that lists this builder surface failure, which the graph does not show: a seed sits
	/// on an entry only for the parts of the builder surface it fails, so it belongs on the entry that names exactly those.
	/// The graph still fails, so the report calls the seed misfiled, not stale.
	case staleBuilderSurfaceSignature(GraphFuzzerKnownIssue, GraphFuzzerFailure.Kind)
	/// The graph's seed is a known issue that lists a leak (`documentsLeak`) beside what else the graph still fails, such as
	/// the builder surface, and the retention oracle judged the graph and found no leak: the leak's entry is stale, though
	/// the seed's other entries are not, so a fix of the leak is seen on a seed that still fails otherwise.
	case staleLeakEntry(GraphFuzzerKnownIssue)
	/// The graph fails, and no known issue documents that failure: either its seed is not a known issue, or
	/// it fails another way than its known issue documents.
	case failure(GraphFuzzerFailure)

	/// - Parameter laterFailures: The ways the graph fails after `failure` in the oracle's chain. A known value
	///   failure masks none of them: the first the known issue does not document is the finding. Nor does a known
	///   rejection of a base corpus graph's value-oracle fixture, or a known failure of it to compile, of each of which
	///   every later failure is independent: the value comparison does not run, and the wrapper, multi-module and
	///   rename oracles judge the drawn graph. Nor does a known failure of the builder surface, which judges only the
	///   surface a person writes against, of which every later oracle is independent. No known failure masks a renamed
	///   graph's difference, which judges only what the tool generates, nor what the retention oracle or the level function
	///   capture check finds, since what a graph keeps alive does not depend on how else it fails, so a known failure never hides a leak, nor a
	///   value a public mock builds other than its known-right path does, which the public mock corpus's value oracle alone judges for a
	///   generated call of a public mock, nor a failure of
	///   the builder surface (`GraphFuzzerFailure.builderSurfaceKindsNeverMasked`), which judges only the tool's output
	///   for the graph and its edits, so a known failure of an earlier oracle, such as a hole name that changes with a
	///   second place, never hides a part of the builder surface its seed's entry does not list – the compile of the call
	///   a person writes against a seam's readable initializer (`builderCallDoesNotCompile`) among them.
	/// - Parameter retentionIsJudged: Whether the retention oracle judged the graph, which it does only where the run
	///   compiles and runs its code. A graph it did not judge that fails nothing else passes, rather than making stale a
	///   known issue every signature of which documents a leak (`documentsOnlyRetention`); a known issue that lists
	///   anything else is stale, since what else it lists was judged.
	init(failure: GraphFuzzerFailure?, laterFailures: [GraphFuzzerFailure] = [], knownIssue: GraphFuzzerKnownIssue?, retentionIsJudged: Bool = true) {
		switch (failure, knownIssue) {
		case (nil, nil):
			self = .passed
		case let (nil, knownIssue?):
			self = retentionIsJudged || !knownIssue.documentsOnlyRetention ? .staleKnownIssue(knownIssue) : .passed
		case let (failure?, knownIssue?) where knownIssue.matches(failure):
			// No signature lists the compile of `C` (`builderCallDoesNotCompile`), so a known failure of its kind never arises
			// today; it is listed here so that one never masks a later failure should a signature come to list it. A known
			// difference of a renamed graph masks none either, whatever order the chain judges in.
			let masksNoLaterFailure = [.seamBuildsOtherValuesThanInline, .holeBuildsOtherValuesThanVisibleBuild, .publicMockBuildsOtherValuesThanKnownRight, .seamRetainsWhatInlineFrees, .publicMockRetainsWhatKnownRightFrees, .mockBuildsOtherValuesThanProduction, .valueOracleFixtureRejected, .valueOracleFixtureDoesNotCompile, .builderCallDoesNotCompile, .renamedGraphDiffers].contains(failure.kind)
				|| GraphFuzzerFailure.knownBuilderSurfaceKinds.contains(failure.kind)
			if let unmasked = laterFailures.first(where: { (masksNoLaterFailure || $0.kind == .renamedGraphDiffers || $0.kind == .seamRetainsWhatInlineFrees || $0.kind == .publicMockRetainsWhatKnownRightFrees || $0.kind == .publicMockBuildsOtherValuesThanKnownRight || $0.kind == .levelFunctionKeepsValues || GraphFuzzerFailure.builderSurfaceKindsNeverMasked.contains($0.kind)) && !knownIssue.matches($0) }) {
				self = .failure(unmasked)
			} else {
				self = .knownIssue(knownIssue, failure)
			}
		case let (failure?, _):
			self = .failure(failure)
		}
	}

	/// What the fuzzer concludes about one graph: the finding `init` makes, then each other difference of a renamed
	/// graph that the known issue does not document, as a finding of its own, so that a graph's every undocumented
	/// difference is reported at once, and, when the graph fails at all, each difference of a renamed graph its known
	/// issue lists and it does not show.
	static func findings(failure: GraphFuzzerFailure?, laterFailures: [GraphFuzzerFailure] = [], knownIssue: GraphFuzzerKnownIssue?, retentionIsJudged: Bool = true) -> [GraphFuzzerFinding] {
		let finding = GraphFuzzerFinding(failure: failure, laterFailures: laterFailures, knownIssue: knownIssue, retentionIsJudged: retentionIsJudged)
		var reportedFailure: GraphFuzzerFailure?
		if case let .failure(failure) = finding {
			reportedFailure = failure
		}
		var findings = [finding] + laterFailures
			.filter { $0.kind == .renamedGraphDiffers && $0 != reportedFailure && knownIssue?.matches($0) != true }
			.map(GraphFuzzerFinding.failure)
		if let knownIssue, let failure {
			let shownAspects = Set(([failure] + laterFailures).filter { $0.kind == .renamedGraphDiffers }.compactMap(\.renamedGraphDifference))
			for case let .renamedGraphDiffers(aspect) in knownIssue.signatures where !shownAspects.contains(aspect) {
				findings.append(.staleRenamedGraphDifference(knownIssue, aspect))
			}
			let shownKinds = Set(([failure] + laterFailures).map(\.kind))
			for case let .builderSurface(kind) in knownIssue.signatures where !shownKinds.contains(kind) {
				findings.append(.staleBuilderSurfaceSignature(knownIssue, kind))
			}
			// Each entry a seed's issue combines is judged on its own: a leak the retention oracle judged and no longer finds
			// makes the leak's entry stale, though the seed still fails what its other entries list.
			if retentionIsJudged, knownIssue.documentsLeak, shownKinds.isDisjoint(with: [.seamRetainsWhatInlineFrees, .publicMockRetainsWhatKnownRightFrees]) {
				findings.append(.staleLeakEntry(knownIssue))
			}
		}
		return findings
	}

	/// The line the long run appends to its report, which `graph-fuzzer.yml` reads.
	func reportLine(seed: UInt64) -> String? {
		switch self {
		case .passed:
			nil
		case let .knownIssue(knownIssue, _):
			"known \(seed) \(knownIssue.reason)"
		case let .staleKnownIssue(knownIssue):
			"stale \(seed) \(knownIssue.reason)"
		case let .staleRenamedGraphDifference(knownIssue, aspect):
			"misfiled \(seed) \(knownIssue.reason): the renamed graph does not show \(aspect.rawValue); list the seed under the entry that names exactly what it shows"
		case let .staleBuilderSurfaceSignature(knownIssue, kind):
			"misfiled \(seed) \(knownIssue.reason): the graph does not show \(kind.rawValue); list the seed under the entry that names exactly what it shows"
		case let .staleLeakEntry(knownIssue):
			"stale \(seed) \(knownIssue.reason): the graph no longer keeps alive what its leak's entry lists, though it still fails what the seed's other entries list; remove the seed from the leak's entry"
		case let .failure(failure) where failure.kind == .renamedGraphDiffers:
			// Each difference of a graph is a finding, so its line says which, without the sentence's period.
			"failure \(seed) \(failure.kind.rawValue): \(failure.details.prefix { $0 != "\n" }.dropLast())"
		case let .failure(failure):
			"failure \(seed) \(failure.kind.rawValue)"
		}
	}
}

/// A set of seeds as one number that does not depend on the order seeds are added in, so that the parts shards of
/// the corpus report add up to the whole: the sum, wrapping, of each seed's `GraphFuzzerHash`.
struct GraphFuzzerSeedSetSum {
	private(set) var value: UInt64 = 0

	mutating func add(_ seed: UInt64) {
		add(member: String(seed))
	}

	/// Adds a member named by a string, such as `<seed>:<type>`.
	mutating func add(member: String) {
		var hash = GraphFuzzerHash()
		hash.combine(member)
		value &+= hash.value
	}

	/// A sum whose value is pinned.
	init(value: UInt64 = 0) {
		self.value = value
	}
}

/// FNV-1a over strings, so a pinned value names the same content on every platform.
struct GraphFuzzerHash {
	private(set) var value: UInt64 = 0xCBF29CE484222325

	mutating func combine(_ string: String) {
		for byte in string.utf8 {
			value = (value ^ UInt64(byte)) &* 0x00000100000001B3
		}
		// Separate consecutive strings, so that "ab" then "c" differs from "a" then "bc".
		value = (value ^ 0xFF) &* 0x00000100000001B3
	}
}

/// The run of a graph without its second path to a type that holds a place
/// (`GraphFuzzerGenerator.fixtureWithoutSecondPath(forSeed:features:)`): the property left out, by its type's name and its
/// label, what the tool produced, and the facts of the places it computed.
struct GraphFuzzerSecondPathRun {
	let typeName: String
	let label: String
	let outcome: GraphFuzzerToolOutcome
	let placeFacts: GraphFuzzerPlaceFacts
}

/// A graph with what two runs of the tool produced for it.
@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
struct GraphFuzzerToolRuns {
	/// - Parameters:
	///   - renamedOutcomes: The outcome of the graph renamed by each renaming, with the renaming undone.
	///   - inlineOutcome: The outcome of the graph with no seam, when the graph declares one.
	///   - visibleOutcome: The outcome of the graph's visible build (`GraphFuzzerFixture.withoutHoles`), when the graph
	///     draws a hole.
	///   - knownRightOutcome: The outcome of the known-right path of a graph drawn with `generateMockPublic`
	///     (`GraphFuzzerGenerator.knownRightPublicMockFixture(forSeed:)`).
	///   - multiModuleRuns: What the two multi-module integrations produced for the graph split across modules.
	///   - pluginOutcome: The outcome of a graph split across modules as the SwiftPM plugin runs the tool, when no module
	///     of it is run without its package's name: `firstOutcome` is how Bazel runs it.
	///   - recomputedSignaturesOutcome: The outcome of a graph split across modules that declares a seam, run as
	///     `firstOutcome` was with every module info's seam signatures discarded.
	///   - readTwinOutcome: The outcome of the graph's read twin (`GraphFuzzerFixture.readTwin`) as `firstOutcome` was
	///     run, with its rename undone, when the graph names a type no declaration SafeDI reads declares.
	///   - readTwinPluginOutcome: The outcome of the read twin as `pluginOutcome` was run, with its rename undone, when the
	///     graph has both.
	///   - valueOracle: The value oracle's run of a base corpus graph the tool accepts.
	///   - withoutSecondHolePlaceOutcome: The outcome of the graph without its second place of a hole
	///     (`GraphFuzzerGenerator.fixtureWithoutSecondHolePlace`), when it has one, with the place it leaves out.
	///   - placeLevelDisagreements: Each level of a place of a seam that one build of a type gives with other values than
	///     another build of it, in the run of `firstOutcome` (`SeamPlaceLevels.levelDisagreements()`).
	///   - placeFacts: The facts of the places of every seam's holes the run of `firstOutcome` computes.
	///   - withoutSecondPath: The run of the graph without its second path to a type that holds a place
	///     (`GraphFuzzerGenerator.fixtureWithoutSecondPath(forSeed:features:)`), when it has one.
	///   - remedyRuns: The outcome of each remedy the errors of a rejected base corpus graph state, applied to the graph
	///     (`GraphFuzzerOracle.remedyRuns(of:outcome:)`).
	///   - builderSurfaceRuns: The outcome of the graph with each builder surface edit that applies to it
	///     (`GraphFuzzerBuilderSurfaceEdit`).
	///   - drawnHolePlaces: The places of holes the draw put beneath a lazy wrapper or made forward a value
	///     (`GraphFuzzerGenerator.drawnHolePlaces(forSeed:features:)`), which the builder surface's floors count.
	///   - queryExport: The JSON `query graph` exports for a graph in one module the tool accepts, which
	///     `querySuppliersFailure` compares with the generated code.
	init(
		fixture: GraphFuzzerFixture,
		firstOutcome: GraphFuzzerToolOutcome,
		secondOutcome: GraphFuzzerToolOutcome,
		cleanSubtreeSkipOffOutcome: GraphFuzzerToolOutcome? = nil,
		renamedOutcomes: [(renaming: GraphFuzzerRenaming, outcome: GraphFuzzerToolOutcome)] = [],
		inlineOutcome: GraphFuzzerToolOutcome? = nil,
		visibleOutcome: GraphFuzzerToolOutcome? = nil,
		knownRightOutcome: GraphFuzzerToolOutcome? = nil,
		multiModuleRuns: [GraphFuzzerMultiModuleRuns] = [],
		pluginOutcome: GraphFuzzerToolOutcome? = nil,
		recomputedSignaturesOutcome: GraphFuzzerToolOutcome? = nil,
		readTwinOutcome: GraphFuzzerToolOutcome? = nil,
		readTwinPluginOutcome: GraphFuzzerToolOutcome? = nil,
		valueOracle: GraphFuzzerValueOracleRun? = nil,
		withoutSecondHolePlaceOutcome: (place: String, outcome: GraphFuzzerToolOutcome)? = nil,
		placeLevelDisagreements: [String] = [],
		rootFunctionKeyDisagreements: [String] = [],
		fillsOfCalls: [SeamFillSharing.FillsOfCall] = [],
		placeFacts: GraphFuzzerPlaceFacts = GraphFuzzerPlaceFacts(),
		withoutSecondPath: GraphFuzzerSecondPathRun? = nil,
		remedyRuns: [GraphFuzzerRemedyRun] = [],
		builderSurfaceRuns: [GraphFuzzerBuilderSurfaceRun] = [],
		drawnHolePlaces: [GraphFuzzerDrawnHolePlace] = [],
		queryExport: String? = nil,
	) {
		self.queryExport = queryExport
		self.builderSurfaceRuns = builderSurfaceRuns
		self.drawnHolePlaces = drawnHolePlaces
		self.withoutSecondHolePlaceOutcome = withoutSecondHolePlaceOutcome
		self.placeLevelDisagreements = placeLevelDisagreements
		self.rootFunctionKeyDisagreements = rootFunctionKeyDisagreements
		self.fillsOfCalls = fillsOfCalls
		self.placeFacts = placeFacts
		self.withoutSecondPath = withoutSecondPath
		self.remedyRuns = remedyRuns
		self.fixture = fixture
		self.firstOutcome = firstOutcome
		self.secondOutcome = secondOutcome
		self.cleanSubtreeSkipOffOutcome = cleanSubtreeSkipOffOutcome
		self.renamedOutcomes = renamedOutcomes
		self.inlineOutcome = inlineOutcome
		self.visibleOutcome = visibleOutcome
		self.knownRightOutcome = knownRightOutcome
		self.multiModuleRuns = multiModuleRuns
		self.pluginOutcome = pluginOutcome
		self.recomputedSignaturesOutcome = recomputedSignaturesOutcome
		self.readTwinOutcome = readTwinOutcome
		self.readTwinPluginOutcome = readTwinPluginOutcome
		self.valueOracle = valueOracle
	}

	let fixture: GraphFuzzerFixture
	let firstOutcome: GraphFuzzerToolOutcome
	let secondOutcome: GraphFuzzerToolOutcome
	/// The outcome of a run that skips no clean subtree in the validation walk, when the first run skipped one.
	let cleanSubtreeSkipOffOutcome: GraphFuzzerToolOutcome?
	let renamedOutcomes: [(renaming: GraphFuzzerRenaming, outcome: GraphFuzzerToolOutcome)]
	let inlineOutcome: GraphFuzzerToolOutcome?
	let visibleOutcome: GraphFuzzerToolOutcome?
	let knownRightOutcome: GraphFuzzerToolOutcome?
	let multiModuleRuns: [GraphFuzzerMultiModuleRuns]
	let pluginOutcome: GraphFuzzerToolOutcome?
	/// The outcome of a graph split across modules that declares a seam, run as `firstOutcome` was with every `.safedi`
	/// file's seam signatures discarded, so that each module computes the signatures of the seams it calls.
	let recomputedSignaturesOutcome: GraphFuzzerToolOutcome?
	let readTwinOutcome: GraphFuzzerToolOutcome?
	let readTwinPluginOutcome: GraphFuzzerToolOutcome?
	let valueOracle: GraphFuzzerValueOracleRun?
	let withoutSecondHolePlaceOutcome: (place: String, outcome: GraphFuzzerToolOutcome)?
	let placeLevelDisagreements: [String]
	/// Each key a root reaches root functions of with two texts (`collectingRootFunctionKeyDisagreements(during:)`).
	let rootFunctionKeyDisagreements: [String]
	/// What each seam call that fills a place built in the first run (`SeamFillSharing.observer`).
	let fillsOfCalls: [SeamFillSharing.FillsOfCall]
	let placeFacts: GraphFuzzerPlaceFacts
	let withoutSecondPath: GraphFuzzerSecondPathRun?
	let remedyRuns: [GraphFuzzerRemedyRun]
	let builderSurfaceRuns: [GraphFuzzerBuilderSurfaceRun]
	let drawnHolePlaces: [GraphFuzzerDrawnHolePlace]
	let queryExport: String?

	/// The failure of a graph some place of whose seam's tree has a path that repeats a declaration, or `nil`: the tree
	/// closes a cycle where a declaration is already being built above, and a build that closes a cycle is the first build,
	/// so a scope value's chain never repeats a declaration and a recursive scope enum's value has a bounded depth (the
	/// design's section 2.4). The per-path bodies 2.3.0 generates build each place's scope value from its path, so this
	/// judges their chains; a body with one function per type, after the tag, builds them at run time, which only a run of
	/// the generated code can judge.
	var placeChainFailure: GraphFuzzerFailure? {
		guard !placeFacts.chainRepeats.isEmpty else { return nil }
		return GraphFuzzerFailure(
			seed: fixture.seed,
			kind: .placeChainRepeatsDeclaration,
			details: "\(placeFacts.chainRepeats.joined(separator: "\n"))\nThis graph:\n\(firstOutcome.description)",
		)
	}

	/// Whether the tool accepts the graph and the graph without its second path to a type that holds a place, which
	/// `secondPathFailure` compares.
	var isComparedWithoutSecondPath: Bool {
		guard case .accepted = firstOutcome, case .accepted? = withoutSecondPath?.outcome else { return false }
		return true
	}

	/// The failure of a graph with a second path to a type that holds a place, when the tool accepts it with and without
	/// the path, whose levels (`GraphFuzzerPlaceFacts.secondPathLevelChanges(comparedWith:typeName:label:)`) or scope enums,
	/// cases, structs and fields (`GraphFuzzerScopeDeclarations.secondPathChanges(comparedWith:typeName:label:)`) differ
	/// beyond the case of the
	/// path's own property, or `nil`: a second path to a type that holds a place adds nothing (the design's section 2.10).
	var secondPathFailure: GraphFuzzerFailure? {
		guard case let .accepted(generatedFiles, _) = firstOutcome,
		      let withoutSecondPath,
		      case let .accepted(filesWithoutPath, _) = withoutSecondPath.outcome
		else { return nil }
		var changes = placeFacts.secondPathLevelChanges(comparedWith: withoutSecondPath.placeFacts, typeName: withoutSecondPath.typeName, label: withoutSecondPath.label)
		changes += GraphFuzzerScopeDeclarations(generatedFiles: generatedFiles).secondPathChanges(
			comparedWith: GraphFuzzerScopeDeclarations(generatedFiles: filesWithoutPath),
			typeName: withoutSecondPath.typeName,
			label: withoutSecondPath.label,
		)
		guard !changes.isEmpty else { return nil }
		return GraphFuzzerFailure(
			seed: fixture.seed,
			kind: .secondPathChangesScope,
			details: "The second path `\(withoutSecondPath.typeName).\(withoutSecondPath.label)`:\n\(changes.joined(separator: "\n"))\nThis graph:\n\(firstOutcome.description)\nWithout its second path:\n\(withoutSecondPath.outcome.description)",
		)
	}

	/// The failures of an accepted graph whose generated scope enums, nested by type, disagree with the cases its places'
	/// paths produce (`GraphFuzzerScopeDeclarations`): a produced case no enum declares; in a graph without a tangle of
	/// cycles, an enum, a case of its own or a fill case no path produces; and a case that names no property of its type.
	/// A place inside a fill is judged as every other (`GraphFuzzerPlaceFacts`): its path produces the call's case for the
	/// builder filled, `<call>_<builder>`, and a case of the enum of each type the fill builds. A public mock's enums keep a
	/// case per path inside a fill and are left to the public mock corpus.
	var scopeCaseFailures: [GraphFuzzerFailure] {
		guard case let .accepted(generatedFiles, _) = firstOutcome else { return [] }
		let declarations = GraphFuzzerScopeDeclarations(generatedFiles: generatedFiles)
		var failures = [GraphFuzzerFailure]()
		func append(_ kind: GraphFuzzerFailure.Kind, _ descriptions: [String]) {
			guard !descriptions.isEmpty else { return }
			failures.append(GraphFuzzerFailure(seed: fixture.seed, kind: kind, details: "\(descriptions.joined(separator: "\n"))\nThis graph:\n\(firstOutcome.description)"))
		}
		append(.producedCaseUndeclared, declarations.undeclaredProducedCases(of: placeFacts))
		// A tangle of cycles no type always encloses can keep a case no run produces, which the design accepts.
		if !GraphFuzzerFeature.seamDrawFeatures(of: fixture).contains(.holeTangleOfCycles) {
			append(.declaredCaseNeverProduced, declarations.unproducedDeclaredCases(of: placeFacts))
		}
		append(.scopeCaseNamesNoProperty, declarations.casesNamingNoPropertyOfTheirType(of: placeFacts.addingSeamRootLabels(declaredIn: fixture.swiftFileContent)))
		return failures
	}

	/// The failure of a graph in whose seam's tree two builds of one type bind other values before the same property, or
	/// `nil`: a scope enum nested by type holds one level per type, so what a type binds before a property, the seam's
	/// root's parameters included, must not depend on the path the type is built on, inside a fill the seam generates too
	/// (`SeamPlaceLevels.levelDisagreements()`).
	var placeLevelsFailure: GraphFuzzerFailure? {
		guard !placeLevelDisagreements.isEmpty else { return nil }
		return GraphFuzzerFailure(
			seed: fixture.seed,
			kind: .placeLevelsDifferBetweenBuildsOfType,
			details: "\(placeLevelDisagreements.joined(separator: "\n"))\nThis graph:\n\(firstOutcome.description)",
		)
	}

	/// The failure of an accepted graph that draws `addingPlacesOfOneCaseShapes`' tree whose call of `SameCaseHome` built
	/// other fills in the first run than the draw's own count (`GraphFuzzerFeature.fillsOfPlacesOfOneCase(in:)`), or `nil`:
	/// a fill that generates no code judges only the places that hand their fills the values its own place does, and
	/// every such place after the first. Which fill judges a place reaches no output where the fills' judgments agree,
	/// so the two runs' comparison does not show a fill standing for a place of another kind; this count does. With
	/// `Scope.FillVariant` leaving out the fields a fill's tree receives, seeds 26 and 38 of the seam corpus fail.
	var placesJudgedByAnotherPlacesFillFailure: GraphFuzzerFailure? {
		guard case .accepted = firstOutcome, let expected = GraphFuzzerFeature.fillsOfPlacesOfOneCase(in: fixture) else { return nil }
		let fills = fillsOfCalls.last { $0.calledType == expected.calledType }
		guard fills?.builtFillCount != expected.builtFillCount || fills?.placeStoodForCount != expected.placeStoodForCount else { return nil }
		let built = fills.map { "built \($0.builtFillCount) fills, of which other places’ stand for \($0.placeStoodForCount) places" } ?? "reported no fill"
		return GraphFuzzerFailure(
			seed: fixture.seed,
			kind: .placesJudgedByAnotherPlacesFill,
			details: "The call of `\(expected.calledType)` \(built); its places are of kinds that take \(expected.builtFillCount) fills, standing for \(expected.placeStoodForCount) places.\nThis graph:\n\(firstOutcome.description)",
		)
	}

	/// The failure of a graph one of whose roots reaches two root functions with one key and different text, or `nil`: a
	/// root declares a root function once per name, from the first call that reaches it (`RootFunctionHoisting`), so its
	/// key must name everything its text is a function of. Nothing in the generator compares the text.
	var rootFunctionKeyFailure: GraphFuzzerFailure? {
		guard !rootFunctionKeyDisagreements.isEmpty else { return nil }
		return GraphFuzzerFailure(
			seed: fixture.seed,
			kind: .rootFunctionTextDiffersForOneKey,
			details: "\(rootFunctionKeyDisagreements.joined(separator: "\n"))\nThis graph:\n\(firstOutcome.description)",
		)
	}

	/// The failure of a rejected base corpus graph a remedy one of whose errors states leaves an error at the declaration
	/// the error is at, or `nil`: following an error's advice must fix that error and add none there. Another error
	/// elsewhere is allowed, since a remedy can expose what the tool's walk stopped before or change what another type
	/// receives. Every remedy that leaves one is a line of the failure.
	var remedyFailure: GraphFuzzerFailure? {
		let failingRuns = remedyRuns.filter { $0.failureLine != nil }
		guard !failingRuns.isEmpty else { return nil }
		let remedyFailures = failingRuns.compactMap(\.failureLine)
		let remedies = failingRuns.map { run in
			"The errors at \(run.remedy.site) the \(run.remedy.kind.rawValue) remedy answers:\n\(run.remedy.answeredErrors.joined(separator: "\n"))\nThe remedied graph:\n\(run.remedy.fixture.description)\nIts outcome:\n\(run.outcome.description)"
		}
		return GraphFuzzerFailure(
			seed: fixture.seed,
			kind: .remedyLeavesErrorAtSite,
			details: "\(remedyFailures.joined(separator: "\n"))\n\(remedies.joined(separator: "\n"))",
			remedyFailures: remedyFailures,
		)
	}

	/// Whether the tool accepts the graph and the graph without its second place of a hole, whose names
	/// `holeNameStabilityFailure` compares.
	var isComparedWithoutSecondHolePlace: Bool {
		guard case .accepted = firstOutcome, case .accepted? = withoutSecondHolePlaceOutcome?.outcome else { return false }
		return true
	}

	/// The failure of a graph with a hole whose builder labels, scope types or case names
	/// (`GraphFuzzerOracle.holeBuilderNames(in:)`) without its second place of a hole are not all among those with it,
	/// when the tool accepts both, or `nil`. Adding a place beneath a seam adds names and never changes one (the design's
	/// output stability), so that a hand-written caller of the seam, or of a public mock, that names a case keeps
	/// compiling; but for the shape the design accepts, a known issue: an internal consumer that passes up the places of a
	/// second public mock of the hole's type names the builders it takes for the two mocks apart, after each called type.
	/// Two calls of one public mock share one builder, so a second call only adds a case.
	var holeNameStabilityFailure: GraphFuzzerFailure? {
		guard case let .accepted(generatedFiles, _) = firstOutcome,
		      let withoutSecondHolePlaceOutcome,
		      case let .accepted(filesWithoutPlace, _) = withoutSecondHolePlaceOutcome.outcome
		else { return nil }
		let changedNames = GraphFuzzerOracle.holeBuilderNames(in: filesWithoutPlace).subtracting(GraphFuzzerOracle.holeBuilderNames(in: generatedFiles))
		guard !changedNames.isEmpty else { return nil }
		return GraphFuzzerFailure(
			seed: fixture.seed,
			kind: .holeNamesChangeWithSecondPlace,
			details: "Adding the second place `\(withoutSecondHolePlaceOutcome.place)` removes \(changedNames.sorted().joined(separator: ", ")).\nThis graph:\n\(firstOutcome.description)\nWithout its second place:\n\(withoutSecondHolePlaceOutcome.outcome.description)",
		)
	}

	/// The failure of a base corpus graph's value oracle before anything is compiled, or `nil`: the mirror model
	/// disagrees with a generated mock, the tool rejects the value-oracle fixture, the fixture changes a mock the graph
	/// generates, or a root's mock takes a parameter. Such a graph is not compared.
	var valueOracleFixtureFailure: GraphFuzzerFailure? {
		guard let valueOracle else { return nil }
		let plan = valueOracle.plan
		guard plan.modelFailures.isEmpty else {
			return GraphFuzzerFailure(seed: fixture.seed, kind: .mirrorModelDisagreesWithMock, details: "\(plan.modelFailures.joined(separator: "\n"))\nThis graph:\n\(firstOutcome.description)")
		}
		guard let outcome = valueOracle.outcome else { return nil }
		let fixtureDescription = "The value-oracle fixture:\n\(plan.valueOracleFixture(storingEveryParameter: false).description)"
		switch outcome {
		case let .rejected(diagnostics):
			return GraphFuzzerFailure(
				seed: fixture.seed,
				kind: .valueOracleFixtureRejected,
				details: "\(diagnostics)\n\(fixtureDescription)",
				rejectionErrorLines: diagnostics.split(separator: "\n").filter { $0.contains(": error: ") }.map(String.init),
			)
		case let .accepted(valueOracleFiles, _):
			guard plan.mirrorNamesSortingBeforeTypeNames.isEmpty else {
				return GraphFuzzerFailure(seed: fixture.seed, kind: .valueOracleFixtureChangesDrawnMocks, details: "The graph declares \(plan.mirrorNamesSortingBeforeTypeNames), which sort after a mirror's name, so a mirror can change the order of the tool's alphabetical walks.\n\(fixtureDescription)")
			}
			// A mocked type's file also holds the configuration of the type for the mocks that build it, which the root
			// mocks the fixture adds can need where no mock of the graph did, and a root mock can make a configuration
			// `@Sendable`-typed: neither is compared (`GraphFuzzerMockOverrides.comparableWithAnotherRunsMocks`), and the
			// files that differ only so are counted and pinned.
			let mockFileSuffix = "+SafeDIMock.swift"
			let changedMocks = valueOracle.drawnMockFileNamesChanged
			guard changedMocks.isEmpty else {
				let changes = changedMocks.map { "\($0) as the corpus run generates it:\n\(plan.drawnMockFiles[$0] ?? "")\nAs the value-oracle run generates it:\n\(valueOracleFiles[$0] ?? "(none)")" }
				return GraphFuzzerFailure(seed: fixture.seed, kind: .valueOracleFixtureChangesDrawnMocks, details: "\(changes.joined(separator: "\n"))\n\(fixtureDescription)")
			}
			let rootMocksTakingParameters = plan.rootTypeNames.compactMap { rootTypeName -> String? in
				let parameters = GraphFuzzerMockOverrides.mockParameters(valueOracleFiles[rootTypeName + mockFileSuffix] ?? "")
					.filter { !$0.hasPrefix("safeDIOverrides: ") }
				return parameters.isEmpty ? nil : "`\(rootTypeName).mock` takes \(parameters.joined(separator: " "))"
			}
			guard rootMocksTakingParameters.isEmpty else {
				return GraphFuzzerFailure(seed: fixture.seed, kind: .rootMockTakesParameter, details: "\(rootMocksTakingParameters.joined(separator: "\n"))\n\(fixtureDescription)")
			}
			return nil
		}
	}

	/// The failure of each partitioned run whose two integrations give other results, in the order the runs were made.
	var multiModuleFailures: [GraphFuzzerFailure] {
		multiModuleRuns.compactMap(\.failure)
	}

	/// The failure of a graph that names a type no declaration SafeDI reads declares whose read twin
	/// (`GraphFuzzerFixture.readTwin`), which declares that type `public` where SafeDI reads it, gets another outcome
	/// than the graph under either flow the oracle runs both under, beyond what `GraphFuzzerReadTwin.difference(between:and:)`
	/// allows, or `nil`.
	var readTwinFailure: GraphFuzzerFailure? {
		guard let readTwin = fixture.readTwin else { return nil }
		let comparisons = [
			(flow: "", outcome: firstOutcome, twinOutcome: readTwinOutcome),
			(flow: ", as the SwiftPM plugin runs the tool", outcome: pluginOutcome, twinOutcome: readTwinPluginOutcome),
		]
		for comparison in comparisons {
			guard let outcome = comparison.outcome, let twinOutcome = comparison.twinOutcome,
			      let difference = readTwin.difference(between: outcome, and: twinOutcome)
			else { continue }
			return GraphFuzzerFailure(
				seed: fixture.seed,
				kind: .readTwinDiffers,
				details: "Declaring \(readTwin.unreadTypeNames) `public` where SafeDI reads it changes \(difference)\(comparison.flow).\nThis graph:\n\(outcome.description)\nIts read twin, with its rename undone:\n\(twinOutcome.description)",
			)
		}
		return nil
	}

	/// The failure of a graph whose seam takes a builder for a hole that the tool accepts while it rejects the graph's
	/// visible build, or `nil`: a fill may be rejected where inline would read another value, but what the seam's module
	/// rejects building inline, a fill must reject too.
	var visibleBuildFailure: GraphFuzzerFailure? {
		guard case .accepted = firstOutcome, case let .rejected(diagnostics) = visibleOutcome else { return nil }
		return GraphFuzzerFailure(
			seed: fixture.seed,
			kind: .holeAcceptedWhereVisibleBuildRejects,
			details: "With the hole:\n\(firstOutcome.description)\nThe visible build:\n\(diagnostics)",
		)
	}

	/// The failure of a graph the tool rejects with the seam declared and accepts without it, where the rejection
	/// is not one of a seam's own errors (`GraphFuzzerOracle.isSeamOnlyRejection`) but an error of the inlined
	/// validation, which the seam world should not add, or `nil`. A seam's own error is what the seam rules reject
	/// that inline accepts; any other error is a shape the seam world sees differently than inline, a defect.
	var differentialFailure: GraphFuzzerFailure? {
		// In a graph split across modules, a caller's error that it holds a value its tier omits is a seam's own, which
		// `omittedValueFailure` judges; in a graph in one module, whose seams are called at their narrowest tier, it is
		// never one.
		guard case let .rejected(diagnostics) = firstOutcome, case .accepted = inlineOutcome,
		      !GraphFuzzerOracle.isSeamOnlyRejection(diagnostics: diagnostics, seamTypeNames: fixture.seamTypeNames, excusingOmittedValues: fixture.modules != nil)
		else { return nil }
		return GraphFuzzerFailure(
			seed: fixture.seed,
			kind: .seamRejectsGraphInlineAccepts,
			details: "With the seam:\n\(diagnostics)\nWithout it, the tool accepts the graph.",
		)
	}

	/// The failure of a graph in one module the tool accepts with its seam and rejects with no seam, or `nil`: in one
	/// module the seam world adds rules to the inlined validation and removes none (`seamAcceptsGraphInlineRejects`).
	var acceptanceDifferentialFailure: GraphFuzzerFailure? {
		guard fixture.modules == nil, case .accepted = firstOutcome, case let .rejected(diagnostics) = inlineOutcome else { return nil }
		return GraphFuzzerFailure(
			seed: fixture.seed,
			kind: .seamAcceptsGraphInlineRejects,
			details: "With the seam, the tool accepts the graph.\nWithout it:\n\(diagnostics)",
		)
	}

	/// The failure of a graph split across modules that the SwiftPM plugin flow and the module-info flow give another
	/// verdict, other diagnostics, or other generated declarations (`GraphFuzzerOracle.integrationComparedBlocks(of:)`),
	/// but for the plugin flow's assertions of decisions about blocks in a dependency's files
	/// (`GraphFuzzerOracle.firstDeclarationOneIntegrationGenerates`), or `nil`. Both flows lay a module's files out at the
	/// same paths, so their diagnostics are compared as they are.
	var integrationsDisagreeFailure: GraphFuzzerFailure? {
		guard let pluginOutcome else { return nil }
		let difference: String? = switch (firstOutcome, pluginOutcome) {
		case let (.rejected(moduleInfoDiagnostics), .rejected(pluginDiagnostics)):
			moduleInfoDiagnostics == pluginDiagnostics ? nil : "The two flows report other diagnostics."
		case let (.accepted(moduleInfoFiles, _), .accepted(pluginFiles, _)):
			GraphFuzzerOracle.firstDeclarationOneIntegrationGenerates(moduleInfoFiles: moduleInfoFiles, pluginFiles: pluginFiles, conditionsSpelledOnlyInDependencies: fixture.conditionsSpelledOnlyInDependencies)
		case (.accepted, .rejected):
			"The module-info flow accepts the graph, and the SwiftPM plugin flow rejects it."
		case (.rejected, .accepted):
			"The module-info flow rejects the graph, and the SwiftPM plugin flow accepts it."
		}
		guard let difference else { return nil }
		return GraphFuzzerFailure(
			seed: fixture.seed,
			kind: .integrationsDisagree,
			details: "\(difference)\nThe module-info flow:\n\(firstOutcome.description)\nThe SwiftPM plugin flow:\n\(pluginOutcome.description)",
		)
	}

	/// The failure of a graph split across modules whose modules generate other code or report other diagnostics when each
	/// reads the signatures of the seams it calls, and the plans of the public mocks its mocks call, from their modules'
	/// `.safedi` files than when it computes them again from the declarations those files carry, or `nil`: a module's
	/// stored signature or plan must be the one each caller would compute.
	var storedSeamSignaturesDisagreeFailure: GraphFuzzerFailure? {
		guard let recomputedSignaturesOutcome, recomputedSignaturesOutcome != firstOutcome else { return nil }
		return GraphFuzzerFailure(
			seed: fixture.seed,
			kind: .storedSeamSignaturesDisagree,
			details: "Reading the stored signatures:\n\(firstOutcome.description)\nComputing them again:\n\(recomputedSignaturesOutcome.description)",
		)
	}

	/// The failure of a graph whose `addingUncreatedAliasShapes` seam the tool rejects, with an error about that seam,
	/// where it accepts the graph with no seam, or `nil`. The seam binds an `onlyIfAvailable` alias of a parameter from
	/// that parameter as inline binds it from the caller's nearest declaration of its label, and that seam's tree has no
	/// shape any other seam rule rejects, so the seam must accept every graph inline accepts.
	var seamRejectedWhereInlineAcceptsFailure: GraphFuzzerFailure? {
		guard case let .rejected(diagnostics) = firstOutcome, case .accepted = inlineOutcome else { return nil }
		let aliasSeamName = "dependency tree of `\(fixture.typeNamePrefix)AliasSeam`"
		guard diagnostics.split(separator: "\n").contains(where: { $0.contains(": error: ") && $0.contains(aliasSeamName) }) else { return nil }
		return GraphFuzzerFailure(
			seed: fixture.seed,
			kind: .seamRejectedWhereInlineAccepts,
			details: "With the seam:\n\(diagnostics)\nWithout it, the tool accepts the graph.",
		)
	}

	/// The failure of a graph the tool accepts whose generated seam tier is wider than a type one of its parameters
	/// names, by the access the generator gave each type it drew (`GraphFuzzerGenerator.narrowerTypeAccess`), or `nil`.
	var tierAccessFailure: GraphFuzzerFailure? {
		// A public mock graph's generated declarations are judged by `publicMockAccessFailure`.
		guard knownRightOutcome == nil, case let .accepted(seamFiles, _) = firstOutcome else { return nil }
		let findings = GraphFuzzerOracle.tiersWiderThanParameterTypes(
			in: seamFiles,
			typeAccess: GraphFuzzerGenerator.narrowerTypeAccess(forSeed: fixture.seed, features: GraphFuzzerGeneratorFeature.features(drawnIn: fixture)),
		)
		guard !findings.isEmpty else { return nil }
		return GraphFuzzerFailure(seed: fixture.seed, kind: .seamTierWiderThanParameterType, details: "\(findings.joined(separator: "\n"))\nThis graph:\n\(firstOutcome.description)")
	}

	/// The failure of a graph split across modules whose `ProofSeam` call in a caller's module omits a parameter
	/// against what the caller's inline build does, or `nil`. Inline, each type of the seam's tree is built in the
	/// caller's module, so the inline build shows which receivers the caller hands a value. The tool must report an
	/// error exactly where a tier a caller calls omits a parameter some receiver of which the inline build passes a
	/// value – a binding, rather than `nil` – so an accepted graph whose call omits such a parameter fails, as does an
	/// error that a caller holds a value its tier omits where the inline build passes every receiver of it `nil`.
	/// Judged only where the tool accepts the graph inline; an alias's receiver is not followed.
	var omittedValueFailure: GraphFuzzerFailure? {
		guard fixture.modules != nil, case let .accepted(inlineFiles, _) = inlineOutcome else { return nil }
		let seamName = fixture.typeNamePrefix + "ProofSeam"
		var receiversByLabel = [String: Set<String>]()
		for content in fixture.swiftFileContent {
			var currentType: String?
			for line in GraphFuzzerSourceLine.lines(of: content) {
				switch line {
				case let .typeDeclaration(name):
					currentType = name
				case let .property(attribute, label, _):
					if let currentType, attribute == "@Received" || attribute == "@Received(onlyIfAvailable: true)" {
						receiversByLabel[label, default: []].insert(currentType)
					}
				case .instantiableAttribute, .instantiateMethod, .other:
					break
				}
			}
		}
		/// Whether the inline build of `module` passes some receiver of `label` a value.
		func inlinePassesValue(for label: String, in module: GraphFuzzerModule) -> Bool {
			inlineFiles.contains { fileName, contents in
				fileName.hasPrefix(module.name + "/") && (receiversByLabel[label] ?? []).contains { receiver in
					GraphFuzzerOracle.initializerCalls(of: receiver, in: contents).contains { call in
						call.contains { $0.label == label && $0.value != "nil" }
					}
				}
			}
		}
		var findings = [String]()
		let kind: GraphFuzzerFailure.Kind
		switch firstOutcome {
		case let .accepted(seamFiles, _):
			kind = .seamTierOmitsValueInlinePasses
			let parameterLabels = Set(seamFiles.values.flatMap { GraphFuzzerOracle.seamInitializers(inGeneratedFile: $0) }.filter { $0.seamTypeName == seamName }.flatMap { tier in
				tier.parameters.map { $0.prefix { $0 != ":" }.trimmingCharacters(in: .whitespaces) }
			})
			for module in [GraphFuzzerModule.samePackageCaller, .otherPackageCaller] {
				for (fileName, contents) in seamFiles.sorted(by: { $0.key < $1.key }) where fileName.hasPrefix(module.name + "/") && !fileName.hasSuffix("+SafeDISeamCaller.swift") {
					for call in GraphFuzzerOracle.initializerCalls(of: seamName, in: contents) {
						let passedLabels = call.map { $0.label.hasPrefix("__safeDI_") ? String($0.label.dropFirst("__safeDI_".count)) : $0.label }
						for label in parameterLabels.subtracting(passedLabels).sorted() where inlinePassesValue(for: label, in: module) {
							findings.append("\(fileName) calls `\(seamName)` without `\(label)`, which the inline build of \(module.name) passes a receiver a value for, and the tool reports no error.")
						}
					}
				}
			}
		case let .rejected(diagnostics):
			kind = .seamTierOmitsProvidedValueReportedWhereInlinePassesNil
			// An outer seam that takes the value from its own callers reports the omission whatever its callers hold, which
			// the inline build of this graph's callers cannot judge.
			for error in diagnostics.split(separator: "\n") where error.contains(": error: ") && !GraphFuzzerOracle.isOuterSeamOmittedValueError(error) {
				guard let label = GraphFuzzerOracle.omittedValueLabel(of: error),
				      let module = [GraphFuzzerModule.samePackageCaller, .otherPackageCaller].first(where: { error.contains("/Sources/\($0.name)/") }),
				      !inlinePassesValue(for: label, in: module)
				else { continue }
				findings.append("The tool reports that \(module.name) holds `\(label)`, but the inline build of \(module.name) passes every receiver of it `nil`: \(error)")
			}
		}
		guard !findings.isEmpty else { return nil }
		return GraphFuzzerFailure(seed: fixture.seed, kind: kind, details: "\(findings.joined(separator: "\n"))\nThis graph:\n\(firstOutcome.description)\nInline:\n\(inlineOutcome?.description ?? "")")
	}

	/// Whether the value oracle inspected the graph: the tool accepts it with the seam and without it, or accepts a
	/// `generateMockPublic` graph and its known-right path, or accepts a base corpus graph, whose value-oracle run then
	/// judges it.
	var isInspectedByValueOracle: Bool {
		guard case .accepted = firstOutcome else { return false }
		guard valueOracle == nil else { return true }
		switch (inlineOutcome, knownRightOutcome) {
		case (.accepted?, _), (_, .accepted?):
			return true
		case (.rejected?, _), (_, .rejected?), (nil, nil):
			return false
		}
	}

	/// The failure of a graph the tool accepts with the seam and without it, whose generated code, over the whole
	/// module, passes a literal `nil` to some argument of some type's construction more often with the seam than
	/// without it, or `nil`. A seam that passes `nil` where inline passes a value loses a value a receiver gets today.
	/// The constructions of a seam type itself are not compared: its own tiers and the calls of them pass `nil` for
	/// what a tier omits, which inline has no counterpart of. A seam that reads a value inline does not (the
	/// documented divergences) lowers its count, which is no failure. A literal `nil` a call of a builder function passes
	/// for a label – a cycle parameter of a function a lazy cycle closes on – counts at each construction in the function's
	/// body that passes the parameter on by name (`GraphFuzzerOracle.nilArgumentCountsThroughBuilderFunctions`), on both
	/// sides: inline's `nil` reaches those constructions through the parameter, where a seam's fill can write it at each.
	/// Where inline passes an argument `nil` in a shared builder function, whose code stands for places its text does not
	/// count (`GraphFuzzerOracle.nilArgumentKeysInSharedBuilderFunctions`), only a seam that passes it `nil` where inline
	/// never does fails; the value oracle compares what each place builds. The seam's count is the number of times its
	/// text passes `nil`, which is at most its number of places, so comparing it with an exact inline count is sound.
	var nilArgumentFailure: GraphFuzzerFailure? {
		guard case let .accepted(seamFiles, _) = firstOutcome, case let .accepted(inlineFiles, _) = inlineOutcome else { return nil }
		let seamTypeNames = Set(fixture.swiftFileContent.flatMap { content -> [String] in
			var nextTypeIsSeam = false
			var names = [String]()
			for line in GraphFuzzerSourceLine.lines(of: content) {
				switch line {
				case let .instantiableAttribute(arguments):
					nextTypeIsSeam = arguments.contains("generateDependencyTree: true")
				case let .typeDeclaration(name):
					if nextTypeIsSeam {
						names.append(name)
					}
					nextTypeIsSeam = false
				case .instantiateMethod, .property, .other:
					break
				}
			}
			return names
		})
		func counts(in files: [String: String]) -> [String: Int] {
			GraphFuzzerOracle.nilArgumentCounts(in: files, typeNamePrefix: fixture.typeNamePrefix, excluding: seamTypeNames).merging(
				GraphFuzzerOracle.nilArgumentCountsThroughBuilderFunctions(in: files, typeNamePrefix: fixture.typeNamePrefix, excluding: seamTypeNames),
				uniquingKeysWith: +,
			)
		}
		let inlineSharedKeys = GraphFuzzerOracle.nilArgumentKeysInSharedBuilderFunctions(in: inlineFiles, typeNamePrefix: fixture.typeNamePrefix, excluding: seamTypeNames)
		let inlineCounts = counts(in: inlineFiles)
		let differences = GraphFuzzerOracle.nilArgumentCountsExceeding(counts(in: seamFiles).filter { !inlineSharedKeys.contains($0.key) }, inlineCounts)
		guard !differences.isEmpty else { return nil }
		return GraphFuzzerFailure(
			seed: fixture.seed,
			kind: .seamPassesNilWhereInlinePassesValue,
			details: "\(differences.joined(separator: "\n"))\nWith the seam:\n\(firstOutcome.description)\nWithout it:\n\(inlineOutcome?.description ?? "")",
		)
	}

	/// A failure for each way a renamed graph, with its renaming undone, differs, in the order of the renamings: another
	/// verdict, other diagnostics or warnings in any order (the tool sorts them by file, and the files are renamed),
	/// each diagnostic's suggestions in any order, other generated file names, or the code of each generated file that
	/// differs by more than the order of its extensions.
	var renamedGraphFailures: [GraphFuzzerFailure] {
		renamedGraphFailures(refutingOrderOf: [:])
	}

	/// `renamedGraphFailures`, where the renamed graph at each index of `renamedOutcomes` that `refutations` lists has a
	/// difference of the order of its label-sorted lists that its code does not bear out: the code, with its renaming undone,
	/// does not compile with the graph, or builds other values than the graph's own code
	/// (`GraphFuzzerOracle.valueComparisons(of:isolatingValueGraphsOf:)`). Each such difference is the file's code
	/// (`dependencyTreeCode`), with what refuted the order.
	func renamedGraphFailures(refutingOrderOf refutations: [Int: String]) -> [GraphFuzzerFailure] {
		renamedOutcomes.enumerated().flatMap { index, renamed in
			let (renaming, outcome) = renamed
			return GraphFuzzerToolOutcome.differences(between: firstOutcome, and: outcome, comparingCode: .inAnyOrderOfExtensions, renaming: renaming, of: fixture).map { difference in
				let refutation = difference.aspect == .dependencyTreeListOrder ? refutations[index] : nil
				let reportedDifference = refutation == nil ? difference : GraphFuzzerOutcomeDifference(aspect: .dependencyTreeCode, fileName: difference.fileName)
				return GraphFuzzerFailure(
					seed: fixture.seed,
					kind: .renamedGraphDiffers,
					details: "\(renaming.description.prefix(1).uppercased())\(renaming.description.dropFirst()) changes \(reportedDifference.description).\(refutation.map { "\n\($0)" } ?? "")\nThis graph:\n\(firstOutcome.description)\nThe renamed graph, with its renaming undone:\n\(outcome.description)",
					renamedGraphDifference: reportedDifference.aspect,
				)
			}
		}
	}

	/// The index in `renamedOutcomes` and the generated files of each renamed graph the tool accepted whose code differs
	/// from this graph's in the order of its label-sorted lists (`dependencyTreeListOrder`): code that, with its renaming
	/// undone, must compile with this graph and build its values.
	var renamedOutcomesDifferingInListOrder: [(index: Int, generatedFiles: [String: String])] {
		renamedOutcomes.enumerated().compactMap { index, renamed in
			guard case let .accepted(generatedFiles, _) = renamed.outcome,
			      GraphFuzzerToolOutcome.differences(between: firstOutcome, and: renamed.outcome, comparingCode: .inAnyOrderOfExtensions, renaming: renamed.renaming, of: fixture).contains(where: { $0.aspect == .dependencyTreeListOrder })
			else { return nil }
			return (index, generatedFiles)
		}
	}

	/// The failure of a graph whose run with no skip of a clean subtree in the validation walk gives other results than its
	/// first run, which skipped one, or `nil`: a skipped subtree's walk along another path completed with an equal context and
	/// found nothing, so walking it again would find nothing either (`cycle-validation.md`, "Clean subtrees"). Seeds 10 and 17
	/// of the seam corpus fail it when the walk remembers a subtree whose walk raised `memoBlockingEventCount`.
	var cleanSubtreeSkipFailure: GraphFuzzerFailure? {
		guard let cleanSubtreeSkipOffOutcome, cleanSubtreeSkipOffOutcome != firstOutcome else { return nil }
		return GraphFuzzerFailure(
			seed: fixture.seed,
			kind: .cleanSubtreeSkipChangesOutcome,
			details: "Skipping clean subtrees:\n\(firstOutcome.description)\nSkipping none:\n\(cleanSubtreeSkipOffOutcome.description)",
		)
	}

	var runsDifferFailure: GraphFuzzerFailure? {
		guard firstOutcome != secondOutcome else { return nil }
		return GraphFuzzerFailure(
			seed: fixture.seed,
			kind: .runsDiffer,
			details: "First run:\n\(firstOutcome.description)\nSecond run:\n\(secondOutcome.description)",
		)
	}

	/// The failure of a graph whose generated internal `mock()` takes a `LazilyInstantiated` or `SendableLazilyInstantiated`
	/// parameter, spelled as itself or, beneath a `Sendable` wrapper, as a `@Sendable` autoclosure of it, that is neither a
	/// property the mocked type forwards nor one a type the mock builds instantiates and the mock cannot build, or `nil`
	/// when none does. An internal mock takes the instance of a dependency its tree receives as a wrapper it cannot build,
	/// and wraps the instance for the receivers, so a type's mock has the same parameters whether the dependencies it
	/// receives are lazily instantiated or not. A public mock takes the wrapper its tree receives ("A lazy value a public
	/// mock takes" in `public-mock-builders.md`), so its file, which declares the mock's guard enum, is not judged here: the
	/// value differential's creation stamps fail a public mock that reads the value before the tree does. A wrapper that a type the mock builds instantiates and that no declaration the mock's
	/// module sees fulfills, the mock takes as that wrapper (`mock-generation.md`). The oracle reads which types the mock
	/// builds, and which of their instantiated dependencies no scope builds, from the mirror model of the declarations the
	/// mock's module sees (`GraphFuzzerMockMirrorModel.mockRoot`, `propertiesToGenerate`), and pairs each such parameter
	/// with one of those declarations of its type whose label it carries, alone or named apart (`<label>_…`).
	var wrapperParameterFailure: GraphFuzzerFailure? {
		let mockFileSuffix = "+SafeDIMock.swift"
		var modelByModuleName = [String: GraphFuzzerMockMirrorModel]()
		var wrapperParameters = [String]()
		for (fileName, contents) in generatedFiles.sorted(by: { $0.key < $1.key }) where fileName.hasSuffix(mockFileSuffix) {
			// A split graph's generated files are keyed by their module's name.
			let pathComponents = fileName.dropLast(mockFileSuffix.count).split(separator: "/")
			let mockedTypeName = String(pathComponents.last ?? "")
			let moduleName = pathComponents.count > 1 ? String(pathComponents[0]) : ""
			let model = modelByModuleName[moduleName] ?? mirrorModel(ofDeclarationsSeenByModuleNamed: moduleName)
			modelByModuleName[moduleName] = model
			let lines = contents.split(separator: "\n", omittingEmptySubsequences: false).map { $0.trimmingCharacters(in: .whitespaces) }
			guard let signatureStart = lines.firstIndex(where: { $0.hasSuffix("static func mock(") }) else { continue }
			let modeledTypeName = GraphFuzzerMockMirrorModel.unqualifiedName(of: mockedTypeName)
			guard !contents.contains("enum __safeDI_\(modeledTypeName)_mock_") else { continue }
			let mockedTypeDependencies = model.types[modeledTypeName]?.dependencies ?? []
			let forwardedWrapperTypes = Set(mockedTypeDependencies.filter { $0.source == .forwarded }.map(\.property.type))
			// One entry per declaration, in the order the mock's tree reaches the declaring types.
			var unpairedInstantiatedProperties = [GraphFuzzerMirrorProperty]()
			var cache = GraphFuzzerMockMirrorModel.ReceivedPropertiesCache()
			let typeNamesTheMockBuilds = model.types[modeledTypeName] == nil ? [] : model.mockRoot(ofTypeNamed: modeledTypeName, cache: &cache).typeNamesInTree
			for typeName in typeNamesTheMockBuilds {
				let propertiesToGenerate = model.propertiesToGenerate(ofTypeNamed: typeName)
				for dependency in model.types[typeName]?.dependencies ?? [] {
					if case .instantiated = dependency.source, !propertiesToGenerate.contains(where: { $0.property == dependency.property }) {
						unpairedInstantiatedProperties.append(dependency.property)
					}
				}
			}
			var unpairedParameters = [(parameter: GraphFuzzerMirrorProperty, spelling: String)]()
			for line in lines[(signatureStart + 1)...].prefix(while: { !$0.hasPrefix(")") }) {
				guard let typeStart = line.range(of: ": ") else { continue }
				let spelledType = String(line[typeStart.upperBound...].prefix { $0 != "=" && $0 != "," }).trimmingCharacters(in: .whitespaces)
				// Beneath a `Sendable` wrapper the mock takes the value as `@autoclosure @escaping @Sendable () -> T`.
				let autoclosureArrow = spelledType.hasPrefix("@autoclosure ") ? spelledType.range(of: "() -> ") : nil
				let type = autoclosureArrow.map { String(spelledType[$0.upperBound...]) } ?? spelledType
				if type.hasPrefix("LazilyInstantiated<") || type.hasPrefix("SendableLazilyInstantiated<"),
				   !forwardedWrapperTypes.contains(type)
				{
					let label = String(line[..<typeStart.lowerBound])
					unpairedParameters.append((GraphFuzzerMirrorProperty(label: label, type: type), "\(label): \(spelledType)"))
				}
			}
			// A parameter that keeps its declaration's label pairs first, so that a parameter named apart cannot take the
			// declaration it names away from it. A label written as a keyword is compared without its backticks, which the
			// declaration and the parameter can spell differently.
			for keepsLabel in [true, false] {
				var stillUnpairedParameters = [(parameter: GraphFuzzerMirrorProperty, spelling: String)]()
				for unpaired in unpairedParameters {
					let parameter = unpaired.parameter
					let parameterLabel = parameter.label.replacingOccurrences(of: "`", with: "")
					if let index = unpairedInstantiatedProperties.firstIndex(where: { declaration in
						let declarationLabel = declaration.label.replacingOccurrences(of: "`", with: "")
						return declaration.type == parameter.type && (keepsLabel ? parameterLabel == declarationLabel : parameterLabel.hasPrefix(declarationLabel + "_"))
					}) {
						unpairedInstantiatedProperties.remove(at: index)
					} else {
						stillUnpairedParameters.append(unpaired)
					}
				}
				unpairedParameters = stillUnpairedParameters
			}
			wrapperParameters += unpairedParameters.map { "`\(mockedTypeName).mock` takes `\($0.spelling)`." }
		}
		guard !wrapperParameters.isEmpty else { return nil }
		return GraphFuzzerFailure(
			seed: fixture.seed,
			kind: .mockTakesWrapperParameterForReceive,
			details: "\(wrapperParameters.joined(separator: "\n"))\nThis graph:\n\(firstOutcome.description)",
		)
	}

	/// The failure of a base corpus graph whose generated mock builds a type that has a hand-written mock with the type's
	/// initializer, or `nil`. A generated mock builds such a type by calling its hand-written mock (`mock`, or the method
	/// `customMockName` names, in its body or in a `mockOnly` declaration), so no mock file names the type's initializer.
	/// The value oracle cannot see this, since every drawn hand-written mock builds what the initializer builds. Only a
	/// base corpus graph is judged, whose one module holds every declaration of every type.
	var handWrittenMockBypassFailure: GraphFuzzerFailure? {
		guard GraphFuzzerGeneratorFeature.features(drawnIn: fixture).isEmpty, fixture.modules == nil else { return nil }
		let typeNames = Self.typeNamesWithHandWrittenMocks(in: fixture)
		guard !typeNames.isEmpty else { return nil }
		var constructions = [String]()
		for (fileName, contents) in generatedFiles.sorted(by: { $0.key < $1.key }) where fileName.hasSuffix("+SafeDIMock.swift") {
			let lines = contents.split(separator: "\n").map { $0.trimmingCharacters(in: .whitespaces) }
			for line in lines where !line.hasPrefix("//") {
				for typeName in typeNames where Self.callsInitializer(of: typeName, in: line) {
					constructions.append("`\(fileName)` builds `\(typeName)` with its initializer, not its hand-written mock: \(line)")
				}
			}
		}
		guard !constructions.isEmpty else { return nil }
		return GraphFuzzerFailure(
			seed: fixture.seed,
			kind: .generatedMockBypassesHandWrittenMock,
			details: "\(constructions.joined(separator: "\n"))\nThis graph:\n\(firstOutcome.description)",
		)
	}

	/// The names of the types `fixture` declares a hand-written mock of, sorted: the type each static method named `mock`,
	/// or named by a `customMockName` the fixture spells, returns, written on one line as
	/// `static func <name>(<parameters>) -> <Type> {`.
	private static func typeNamesWithHandWrittenMocks(in fixture: GraphFuzzerFixture) -> [String] {
		var mockNames: Set = ["mock"]
		for content in fixture.swiftFileContent {
			var remaining = content[...]
			while let range = remaining.range(of: "customMockName: \"") {
				remaining = remaining[range.upperBound...]
				mockNames.insert(String(remaining.prefix { $0 != "\"" }))
			}
		}
		var typeNames = Set<String>()
		for content in fixture.swiftFileContent {
			for line in content.split(separator: "\n") {
				guard let start = line.range(of: "static func "),
				      let open = line[start.upperBound...].firstIndex(of: "("),
				      mockNames.contains(String(line[start.upperBound..<open])),
				      let close = line.range(of: ") -> ", options: .backwards),
				      line.hasSuffix(" {")
				else { continue }
				let returnType = line[close.upperBound...].dropLast(" {".count)
				typeNames.insert(String(returnType.split(separator: ".").last ?? returnType))
			}
		}
		return typeNames.sorted()
	}

	/// Whether `line` calls the initializer of the type named `typeName`, spelled `<typeName>(` or `<typeName>.init`, alone
	/// or qualified.
	private static func callsInitializer(of typeName: String, in line: String) -> Bool {
		func isIdentifierCharacter(_ character: Character) -> Bool {
			character.isLetter || character.isNumber || character == "_"
		}
		var searchStart = line.startIndex
		var callsInitializer = false
		while !callsInitializer, let range = line.range(of: typeName, range: searchStart..<line.endIndex) {
			searchStart = range.upperBound
			let rest = line[range.upperBound...]
			let characterAfterInit = rest.dropFirst(".init".count).first
			let startsName = range.lowerBound == line.startIndex || !isIdentifierCharacter(line[line.index(before: range.lowerBound)])
			let namesInitializer = rest.hasPrefix("(") || (rest.hasPrefix(".init") && !(characterAfterInit.map(isIdentifierCharacter) ?? false))
			callsInitializer = startsName && namesInitializer
		}
		return callsInitializer
	}

	/// The mirror model of the declarations the module named `moduleName` sees: its own files' and those of the modules
	/// it depends on, directly or through another, or every file's in a graph in one module.
	private func mirrorModel(ofDeclarationsSeenByModuleNamed moduleName: String) -> GraphFuzzerMockMirrorModel {
		var seenFiles = fixture.swiftFileContent
		if let modules = fixture.modules, let module = GraphFuzzerModule(rawValue: moduleName) {
			var seenModules: Set = [module]
			var pendingModules = module.dependencies
			while let dependency = pendingModules.popLast() {
				if seenModules.insert(dependency).inserted {
					pendingModules += dependency.dependencies
				}
			}
			seenFiles = zip(modules, fixture.swiftFileContent).filter { seenModules.contains($0.0) }.map(\.1)
		}
		return GraphFuzzerMockMirrorModel(
			fixture: GraphFuzzerFixture(seed: fixture.seed, swiftFileContent: seenFiles),
			readsExistentialAndQualifiedSpellings: true,
		)
	}

	var generatedFiles: [String: String] {
		switch firstOutcome {
		case let .accepted(generatedFiles, _):
			generatedFiles
		case .rejected:
			[:]
		}
	}
}

@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
enum GraphFuzzerOracle {
	/// Runs each seed's graph through SafeDITool twice, renamed by each renaming, and, when it declares no seam and no
	/// public mock, split across modules through both multi-module integrations (`GraphFuzzerMultiModuleProperty`),
	/// then compiles every graph's fixture, with the generated code of each graph the tool accepted, in as few `swiftc`
	/// invocations as attribution allows. Compilation is skipped when `compileVerificationIsEnabled` is `false`.
	///
	/// - Parameter willRunSeed: Called before the tool first runs a seed's graph, so that a long run can record
	///   which seed was running if the tool crashes the process.
	/// - Parameter isolatedSeeds: The seeds whose value graphs are each compared on their own
	///   (`valueComparisons(of:isolatingValueGraphsOf:)`).
	/// - Parameter concurrentToolRuns: How many seeds' graphs the tool runs at once. The results are in the order of
	///   `seeds` whatever it is. A long run passes 1: its batches already run side by side, and with one seed running
	///   per batch the last seed a batch recorded is the one a crash interrupted.
	static func results(
		forSeeds seeds: [UInt64],
		features: Set<GraphFuzzerGeneratorFeature> = [],
		isolatingValueGraphsOf isolatedSeeds: Set<UInt64> = [],
		concurrentToolRuns: Int = ProcessInfo.processInfo.activeProcessorCount,
		willRunSeed: @escaping @Sendable (UInt64) -> Void = { _ in },
	) async throws -> [GraphFuzzerResult] {
		await ProcessSlots.shared.takePlaceInLine(for: Test.current?.id)
		// Each seed's runs are measured in the task that makes them, so the phase's figure stays the seconds spent in it
		// summed over seeds, as it is summed over batches.
		let toolRuns = try await valuesInOrder(of: seeds, concurrent: concurrentToolRuns) { seed in
			try await GraphFuzzerPhaseAccount.measuring(.toolRuns) {
				willRunSeed(seed)
				return try await self.toolRuns(of: GraphFuzzerGenerator.fixture(forSeed: seed, features: features))
			}
		}
		return try await results(of: toolRuns, isolatingValueGraphsOf: isolatedSeeds)
	}

	/// What `value` gives for each of `elements`, in their order, with at most `concurrent` of them being worked out
	/// at once.
	///
	/// When `value` throws for several elements, the error thrown is that of the first of them in the order of
	/// `elements`, whichever finished first: after a failure no further element is started, the ones running finish,
	/// and elements are started in order, so every element before a failed one has run. A serial loop throws the same
	/// error, so the seed a failure names does not change from run to run.
	static func valuesInOrder<Element: Sendable, Value: Sendable>(
		of elements: [Element],
		concurrent: Int,
		_ value: @escaping @Sendable (Element) async throws -> Value,
	) async throws -> [Value] {
		let resultsByIndex = await withTaskGroup(of: (index: Int, result: Result<Value, any Error>).self) { group in
			var nextIndex = 0
			var hasFailed = false
			func addNextElement() {
				guard !hasFailed, nextIndex < elements.count else { return }
				let index = nextIndex
				let element = elements[index]
				nextIndex += 1
				group.addTask {
					do {
						return try await (index, .success(value(element)))
					} catch {
						return (index, .failure(error))
					}
				}
			}
			for _ in 0..<max(1, concurrent) {
				addNextElement()
			}
			var resultsByIndex = [Int: Result<Value, any Error>]()
			for await finished in group {
				resultsByIndex[finished.index] = finished.result
				switch finished.result {
				case .success:
					break
				case .failure:
					hasFailed = true
				}
				addNextElement()
			}
			return resultsByIndex
		}
		return try elements.indices.compactMap { resultsByIndex[$0] }.map { try $0.get() }
	}

	/// The oracle's verdict on graphs the tool already ran.
	/// - Parameter isolatedSeeds: The seeds whose value graphs are each compared on their own.
	static func results(of toolRuns: [GraphFuzzerToolRuns], isolatingValueGraphsOf isolatedSeeds: Set<UInt64> = []) async throws -> [GraphFuzzerResult] {
		// The remedied graphs the tool accepts compile in the same invocations, each under a prefix of its own, and a failure
		// of one is its seed's (`GraphFuzzerRemedyVariant`).
		let remedyVariants = remedyVariants(of: toolRuns.filter { $0.runsDifferFailure == nil })
		let compiledRuns = toolRuns.filter { $0.runsDifferFailure == nil } + remedyVariants.map(\.compiledRuns)
		// A graph that fails as a debug build is reported as one, unless only its hand-written call fails there and its code
		// fails as a release build.
		let compilationFailures: [UInt64: GraphFuzzerFailure] = if compileVerificationIsEnabled {
			try await GraphFuzzerPhaseAccount.measuring(.compiles) {
				try await attributingFailures(of: remedyVariants, in: self.compilationFailures(of: compiledRuns).merging(self.compilationFailures(of: compiledRuns.filter(\.fixture.compilesAsReleaseBuildToo), definesDebug: false)) { debugFailure, releaseFailure in
					debugFailure.kind == .builderCallDoesNotCompile && releaseFailure.kind != .builderCallDoesNotCompile ? releaseFailure : debugFailure
				})
			}
		} else {
			[:]
		}
		// A graph whose code compiled and whose hand-written call `C` did not is the builder surface's finding, which judges
		// only the call: its code is compared and judged as every graph's that compiles.
		let builderCallFailures = compilationFailures.filter { $0.value.kind == .builderCallDoesNotCompile }
		let codeCompilationFailures = compilationFailures.filter { $0.value.kind != .builderCallDoesNotCompile }
		let valueComparisons = try await GraphFuzzerPhaseAccount.measuring(.valueComparisons) {
			try await self.valueComparisons(of: toolRuns.filter { $0.runsDifferFailure == nil && codeCompilationFailures[$0.fixture.seed] == nil }, isolatingValueGraphsOf: isolatedSeeds)
		}
		return toolRuns.map { runs in
			let renamedGraphFailures = runs.renamedGraphFailures(refutingOrderOf: valueComparisons.listOrderRefutations[runs.fixture.seed] ?? [:])
			var failures = [runs.runsDifferFailure, runs.cleanSubtreeSkipFailure, runs.differentialFailure, runs.acceptanceDifferentialFailure, runs.integrationsDisagreeFailure, runs.storedSeamSignaturesDisagreeFailure, runs.visibleBuildFailure, runs.publicMockAcceptanceFailure, runs.seamRejectedWhereInlineAcceptsFailure, runs.nilArgumentFailure, runs.tierAccessFailure, runs.publicMockAccessFailure, runs.publicMockRootLevelFailure, runs.publicMockOverrideClosureFailure, runs.publicMockOverridesOrderFailure, runs.omittedValueFailure, codeCompilationFailures[runs.fixture.seed], runs.valueOracleFixtureFailure].compactMap(\.self)
			failures.append(contentsOf: valueComparisons.failures[runs.fixture.seed] ?? [])
			failures.append(contentsOf: [runs.wrapperParameterFailure, runs.generatedCodeCallsEntryMeantForPeopleFailure, runs.generatedOnlyInitializerTakesDefaultFailure, runs.carrierMemberReadApartFailure, runs.configurationStorageFailure, runs.handWrittenMockBypassFailure, runs.readTwinFailure, runs.holeNameStabilityFailure, runs.builderSurfaceFailure, builderCallFailures[runs.fixture.seed], runs.builderLabelFailure, runs.sameSupplyFailure, runs.sameSupplyEditRejectedFailure, runs.addedSupplyFailure, runs.forwardedValuesFailure, runs.forwardingRemedyFailure, runs.remedyBuildersFailure, runs.callingMockFailure, runs.placeLevelsFailure, runs.rootFunctionKeyFailure, runs.placesJudgedByAnotherPlacesFillFailure, runs.placeChainFailure, runs.secondPathFailure, runs.multiModuleFailures.first, runs.remedyFailure, runs.querySuppliersFailure].compactMap(\.self))
			failures.append(contentsOf: runs.scopeCaseFailures)
			// Whether a closure a level function returns keeps a level's values, read from the generated text, so it judges
			// with compiles and without.
			let levelFunctionCaptures: GraphFuzzerLevelFunctionCaptures? = if case let .accepted(generatedFiles, _) = runs.firstOutcome {
				GraphFuzzerLevelFunctionCaptures(generatedFiles: generatedFiles)
			} else {
				nil
			}
			if let levelFunctionCaptures, !levelFunctionCaptures.findings.isEmpty {
				failures.append(GraphFuzzerFailure(
					seed: runs.fixture.seed,
					kind: .levelFunctionKeepsValues,
					details: "\(levelFunctionCaptures.findings.map(\.description).joined(separator: "\n"))\nThis graph:\n\(runs.firstOutcome.description)",
				))
			}
			failures.append(contentsOf: renamedGraphFailures)
			// The retention oracle judges last. No known failure masks what it finds, as none masks a renamed graph's
			// difference (`GraphFuzzerFinding`).
			failures.append(contentsOf: [valueComparisons.retentionFailures[runs.fixture.seed]].compactMap(\.self))
			// A base corpus graph is compared once its value-oracle graph is.
			let isValueOracleGraphCompared = runs.valueOracle == nil || valueComparisons.comparedValueOracleSeeds.contains(runs.fixture.seed)
			return GraphFuzzerResult(
				fixture: runs.fixture,
				outcome: runs.firstOutcome,
				failure: failures.first,
				laterFailures: Array(failures.dropFirst()),
				renamedGraphFailures: renamedGraphFailures,
				multiModuleRuns: runs.multiModuleRuns,
				isInspectedByValueOracle: runs.isInspectedByValueOracle,
				isComparedByValueOracle: compileVerificationIsEnabled && runs.isInspectedByValueOracle && runs.runsDifferFailure == nil && codeCompilationFailures[runs.fixture.seed] == nil && isValueOracleGraphCompared,
				isComparedAcrossIntegrations: runs.pluginOutcome != nil,
				isComparedWithRecomputedSignatures: runs.recomputedSignaturesOutcome != nil,
				isComparedWithReadTwin: runs.readTwinOutcome != nil,
				isJudgedByQueryOracle: runs.queryExport != nil,
				isComparedWithoutSecondHolePlace: runs.isComparedWithoutSecondHolePlace,
				isComparedWithoutSecondPath: runs.isComparedWithoutSecondPath,
				isComparedWithCleanSubtreeSkipOff: runs.cleanSubtreeSkipOffOutcome != nil,
				retentionCounts: valueComparisons.retentionCounts[runs.fixture.seed] ?? GraphFuzzerRetentionCounts(),
				valueOracle: runs.valueOracle,
				remedyRuns: runs.remedyRuns,
				builderSurfaceFloorKinds: runs.builderSurfaceFloorKinds + Self.builderCallFloorKinds(of: runs, isCompiled: compileVerificationIsEnabled && runs.runsDifferFailure == nil && codeCompilationFailures[runs.fixture.seed] == nil),
				levelFunctionCaptures: levelFunctionCaptures,
			)
		}
	}

	/// The kinds a graph whose code compiled (`isCompiled`) counts toward the builder surface's floors for the compile of the
	/// call a person writes, `C`, whether `C` compiled or not: `wrapperBuilderCall` where `C` called a builder whose
	/// readable type is a wrapper's `Builder`.
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	static func builderCallFloorKinds(of runs: GraphFuzzerToolRuns, isCompiled: Bool) -> [String] {
		guard isCompiled, GraphFuzzerBuilderSurface.callsWrapperBuilder(in: runs.generatedFiles) else { return [] }
		return [GraphFuzzerBuilderSurface.wrapperBuilderCallKind]
	}

	/// The failures of each graph of `toolRuns` the tool accepts with its seam and without it whose seam build
	/// constructs other values than its inline build, or whose two builds the differential value comparator could
	/// not describe, keyed by seed. A graph with a hole is compared with its visible build too, and that comparison's
	/// failure comes first: each comparison's failure is its own entry, so that a known issue that documents one
	/// (`GraphFuzzerFinding`) masks no undocumented difference of the other. The seam path is the graph with its seams and the files the tool generated for it,
	/// the known-right path the same graph with no seam and the files the tool generated for that; the probes are the
	/// graph's roots and the generated mocks that take no required parameter. Each path is built from the graph drawn
	/// storing every parameter, so the comparator sees every value the generated code passes; storing changes nothing
	/// the tool generates. Nothing is exempted: a seam hands a hole's struct the memo of each value it defers, so a fill
	/// creates the value where inline would. The graphs of one call are compared in one batch.
	/// Nothing is compared when `compileVerificationIsEnabled` is `false`.
	static func valueFailures(of toolRuns: [GraphFuzzerToolRuns]) async throws -> [UInt64: [GraphFuzzerFailure]] {
		try await valueComparisons(of: toolRuns).failures
	}

	/// What `valueComparisons(of:isolatingValueGraphsOf:)` finds.
	struct ValueComparisons {
		/// Each graph’s value failures, keyed by seed.
		var failures = [UInt64: [GraphFuzzerFailure]]()
		/// The base corpus seeds whose value-oracle graph the comparator compared, failing or not.
		var comparedValueOracleSeeds = Set<UInt64>()
		/// Each graph with a hole whose seam build, or public mock, keeps alive what its inline build, or known-right path,
		/// frees (`seamRetainsWhatInlineFrees`, `publicMockRetainsWhatKnownRightFrees`), keyed by seed: a failure after the
		/// value failure in the oracle's chain, which a known value failure does not mask.
		var retentionFailures = [UInt64: GraphFuzzerFailure]()
		/// What the retention oracle judged of each graph with a hole whose two builds the comparator compared, failing or
		/// not, keyed by seed.
		var retentionCounts = [UInt64: GraphFuzzerRetentionCounts]()
		/// What refuted each renamed graph's order-only difference, by its index in `renamedOutcomes`, keyed by seed
		/// (`GraphFuzzerToolRuns.renamedGraphFailures(refutingOrderOf:)`).
		var listOrderRefutations = [UInt64: [Int: String]]()
	}

	/// Whether the graph of `fixture` holds a hole, judged by the retention oracle: it draws a type that fills a seam's hole
	/// (`GraphFuzzerFixture.drawsHole`), or `generatedFiles` take a builder for a hole: a seam's carrier of its places
	/// (`__safeDI_<Stem>Carrier`, `__safeDI_<Stem>SendableCarrier`), or one over an enum of its places – a seam's
	/// `SafeDIScope_` or `SafeDISendableScope_` enum, a public mock's a `MockScope_` one. A rename of those types that drops
	/// graphs from the oracle changes the judged graphs each corpus pins (`retentionCounts`).
	static func holdsHole(fixture: GraphFuzzerFixture, generatedFiles: [String: String]) -> Bool {
		fixture.drawsHole || generatedFiles.values.contains { contents in
			(contents.contains("Scope_") && (contents.contains("SafeDIScope_") || contents.contains("SafeDISendableScope_") || contents.contains("MockScope_")))
				|| contents.range(of: GraphFuzzerOracle.carrierDeclarationPattern, options: .regularExpression) != nil
		}
	}

	/// A seam's declaration of a carrier of its places: its root's, `__safeDI_<Stem>Carrier` or
	/// `__safeDI_<Stem>SendableCarrier`, or a level's, `__safeDI_<Stem>Carrier_<Type>`.
	static let carrierDeclarationPattern = #"\bfinal class __safeDI_\w+Carrier(_\w+)?<__safeDI_Built>"#

	/// `valueFailures(of:)`, with the base corpus seeds whose value-oracle graph the comparator compared, failing or
	/// not. A base corpus graph is compared by its value-oracle graph (`GraphFuzzerValueOracleRun.valueGraph`): each
	/// root's mock and each mirrored mock with its production build, in one path, with no exemption. The graphs of a seed
	/// of `isolatedSeeds` are compared on their own, outside the batch, with `DifferentialValueLimits.isolatedFuzzerGraph`:
	/// a seed whose known compile failure would make the batch compile each graph again on its own, or one whose probes
	/// traverse more wrappers than the batch's budget allows, which a larger budget for every graph would slow down.
	static func valueComparisons(
		of toolRuns: [GraphFuzzerToolRuns],
		isolatingValueGraphsOf isolatedSeeds: Set<UInt64> = [],
	) async throws -> ValueComparisons {
		let inspectedRuns = toolRuns.filter(\.isInspectedByValueOracle)
		// A graph with a hole is compared with its visible build too, in which the seam builds the fulfilling type.
		let visibleRuns = toolRuns.filter { runs in
			guard case .accepted = runs.firstOutcome, case .accepted = runs.visibleOutcome else { return false }
			return true
		}
		// A base corpus graph whose value-oracle fixture the tool accepts as planned.
		let valueOracleGraphs = toolRuns.compactMap { runs -> (runs: GraphFuzzerToolRuns, graph: DifferentialValueGraph)? in
			guard runs.valueOracleFixtureFailure == nil, let graph = runs.valueOracle?.valueGraph else { return nil }
			return (runs, graph)
		}
		guard !inspectedRuns.isEmpty || !visibleRuns.isEmpty, compileVerificationIsEnabled else { return ValueComparisons() }
		var filesToDelete = [URL]()
		defer {
			for fileToDelete in filesToDelete {
				try? FileManager.default.removeItem(at: fileToDelete)
			}
		}
		// Each graph beside the runs it judges: a public mock graph's against its known-right path
		// (`publicMockValueGraph(of:)`), a seam graph's against its inline build.
		// A graph with a hole also judges retention: what each probe keeps alive, holding one wrapper of its value, once the
		// value is released (rule 3 of the seam contract).
		let graphs = inspectedRuns.compactMap { runs -> (runs: GraphFuzzerToolRuns, graph: DifferentialValueGraph)? in
			if let graph = publicMockValueGraph(of: runs, judgesRetention: holdsHole(fixture: runs.fixture, generatedFiles: runs.generatedFiles)) {
				return (runs, graph)
			}
			return seamValueGraph(of: runs).map { (runs, $0) }
		}
		let visibleGraphs = visibleRuns.compactMap { runs -> (runs: GraphFuzzerToolRuns, graph: DifferentialValueGraph)? in
			guard case let .accepted(holeFiles, _) = runs.firstOutcome, case let .accepted(visibleFiles, _) = runs.visibleOutcome else { return nil }
			let storingFixture = GraphFuzzerGenerator.fixture(forSeed: runs.fixture.seed, features: GraphFuzzerGeneratorFeature.features(drawnIn: runs.fixture), storingEveryParameter: true)
			return (runs, DifferentialValueGraph(
				name: "seed \(runs.fixture.seed), visible build",
				feature: DifferentialValuePath(fixture: storingFixture, generatedFiles: holeFiles),
				knownRight: DifferentialValuePath(fixture: storingFixture.withoutHoles, generatedFiles: visibleFiles),
				probes: storingFixture.differentialValueProbes(generatedFiles: holeFiles),
				samples: storingFixture.holeDrawForwardedPropertiesSamples + storingFixture.forwardedLabelAcrossSeamCallSamples,
			))
		}
		guard let comparisons = try await compare(graphs + visibleGraphs + valueOracleGraphs, isolating: isolatedSeeds, filesToDelete: &filesToDelete) else { return ValueComparisons() }
		// A renamed graph's code that differs from the graph's only in the order of its label-sorted lists and blocks is that
		// order only if it means the same: with its renaming undone, it must compile with the graph and build the values the
		// graph's own code builds, against the same inline build. A seed's renamed graphs declare its types again, so each
		// round holds at most one of each seed's, in one batch.
		var renamedGraphsByRound = [[(runs: GraphFuzzerToolRuns, graphIndex: Int, renamedIndex: Int, graph: DifferentialValueGraph)]]()
		for (graphIndex, (runs, graph)) in graphs.enumerated() where runs.knownRightOutcome == nil {
			for (round, (renamedIndex, renamedGraph)) in listOrderGraphs(of: runs, beside: graph).enumerated() {
				if renamedGraphsByRound.count == round {
					renamedGraphsByRound.append([])
				}
				renamedGraphsByRound[round].append((runs, graphIndex, renamedIndex, renamedGraph))
			}
		}
		var listOrderRefutations = [UInt64: [Int: String]]()
		for round in renamedGraphsByRound {
			guard let renamedComparisons = try await compare(round.map { ($0.runs, $0.graph) }, isolating: isolatedSeeds, filesToDelete: &filesToDelete) else { continue }
			for (renamed, renamedComparison) in zip(round, renamedComparisons) {
				if let refutation = listOrderRefutation(of: comparisons[renamed.graphIndex].result, by: renamedComparison.result) {
					listOrderRefutations[renamed.runs.fixture.seed, default: [:]][renamed.renamedIndex] = refutation
				}
			}
		}
		let valueOracleComparisons = zip(valueOracleGraphs.map(\.runs), comparisons.suffix(valueOracleGraphs.count))
		var failures = [UInt64: [GraphFuzzerFailure]]()
		var comparedValueOracleSeeds = Set<UInt64>()
		var retentionFailures = [UInt64: GraphFuzzerFailure]()
		var retentionCounts = [UInt64: GraphFuzzerRetentionCounts]()
		for (runs, comparison) in valueOracleComparisons {
			let builds = "The value-oracle fixture:\n\(runs.valueOracle?.plan.valueOracleFixture(storingEveryParameter: true).description ?? "")\nWhat the tool generated for it:\n\(runs.valueOracle?.outcome?.description ?? "")"
			switch comparison.result {
			case let .success(valueComparison):
				comparedValueOracleSeeds.insert(runs.fixture.seed)
				let differences = valueComparison.differences
				guard !differences.isEmpty else { continue }
				failures[runs.fixture.seed, default: []].append(GraphFuzzerFailure(
					seed: runs.fixture.seed,
					kind: .mockBuildsOtherValuesThanProduction,
					details: "\(differences.map(\.description).joined(separator: "\n"))\n\(valueComparison.report)\(builds)",
					valueDifferences: differences.map(\.description),
				))
			case let .failure(error):
				failures[runs.fixture.seed, default: []].append(GraphFuzzerFailure(
					seed: runs.fixture.seed,
					kind: .valueOracleFixtureDoesNotCompile,
					details: "\(error)\n\(builds)",
				))
			}
		}
		for ((runs, _), comparison) in zip(visibleGraphs, comparisons.dropFirst(graphs.count)) {
			switch comparison.result {
			case let .success(valueComparison):
				let differences = valueComparison.differences
				guard !differences.isEmpty else { continue }
				failures[runs.fixture.seed, default: []].append(GraphFuzzerFailure(
					seed: runs.fixture.seed,
					kind: .holeBuildsOtherValuesThanVisibleBuild,
					details: "\(differences.map(\.description).joined(separator: "\n"))\n\(valueComparison.report)With the hole:\n\(runs.firstOutcome.description)\nThe visible build:\n\(runs.visibleOutcome?.description ?? "")",
					valueDifferences: differences.map(\.description),
				))
			case let .failure(error):
				failures[runs.fixture.seed, default: []].append(GraphFuzzerFailure(
					seed: runs.fixture.seed,
					kind: .valueComparatorCouldNotDescribeGraph,
					details: "\(error)\nWith the hole:\n\(runs.firstOutcome.description)\nThe visible build:\n\(runs.visibleOutcome?.description ?? "")",
				))
			}
		}
		// What the graph keeps alive is judged whatever its values, as a later failure of the oracle's chain.
		for ((runs, graph), comparison) in zip(graphs, comparisons) where graph.judgesRetention {
			guard case let .success(valueComparison) = comparison.result else { continue }
			let judgedProbes = valueComparison.retentionJudgedProbes
			retentionCounts[runs.fixture.seed] = GraphFuzzerRetentionCounts(
				judged: judgedProbes.isEmpty ? 0 : 1,
				judgedDrawingRetentionShape: !judgedProbes.isEmpty && GraphFuzzerRetentionCounts.drawsRetentionShape(runs.fixture) ? 1 : 0,
				judgedThroughHandWrittenBuilder: judgedProbes.contains { $0.hasSuffix(GraphFuzzerFixture.handWrittenBuilderProbeNameSuffix) } ? 1 : 0,
				unpairedExperiments: valueComparison.unpairedRetentionExperimentCount,
				judgedHoldingForwardingWrapper: Dictionary(
					GraphFuzzerRetentionCounts.forwardingWrapperNames(ofHeldLabels: valueComparison.retentionPairedWrapperLabels, in: runs.fixture).map { ($0, 1) },
					uniquingKeysWith: +,
				),
			)
			let differences = valueComparison.retentionDifferences
			guard !differences.isEmpty else { continue }
			let isPublicMockGraph = runs.knownRightOutcome != nil
			let builds = isPublicMockGraph
				? "As drawn:\n\(runs.firstOutcome.description)\nKnown right:\n\(runs.knownRightOutcome?.description ?? "")"
				: "With the seam:\n\(runs.firstOutcome.description)\nWithout it:\n\(runs.inlineOutcome?.description ?? "")"
			retentionFailures[runs.fixture.seed] = GraphFuzzerFailure(
				seed: runs.fixture.seed,
				kind: isPublicMockGraph ? .publicMockRetainsWhatKnownRightFrees : .seamRetainsWhatInlineFrees,
				details: "\(differences.map(\.description).joined(separator: "\n"))\n\(valueComparison.report)\(builds)",
				valueDifferences: differences.map(\.description),
			)
		}
		// A difference from the visible build is reported before one from the inline build, which follows it as a failure of
		// its own: a known issue that documents the first masks no difference of the second it does not document.
		for ((runs, _), comparison) in zip(graphs, comparisons) {
			let isPublicMockGraph = runs.knownRightOutcome != nil
			let builds = isPublicMockGraph
				? "As drawn:\n\(runs.firstOutcome.description)\nKnown right:\n\(runs.knownRightOutcome?.description ?? "")"
				: "With the seam:\n\(runs.firstOutcome.description)\nWithout it:\n\(runs.inlineOutcome?.description ?? "")"
			switch comparison.result {
			case let .success(valueComparison):
				// A public mock graph exempts the shape matrix's stated divergences, derived from its leaf calls.
				let statedDivergences = isPublicMockGraph ? Self.statedPublicMockValueDivergences(in: valueComparison, of: runs) : []
				let differences = valueComparison.differences.filter { !statedDivergences.contains($0) }
				guard !differences.isEmpty else { continue }
				failures[runs.fixture.seed, default: []].append(GraphFuzzerFailure(
					seed: runs.fixture.seed,
					kind: isPublicMockGraph ? .publicMockBuildsOtherValuesThanKnownRight : .seamBuildsOtherValuesThanInline,
					details: "\(differences.map(\.description).joined(separator: "\n"))\n\(valueComparison.report)\(builds)",
					valueDifferences: differences.map(\.description),
				))
			case let .failure(error):
				failures[runs.fixture.seed, default: []].append(GraphFuzzerFailure(
					seed: runs.fixture.seed,
					kind: .valueComparatorCouldNotDescribeGraph,
					details: "\(error)\n\(builds)",
				))
			}
		}
		return ValueComparisons(failures: failures, comparedValueOracleSeeds: comparedValueOracleSeeds, retentionFailures: retentionFailures, retentionCounts: retentionCounts, listOrderRefutations: listOrderRefutations)
	}

	/// The value graph of a seam graph the tool accepts with its seams and without them: the seam build against its inline
	/// build, each from the graph drawn storing every parameter, or `nil` for any other graph.
	static func seamValueGraph(of runs: GraphFuzzerToolRuns) -> DifferentialValueGraph? {
		guard case let .accepted(seamFiles, _) = runs.firstOutcome, case let .accepted(inlineFiles, _) = runs.inlineOutcome else { return nil }
		let storingFixture = GraphFuzzerGenerator.fixture(forSeed: runs.fixture.seed, features: GraphFuzzerGeneratorFeature.features(drawnIn: runs.fixture), storingEveryParameter: true)
		return DifferentialValueGraph(
			name: "seed \(runs.fixture.seed)",
			feature: DifferentialValuePath(fixture: storingFixture, generatedFiles: seamFiles),
			knownRight: DifferentialValuePath(fixture: storingFixture.withoutSeams, generatedFiles: inlineFiles),
			probes: storingFixture.differentialValueProbes(generatedFiles: seamFiles),
			samples: storingFixture.holeDrawForwardedPropertiesSamples + storingFixture.forwardedLabelAcrossSeamCallSamples,
			exemptions: [],
			judgesRetention: holdsHole(fixture: runs.fixture, generatedFiles: seamFiles),
		)
	}

	/// The value graph of each renamed graph of `runs` whose code differs from the graph's only in the order of its lists
	/// and blocks (`GraphFuzzerToolRuns.renamedOutcomesDifferingInListOrder`), by its index in `renamedOutcomes`: its code,
	/// with its renaming undone, compiled with the graph, against `graph`'s known-right path, with `graph`'s samples.
	static func listOrderGraphs(of runs: GraphFuzzerToolRuns, beside graph: DifferentialValueGraph) -> [(renamedIndex: Int, graph: DifferentialValueGraph)] {
		let renamedGraphs = runs.renamedOutcomesDifferingInListOrder
		guard !renamedGraphs.isEmpty else { return [] }
		let storingFixture = GraphFuzzerGenerator.fixture(forSeed: runs.fixture.seed, features: GraphFuzzerGeneratorFeature.features(drawnIn: runs.fixture), storingEveryParameter: true)
		return renamedGraphs.map { renamedIndex, generatedFiles in
			(renamedIndex, DifferentialValueGraph(
				name: "seed \(runs.fixture.seed), \(runs.renamedOutcomes[renamedIndex].renaming.description)",
				feature: DifferentialValuePath(fixture: storingFixture, generatedFiles: generatedFiles),
				knownRight: graph.knownRight,
				probes: storingFixture.differentialValueProbes(generatedFiles: generatedFiles),
				samples: graph.samples,
			))
		}
	}

	/// What refutes a renamed graph's order-only difference, or `nil` when nothing does: the renamed graph's comparison,
	/// `renamedResult`, must end as the graph's own, `ownResult`, did, with the same value differences, or the same failure,
	/// at the same stage of the same path. So a renamed graph whose code does not compile refutes the order even where the
	/// graph's own probes run out of traversals, as do differences the graph's own code does not show and values the graph's
	/// own comparison could not describe.
	static func listOrderRefutation(
		of ownResult: Result<DifferentialValueComparison, DifferentialValueOracleError>,
		by renamedResult: Result<DifferentialValueComparison, DifferentialValueOracleError>,
	) -> String? {
		switch (ownResult, renamedResult) {
		case let (.success(valueComparison), .success(renamedValueComparison)):
			valueComparison.differences.map(\.description) == renamedValueComparison.differences.map(\.description)
				? nil
				: "Its code, with its renaming undone, builds other values than the graph's own code:\n\(renamedValueComparison.differences.map(\.description).joined(separator: "\n"))\n\(renamedValueComparison.report)"
		case let (.success, .failure(error)):
			"Its code, with its renaming undone, does not compile with the graph, or its values cannot be described:\n\(error)"
		case let (.failure(error), .failure(renamedError)):
			error.stage == renamedError.stage && error.path == renamedError.path
				? nil
				: "Its code, with its renaming undone, fails otherwise than the graph's own code, which fails with:\n\(error)\nIts own failure:\n\(renamedError)"
		case let (.failure(error), .success):
			"Its code, with its renaming undone, is described where the graph's own code is not, which fails with:\n\(error)"
		}
	}

	/// Compares each of `graphs`, beside the runs it judges: the graphs of seeds outside `isolatedSeeds` in one batch,
	/// with the comparator's ordinary limits, and each isolated seed's graphs in a batch of their own, with
	/// `DifferentialValueLimits.isolatedFuzzerGraph`, the seeds in the order of their first graph.
	/// - Returns: Each graph's comparison, in the order of `graphs`, or `nil` when compile verification is disabled.
	private static func compare(
		_ graphs: [(runs: GraphFuzzerToolRuns, graph: DifferentialValueGraph)],
		isolating isolatedSeeds: Set<UInt64>,
		filesToDelete: inout [URL],
	) async throws -> [DifferentialValueGraphComparison]? {
		var batches = [(indices: graphs.indices.filter { !isolatedSeeds.contains(graphs[$0].runs.fixture.seed) }, limits: DifferentialValueLimits())]
		var isolatedSeedsInOrder = [UInt64]()
		for (runs, _) in graphs where isolatedSeeds.contains(runs.fixture.seed) && !isolatedSeedsInOrder.contains(runs.fixture.seed) {
			isolatedSeedsInOrder.append(runs.fixture.seed)
		}
		for seed in isolatedSeedsInOrder {
			batches.append((graphs.indices.filter { graphs[$0].runs.fixture.seed == seed }, DifferentialValueLimits.isolatedFuzzerGraph))
		}
		var comparisons = [DifferentialValueGraphComparison?](repeating: nil, count: graphs.count)
		for (indices, limits) in batches {
			guard let batchComparisons = try await DifferentialValueOracle.compare(graphs: indices.map { graphs[$0].graph }, limits: limits, filesToDelete: &filesToDelete) else { return nil }
			for (index, comparison) in zip(indices, batchComparisons) {
				comparisons[index] = comparison
			}
		}
		return comparisons.compactMap(\.self)
	}

	/// How many times the code in `generatedFiles` passes a literal `nil` to each argument of each construction of a
	/// type whose name begins with `typeNamePrefix`, but those of `excludedTypeNames`, keyed by the type and the
	/// argument's label, as `Type(label:)`. The oracle's own seam callers are not generated code and are skipped.
	static func nilArgumentCounts(in generatedFiles: [String: String], typeNamePrefix: String, excluding excludedTypeNames: Set<String>) -> [String: Int] {
		var counts = [String: Int]()
		for (fileName, contents) in generatedFiles where !fileName.hasSuffix("+SafeDISeamCaller.swift") {
			for call in calls(in: contents, calleeExpression: constructionExpression(typeNamePrefix: typeNamePrefix)) where !excludedTypeNames.contains(call.callee) {
				for argument in call.arguments where argument.value == "nil" {
					counts["\(call.callee)(\(argument.label):)", default: 0] += 1
				}
			}
		}
		return counts
	}

	/// How many constructions in the code in `generatedFiles` a literal `nil` reaches through a builder function it
	/// generates, keyed as `nilArgumentCounts(in:typeNamePrefix:excluding:)` keys them: for each call
	/// `__safeDI_f(label: nil)`, each construction of a type whose name begins with `typeNamePrefix`, but those of
	/// `excludedTypeNames`, in the body of the declaration of `__safeDI_f` the call reaches that passes `label: label`. The
	/// call reaches the declaration of its name whose body holds it, else the last one before it, else the first after it.
	/// Such a `nil` is a cycle parameter of a function a lazy cycle closes on, which the function's constructions read by
	/// name. The oracle's own seam callers are not generated code and are skipped.
	static func nilArgumentCountsThroughBuilderFunctions(in generatedFiles: [String: String], typeNamePrefix: String, excluding excludedTypeNames: Set<String>) -> [String: Int] {
		var counts = [String: Int]()
		// The expression is this file's own.
		let declarationExpression = try! NSRegularExpression(pattern: #"\bfunc (__safeDI_[A-Za-z0-9_]+)\("#)
		for (fileName, contents) in generatedFiles where !fileName.hasSuffix("+SafeDISeamCaller.swift") {
			let source = contents as NSString
			let declarations = declarationExpression.matches(in: contents, range: NSRange(location: 0, length: source.length)).compactMap { match -> (name: String, start: Int, body: NSRange)? in
				let parametersEnd = closingDelimiterEnd(in: source, after: match.range.location + match.range.length)
				let bodyStart = source.range(of: "{", range: NSRange(location: parametersEnd, length: source.length - parametersEnd)).location
				guard bodyStart != NSNotFound else { return nil }
				let bodyEnd = closingDelimiterEnd(in: source, after: bodyStart + 1)
				return (source.substring(with: match.range(at: 1)), match.range.location, NSRange(location: bodyStart + 1, length: max(0, bodyEnd - bodyStart - 2)))
			}
			for call in calls(in: contents, calleeExpression: #"(?<![A-Za-z0-9_.])(__safeDI_[A-Za-z0-9_]+)\("#) {
				let labels = call.arguments.filter { $0.value == "nil" }.map(\.label)
				let namesakes = declarations.filter { $0.name == call.callee }
				guard !labels.isEmpty,
				      let declaration = namesakes.last(where: { NSLocationInRange(call.location, $0.body) })
				      ?? namesakes.last(where: { $0.start < call.location })
				      ?? namesakes.first
				else { continue }
				for construction in calls(in: source.substring(with: declaration.body), calleeExpression: constructionExpression(typeNamePrefix: typeNamePrefix)) where !excludedTypeNames.contains(construction.callee) {
					for argument in construction.arguments where labels.contains(argument.label) && handsOn(argument.value, argument.label) {
						counts["\(construction.callee)(\(argument.label):)", default: 0] += 1
					}
				}
			}
		}
		return counts
	}

	/// The keys, as `nilArgumentCounts(in:typeNamePrefix:excluding:)` keys them, that the code in `generatedFiles` passes a
	/// `nil` to in a shared builder function (`SharedBuilderFunctions`), literally or through a call that hands the
	/// function a `nil`, as `nilArgumentCountsThroughBuilderFunctions(in:typeNamePrefix:excluding:)` follows one, and on
	/// through each function that function hands it to by the same label. Such code stands for
	/// as many places as reach it, which its text does not show, so its count is no count of places. The oracle's own seam
	/// callers are not generated code and are skipped.
	static func nilArgumentKeysInSharedBuilderFunctions(in generatedFiles: [String: String], typeNamePrefix: String, excluding excludedTypeNames: Set<String>) -> Set<String> {
		var keys = Set<String>()
		for (fileName, contents) in generatedFiles where !fileName.hasSuffix("+SafeDISeamCaller.swift") {
			let shared = SharedBuilderFunctions(of: contents)
			for call in calls(in: contents, calleeExpression: constructionExpression(typeNamePrefix: typeNamePrefix)) where !excludedTypeNames.contains(call.callee) && shared.isShared(at: call.location) {
				for argument in call.arguments where argument.value == "nil" {
					keys.insert("\(call.callee)(\(argument.label):)")
				}
			}
			// A function hands on a `nil` it is given to the functions it calls with `label: label`, so the walk follows each
			// such call to the constructions at its end.
			let builderCallExpression = #"(?<![A-Za-z0-9_.])(__safeDI_[A-Za-z0-9_]+)\("#
			var pending = calls(in: contents, calleeExpression: builderCallExpression).compactMap { call -> (callee: String, location: Int, labels: Set<String>)? in
				let labels = Set(call.arguments.filter { $0.value == "nil" }.map(\.label))
				return labels.isEmpty ? nil : (call.callee, call.location, labels)
			}
			var visited = Set<String>()
			while let (callee, location, labels) = pending.popLast() {
				guard let declaration = shared.declaration(calledBy: callee, at: location) else { continue }
				let body = (contents as NSString).substring(with: declaration.body)
				for label in labels.sorted() where visited.insert("\(declaration.body.location) \(label)").inserted {
					for construction in calls(in: body, calleeExpression: constructionExpression(typeNamePrefix: typeNamePrefix)) where !excludedTypeNames.contains(construction.callee) && shared.isShared(at: declaration.body.location + construction.location) {
						for argument in construction.arguments where argument.label == label && handsOn(argument.value, label) {
							keys.insert("\(construction.callee)(\(label):)")
						}
					}
					for call in calls(in: body, calleeExpression: builderCallExpression) where call.arguments.contains(where: { $0.label == label && handsOn($0.value, label) }) {
						pending.append((call.callee, declaration.body.location + call.location, [label]))
					}
				}
			}
		}
		return keys
	}

	/// The builder functions of one generated file whose code stands for more than one place, read from its text: the type
	/// key builds a type that several places build alike in one function, which each of those places calls, and the path
	/// key calls the function of an earlier place to close a cycle. A function is shared unless it is referenced exactly
	/// once, from the root's body or from a function that is not shared; code in a function declared inside a shared one is
	/// shared too, as each place of the outer function declares it again.
	struct SharedBuilderFunctions {
		struct Declaration {
			let name: String
			let start: Int
			let nameRange: NSRange
			let body: NSRange
		}

		init(of contents: String) {
			let source = contents as NSString
			let whole = NSRange(location: 0, length: source.length)
			// The expressions are this file's own.
			let declarationExpression = try! NSRegularExpression(pattern: #"\bfunc (__safeDI_[A-Za-z0-9_]+)\("#)
			let declarations = declarationExpression.matches(in: contents, range: whole).compactMap { match -> Declaration? in
				let parametersEnd = GraphFuzzerOracle.closingDelimiterEnd(in: source, after: match.range.location + match.range.length)
				let bodyStart = source.range(of: "{", range: NSRange(location: parametersEnd, length: source.length - parametersEnd)).location
				guard bodyStart != NSNotFound else { return nil }
				let bodyEnd = GraphFuzzerOracle.closingDelimiterEnd(in: source, after: bodyStart + 1)
				return Declaration(name: source.substring(with: match.range(at: 1)), start: match.range.location, nameRange: match.range(at: 1), body: NSRange(location: bodyStart + 1, length: max(0, bodyEnd - bodyStart - 2)))
			}
			self.declarations = declarations
			// A reference calls the function or passes it: a name followed by an argument list, or by the end of the one it is
			// passed in. A generated-only argument label, `__safeDI_<label>:`, is no reference.
			let referenceExpression = try! NSRegularExpression(pattern: #"(?<![A-Za-z0-9_.])(__safeDI_[A-Za-z0-9_]+)(?=\s*[(),])"#)
			var referencingBodies = [[Int?]](repeating: [], count: declarations.count)
			for match in referenceExpression.matches(in: contents, range: whole) where !declarations.contains(where: { $0.nameRange.location == match.range.location }) {
				guard let target = Self.declaration(named: source.substring(with: match.range(at: 1)), at: match.range.location, among: declarations) else { continue }
				referencingBodies[target].append(Self.enclosingDeclaration(at: match.range.location, among: declarations))
			}
			var isShared = [Bool?](repeating: nil, count: declarations.count)
			func shared(_ declaration: Int) -> Bool {
				if let known = isShared[declaration] {
					return known
				}
				// A function that reaches itself again is shared, which this guard also answers while the walk is inside it.
				isShared[declaration] = true
				let result: Bool = if referencingBodies[declaration].count == 1, let referencingBody = referencingBodies[declaration][0] {
					shared(referencingBody)
				} else {
					referencingBodies[declaration].count != 1
				}
				let enclosing = Self.enclosingDeclaration(at: declarations[declaration].start, among: declarations)
				isShared[declaration] = result || enclosing.map(shared) == true
				return isShared[declaration] ?? true
			}
			self.isShared = declarations.indices.map(shared)
		}

		/// Whether the code at `location` is in a shared function.
		func isShared(at location: Int) -> Bool {
			Self.enclosingDeclaration(at: location, among: declarations).map { isShared[$0] } ?? false
		}

		/// The declaration a call of `name` at `location` reaches: the one of its name whose body holds it, else the last
		/// one before it, else the first after it.
		func declaration(calledBy name: String, at location: Int) -> Declaration? {
			Self.declaration(named: name, at: location, among: declarations).map { declarations[$0] }
		}

		private let declarations: [Declaration]
		private let isShared: [Bool]

		private static func declaration(named name: String, at location: Int, among declarations: [Declaration]) -> Int? {
			let namesakes = declarations.indices.filter { declarations[$0].name == name }
			return namesakes.last(where: { NSLocationInRange(location, declarations[$0].body) })
				?? namesakes.last(where: { declarations[$0].start < location })
				?? namesakes.first
		}

		/// The innermost declaration whose body holds `location`.
		private static func enclosingDeclaration(at location: Int, among declarations: [Declaration]) -> Int? {
			declarations.indices
				.filter { NSLocationInRange(location, declarations[$0].body) }
				.min { declarations[$0].body.length < declarations[$1].body.length }
		}
	}

	/// Whether an argument whose value is `value` hands on the parameter `label` a builder function takes: by name, or,
	/// for a lazy cycle's optional wrapper, by the instance it holds, `label?.instance`.
	private static func handsOn(_ value: String, _ label: String) -> Bool {
		value == label || value == label + "?.instance"
	}

	/// The expression whose first capture is the callee of a construction of a type whose name begins with
	/// `typeNamePrefix`, which the call's arguments follow.
	fileprivate static func constructionExpression(typeNamePrefix: String) -> String {
		"(?<![A-Za-z0-9_.])(" + NSRegularExpression.escapedPattern(for: typeNamePrefix) + "[A-Za-z0-9_]+)\\("
	}

	/// Each call in `contents` whose callee `calleeExpression` matches, the callee its first capture and the call's
	/// arguments after it: the callee, where the call begins, and each top-level argument's label and value.
	fileprivate static func calls(in contents: String, calleeExpression: String) -> [(callee: String, location: Int, arguments: [(label: String, value: String)])] {
		// The expressions are this file's, built from escaped names.
		let expression = try! NSRegularExpression(pattern: calleeExpression)
		let source = contents as NSString
		return expression.matches(in: contents, range: NSRange(location: 0, length: source.length)).map { match in
			// The arguments run from after the opening parenthesis to the one that closes it.
			let start = match.range.location + match.range.length
			let end = closingDelimiterEnd(in: source, after: start)
			let arguments = topLevelParameters(source.substring(with: NSRange(location: start, length: max(0, end - start - 1)))).compactMap { argument -> (label: String, value: String)? in
				let parts = argument.split(separator: ":", maxSplits: 1)
				guard parts.count == 2 else { return nil }
				return (parts[0].trimmingCharacters(in: .whitespacesAndNewlines), parts[1].trimmingCharacters(in: .whitespacesAndNewlines))
			}
			return (source.substring(with: match.range(at: 1)), match.range.location, arguments)
		}
	}

	/// The location just past the delimiter that closes the one opened just before `start` in `source`, or the end of
	/// `source`.
	fileprivate static func closingDelimiterEnd(in source: NSString, after start: Int) -> Int {
		GeneratedTextDelimiters.closingDelimiterEnd(in: source, after: start)
	}

	/// A line for each construction argument `seamCounts` passes a literal `nil` more often than `inlineCounts`, in
	/// order.
	static func nilArgumentCountsExceeding(_ seamCounts: [String: Int], _ inlineCounts: [String: Int]) -> [String] {
		seamCounts.keys.sorted().compactMap { key in
			let seamCount = seamCounts[key] ?? 0
			let inlineCount = inlineCounts[key] ?? 0
			return seamCount > inlineCount ? "`\(key)` is passed `nil` \(seamCount) times with the seam and \(inlineCount) without it." : nil
		}
	}

	/// Whether every error in `diagnostics`, a seam-world rejection, is one of a seam's own: reported at the seam
	/// about its generated initializer or a call of it, which no inlined tree has. The inlined validation's errors
	/// name a property or a type; a seam's name the dependency tree of the seam, or the call of its initializer.
	static func isSeamOnlyRejection(diagnostics: String, seamTypeNames: [String], excusingOmittedValues: Bool = false) -> Bool {
		let markers = seamOnlyErrorMarkers + seamTypeNames.map { "` is hidden in chain: \($0) -> " }
		let errors = diagnostics.split(separator: "\n").filter { $0.contains(": error: ") }
		return !errors.isEmpty && errors.allSatisfy { error in
			markers.contains { error.contains($0) } || excusingOmittedValues && isOmittedValueError(error)
		}
	}

	/// The names generated code gives a hole's builders and places, which a hand-written caller spells: each label of a
	/// parameter of a seam's generated initializer or a generated mock whose type names a scope of places (`SafeDIScope_…`,
	/// `SafeDISendableScope_…`, or a public mock's `…MockScope_…`), as `<Type>(<label>:)`; each such
	/// scope type an extension declares, as `<Type>.<scope>`; and each case of one, as `<Type>.<scope>.<case>`. A seam's
	/// labels are read from the initializer only generated code calls, which every module generates, without their
	/// `__safeDI_` prefix: they are the labels of the plain initializer a module that sets
	/// `generatePlainDependencyTreeInitializers` generates beside it, which names the same builders. A builder struct's
	/// members are read through the cases they are named for; a member without a case would need this reader extended.
	static func holeBuilderNames(in generatedFiles: [String: String]) -> Set<String> {
		let scopeDeclaration = try! NSRegularExpression(pattern: #"^    (?:@frozen )?(?:nonisolated )?(?:public |package |internal )?(?:enum|struct) (SafeDI\w*Scope_\w+) \{$"#)
		let scopeCase = try! NSRegularExpression(pattern: #"^        (?:indirect )?case (\w+)"#)
		func firstCapture(of expression: NSRegularExpression, in line: String) -> String? {
			let range = NSRange(line.startIndex..., in: line)
			guard let match = expression.firstMatch(in: line, range: range), let capture = Range(match.range(at: 1), in: line) else { return nil }
			return String(line[capture])
		}
		/// The label of `parameter`, `label: Type`, when its type names a scope of places, without a `__safeDI_` prefix.
		func builderLabel(of parameter: String) -> String? {
			guard let colon = parameter.firstIndex(of: ":"), parameter[colon...].contains("Scope_") else { return nil }
			return generatedOnlyLabel(of: parameter) ?? parameter[..<colon].trimmingCharacters(in: .whitespaces)
		}
		var names = Set<String>()
		for (_, contents) in generatedFiles.sorted(by: { $0.key < $1.key }) {
			var extendedType: String?
			var scope: String?
			var isInMockSignature = false
			for line in contents.components(separatedBy: "\n") {
				if line.hasPrefix("extension "), line.hasSuffix(" {") {
					extendedType = String(line.dropFirst("extension ".count).dropLast(2))
					scope = nil
					continue
				} else if line.hasPrefix("}") {
					extendedType = nil
					scope = nil
					continue
				}
				guard let extendedType else { continue }
				if let declaredScope = firstCapture(of: scopeDeclaration, in: line) {
					scope = declaredScope
					names.insert("\(extendedType).\(declaredScope)")
				} else if line == "    }" {
					scope = nil
				} else if let scope, let caseName = firstCapture(of: scopeCase, in: line) {
					names.insert("\(extendedType).\(scope).\(caseName)")
				} else if line.hasPrefix("    "), !line.hasPrefix("     "), line.hasSuffix("static func mock(") {
					isInMockSignature = true
				} else if isInMockSignature {
					if line.hasPrefix("    )") {
						isInMockSignature = false
					} else if let label = builderLabel(of: line) {
						names.insert("\(extendedType)(\(label):)")
					}
				} else if line.hasPrefix("    "), !line.hasPrefix("     "), let parametersStart = line.range(of: "init("), line.hasSuffix(") {") {
					let parameters = String(line[parametersStart.upperBound..<line.index(line.endIndex, offsetBy: -3)])
					for label in topLevelParameters(parameters).compactMap(builderLabel(of:)) {
						names.insert("\(extendedType)(\(label):)")
					}
				}
			}
		}
		return names
	}

	/// Whether `error`, a diagnostic line, reports a caller holding a value for a parameter the seam tier it calls
	/// omits: "`Host` provides `theme: Theme`, but …", or, where the provider's file cannot be read, "`Host` in module
	/// `Base` provides `theme: Theme`, but …", or, where a fill of a public mock's place holds the value, "`Panel`’s mock
	/// hands this fill `theme: Theme`, but …", or, where the caller is an outer seam that takes the value as a parameter of
	/// its own, "`Outer` takes `theme: Theme?` from its callers, but …".
	static func isOmittedValueError(_ error: Substring) -> Bool {
		omittedValueLabel(of: error) != nil
	}

	/// The label of the parameter an omitted-value error names: `theme` of "`Host` provides `theme: Theme`, but …", of
	/// "`Panel`’s mock hands this fill `theme: Theme`, but …" or of "`Outer` takes `theme: Theme?` from its callers, but …".
	static func omittedValueLabel(of error: Substring) -> String? {
		guard let message = error.range(of: ": error: ").map({ error[$0.upperBound...] }), message.hasPrefix("`") else { return nil }
		for (opening, closing) in [("` provides `", "`, but "), ("`’s mock hands this fill `", "`, but "), ("` takes `", "` from its callers, but ")] {
			if let property = message.range(of: opening), let end = message[property.upperBound...].range(of: closing) {
				return String(message[property.upperBound..<end.lowerBound].prefix { $0 != ":" })
			}
		}
		return nil
	}

	/// Whether `error` is an omitted-value error of an outer seam that takes the value from its own callers: "`Outer`
	/// takes `theme: Theme?` from its callers, but …".
	static func isOuterSeamOmittedValueError(_ error: Substring) -> Bool {
		omittedValueLabel(of: error) != nil && error.contains("` from its callers, but ")
	}

	/// The access levels SafeDI and Swift spell, narrowest first, as `GraphFuzzerGenerator.AccessLevel` orders them.
	static func accessLevel(spelled spelling: String) -> GraphFuzzerGenerator.AccessLevel {
		switch spelling {
		case "public", "open":
			.public
		case "package":
			.package
		default:
			.internal
		}
	}

	/// Each generated tier in `generatedFiles` wider than a type one of its parameters names, by `typeAccess` – the
	/// access of each type narrower than `public`, by the name its fixture spells it with – as a line naming the seam,
	/// the tier, the parameter and the type. Every type `typeAccess` does not name is `public`.
	static func tiersWiderThanParameterTypes(in generatedFiles: [String: String], typeAccess: [String: GraphFuzzerGenerator.AccessLevel]) -> [String] {
		var findings = [String]()
		for (fileName, contents) in generatedFiles.sorted(by: { $0.key < $1.key }) where !fileName.hasSuffix("+SafeDISeamCaller.swift") {
			for tier in seamInitializers(inGeneratedFile: contents) {
				let tierAccess = accessLevel(spelled: tier.access)
				for parameter in tier.parameters {
					let type = parameter.drop { $0 != ":" }.dropFirst().prefix { $0 != "=" }
					for name in typeNames(in: type) {
						guard let typeLevel = typeAccess[name], typeLevel < tierAccess else { continue }
						findings.append("\(fileName): `\(tier.seamTypeName)`’s `\(tier.access)` initializer takes `\(parameter.trimmingCharacters(in: .whitespaces))`, but `\(name)` is `\(typeLevel.spelling)`.")
					}
				}
			}
		}
		return findings
	}

	/// The names `type` spells: each run of identifier characters and dots, so a nested type is one name.
	private static func typeNames(in type: some StringProtocol) -> [String] {
		var names = [String]()
		var name = ""
		for character in type + " " {
			if character.isLetter || character.isNumber || character == "_" || character == "." {
				name.append(character)
			} else if !name.isEmpty {
				names.append(name)
				name = ""
			}
		}
		return names
	}

	/// The arguments of each call of `typeName`'s initializer in `contents` – `typeName(` not part of a longer name, and
	/// after the type that encloses it when it is a nested type's name – each as its label and the text it passes, in
	/// the order the code calls them.
	static func initializerCalls(of typeName: String, in contents: String) -> [[(label: String, value: String)]] {
		var calls = [[(label: String, value: String)]]()
		var searchStart = contents.startIndex
		while let range = contents.range(of: typeName + "(", range: searchStart..<contents.endIndex) {
			searchStart = range.upperBound
			if range.lowerBound > contents.startIndex {
				let previous = contents[contents.index(before: range.lowerBound)]
				guard !(previous.isLetter || previous.isNumber || previous == "_") else { continue }
			}
			var depth = 1
			var end = range.upperBound
			while depth > 0, end < contents.endIndex {
				switch contents[end] {
				case "(", "[":
					depth += 1
				case ")", "]":
					depth -= 1
				default:
					break
				}
				end = contents.index(after: end)
			}
			let arguments = topLevelParameters(String(contents[range.upperBound..<contents.index(before: end)])).compactMap { argument -> (label: String, value: String)? in
				guard let colon = argument.firstIndex(of: ":") else { return nil }
				return (argument[..<colon].trimmingCharacters(in: .whitespaces), argument[argument.index(after: colon)...].trimmingCharacters(in: .whitespaces))
			}
			calls.append(arguments)
		}
		return calls
	}

	/// What each of a seam's own errors says after the location: the label collision, the tier that cannot take a
	/// parameter, the redeclared initializer, the declaration the callers cannot see, and the signatures that do not
	/// settle all open with the first; a missing module info with the second; and a `@Sendable` builder inside the
	/// seam capturing a wrapper parameter – declared outside every builder function of the generated initializer,
	/// whatever the caller would pass – contains the third. An inlined tree's capture names the declaring type
	/// instead; a mock root's capture of a wrapper it is handed prints the same words, and cannot make a differential
	/// failure, since a mock is built the same with and without the seam, so inline rejects it too. A receive hidden
	/// inside a seam's tree is reported hidden in a chain that starts at the seam, on every path and whatever a caller
	/// holds, where inline reports it only in a chain from a root that provides the property (`isSeamOnlyRejection`
	/// adds that marker per seam type).
	private static let seamOnlyErrorMarkers = [
		"error: SafeDI cannot generate the dependency tree of `",
		"error: SafeDI cannot generate a call to the initializer SafeDI generated for `",
		"` receives from outside it, because `",
		// A fill's own errors: what the struct does not carry, what a re-entering call or a passing-up seam hides, or an
		// instantiator the seam's tree is building where it calls the builder, which inline is a wrapper made again in a loop.
		"the builder for `",
		"the builders for `",
		"but that call passes the builder `",
	]

	/// The renamings the graph is split across modules under, besides the graph as generated (`nil`). See
	/// `GraphFuzzerPartition`.
	static let multiModuleRenamings: [GraphFuzzerRenaming?] = [nil]

	/// Runs the tool twice over `fixture`, once over it renamed by each of `renamings`, and, when it declares no seam and
	/// no public mock, split across modules by `GraphFuzzerPartition` and renamed by each of `multiModuleRenamings`, once
	/// through each multi-module integration.
	static func toolRuns(
		of fixture: GraphFuzzerFixture,
		renamings: [GraphFuzzerRenaming] = GraphFuzzerRenaming.all,
		multiModuleRenamings: [GraphFuzzerRenaming?] = multiModuleRenamings,
	) async throws -> GraphFuzzerToolRuns {
		var renamedOutcomes = [(renaming: GraphFuzzerRenaming, outcome: GraphFuzzerToolOutcome)]()
		for renaming in renamings {
			let renamedFixture = fixture.renamed(by: renaming)
			let outcome = try await toolOutcome(of: renamedFixture, fileNames: renaming.fileNames(of: renamedFixture))
			renamedOutcomes.append((renaming, renaming.restore(outcome, typeNamePrefix: fixture.typeNamePrefix)))
		}
		// The partition splits only a graph that declares no seam and no public mock, as no graph of the base corpus does:
		// a seam's or a public mock's graph is split across modules by roles of its own (`GraphFuzzerModule`), which the
		// partition does not model.
		var multiModuleRuns = [GraphFuzzerMultiModuleRuns]()
		if GraphFuzzerGeneratorFeature.features(drawnIn: fixture).isEmpty {
			let partition = GraphFuzzerPartition.partition(of: fixture)
			multiModuleRuns = try await GraphFuzzerPhaseAccount.measuring(.multiModule) {
				var multiModuleRuns = [GraphFuzzerMultiModuleRuns]()
				for renaming in multiModuleRenamings {
					await multiModuleRuns.append(try GraphFuzzerMultiModuleProperty.runs(of: fixture, partition: partition, renaming: renaming))
				}
				return multiModuleRuns
			}
		}
		// The levels of each place of a seam the first run computes must be the same on every build of a type
		// (`placeLevelsFailure`).
		// The paths of the places the first run computes must repeat no declaration (`placeChainFailure`), and their cases
		// must be the ones the generated scope enums declare (`scopeCaseFailures`).
		// The validation walk skips a subtree whose walk along an equal context completed and found nothing. A graph whose
		// first run skipped one is run again with no skip, which must give the same outcome (`cleanSubtreeSkipFailure`).
		let (skippedSubtrees, skippedSubtreesContinuation) = AsyncStream.makeStream(of: Void.self)
		// Every root's root functions with one key must have one text (`rootFunctionKeyFailure`).
		// The call of `addingPlacesOfOneCaseShapes`' seam must build one fill per kind of place
		// (`placesJudgedByAnotherPlacesFillFailure`).
		let (fillsOfCallsStream, fillsOfCallsContinuation) = AsyncStream.makeStream(of: SeamFillSharing.FillsOfCall.self)
		let (((firstOutcome, placeLevelDisagreements), placeFacts), rootFunctionKeyDisagreements) = try await collectingRootFunctionKeyDisagreements(during: {
			try await collectingPlaceFacts(during: {
				try await collectingPlaceLevelDisagreements(during: {
					try await ValidationWalkObservation.$observer.withValue({ observation in
						if case .skippedCleanSubtree = observation {
							skippedSubtreesContinuation.yield()
						}
					}) {
						try await SeamFillSharing.$observer.withValue({ fillsOfCallsContinuation.yield($0) }) {
							try await toolOutcome(of: fixture)
						}
					}
				})
			})
		})
		fillsOfCallsContinuation.finish()
		var fillsOfCalls = [SeamFillSharing.FillsOfCall]()
		for await fills in fillsOfCallsStream {
			fillsOfCalls.append(fills)
		}
		skippedSubtreesContinuation.finish()
		var skippedSubtreeCount = 0
		for await _ in skippedSubtrees {
			skippedSubtreeCount += 1
		}
		let cleanSubtreeSkipOffOutcome: GraphFuzzerToolOutcome? = skippedSubtreeCount > 0
			? try await ValidationWalkObservation.$skipsCleanSubtrees.withValue(false) { try await toolOutcome(of: fixture) }
			: nil
		// A graph with a seam is run again with no seam: a rejection inline does not make is either a seam's own error
		// or a defect (`differentialFailure`), and an accepted graph must pass no receiver `nil` that inline passes a
		// value (`nilArgumentFailure`).
		// The inline build and the known-right path build in a caller what a seam or public mock would have built in its own
		// module, so each module lists every module it depends on, directly or through another, as 2.2.0 asked: a module
		// reads no type from a view.
		let inlineOutcome: GraphFuzzerToolOutcome? = fixture.declaresSeam ? try await toolOutcome(of: fixture.withoutSeams, listsTransitiveDependencies: true) : nil
		// A graph with a hole is run again with the fulfilling type in the seam's module, whose values a fill must equal.
		let visibleOutcome: GraphFuzzerToolOutcome? = fixture.drawsHole ? try await toolOutcome(of: fixture.withoutHoles) : nil
		// A graph with a public mock is run again as its known-right path, every declaration `public` and every `.public`
		// mock `true`: the two must accept the same graphs but for a public mock's own errors
		// (`publicMockAcceptanceFailure`), and build the same values (`valueFailures`).
		let knownRightOutcome: GraphFuzzerToolOutcome? = GraphFuzzerGeneratorFeature.features(drawnIn: fixture).contains(.generateMockPublic)
			? try await toolOutcome(of: GraphFuzzerGenerator.knownRightPublicMockFixture(forSeed: fixture.seed), listsTransitiveDependencies: true)
			: nil
		// A graph split across modules is run again as the SwiftPM plugin runs the tool, which computes every seam
		// signature, tier and public mock from source: the two must agree (`integrationsDisagreeFailure`). A graph with a
		// module run without its package's name models Tuist or Bazel alone, since the plugin always knows the package.
		let pluginOutcome: GraphFuzzerToolOutcome? = fixture.modules != nil && fixture.modulesOmittingPackageName.isEmpty
			? try await toolOutcome(of: fixture, integration: .swiftPackagePlugin)
			: nil
		// A graph split across modules that declares a seam or a public mock is run again with every `.safedi` file's seam
		// signatures and public mock plans discarded, so each module computes the signatures of the seams it calls and the
		// plans of the public mocks its mocks call from the declarations: the two must agree byte for byte
		// (`storedSeamSignaturesDisagreeFailure`).
		let recomputedSignaturesOutcome: GraphFuzzerToolOutcome? = fixture.modules != nil && (fixture.declaresSeam || GraphFuzzerGeneratorFeature.features(drawnIn: fixture).contains(.generateMockPublic))
			? try await toolOutcome(of: fixture, discardingStoredSeamSignatures: true)
			: nil
		// A graph that names a type no declaration SafeDI reads declares is run again as its read twin, which declares that
		// type `public` where SafeDI reads it, under each flow the graph is run under: SafeDI counts the type as `public`, so
		// the two must agree but for the comment naming it (`readTwinFailure`).
		var readTwinOutcome: GraphFuzzerToolOutcome?
		var readTwinPluginOutcome: GraphFuzzerToolOutcome?
		if let readTwin = fixture.readTwin {
			readTwinOutcome = try await readTwin.restoring(toolOutcome(of: readTwin.fixture))
			if pluginOutcome != nil {
				readTwinPluginOutcome = try await readTwin.restoring(toolOutcome(of: readTwin.fixture, integration: .swiftPackagePlugin))
			}
		}
		// A base corpus graph the tool accepts is run again as its value-oracle fixture, whose root mocks and mirrors the
		// value oracle compares with their production builds (`valueFailures`).
		var valueOracle: GraphFuzzerValueOracleRun?
		if compileVerificationIsEnabled, GraphFuzzerGeneratorFeature.features(drawnIn: fixture).isEmpty, fixture.modules == nil, case let .accepted(generatedFiles, _) = firstOutcome {
			let plan = GraphFuzzerValueOraclePlan(fixture: fixture, generatedFiles: generatedFiles)
			valueOracle = try await GraphFuzzerValueOracleRun(
				plan: plan,
				outcome: plan.modelFailures.isEmpty ? toolOutcome(of: plan.valueOracleFixture(storingEveryParameter: false)) : nil,
			)
		}
		// A graph with a hole drawn with a second place of it is run again without that place, which must leave every builder
		// label and case name the tool generates as it is (`holeNameStabilityFailure`). Regenerated from the seed, so only a
		// graph the generator draws for its seed has one.
		var withoutSecondHolePlaceOutcome: (place: String, outcome: GraphFuzzerToolOutcome)?
		let drawnFeatures = GraphFuzzerGeneratorFeature.features(drawnIn: fixture)
		let isDrawnForItsSeed = !drawnFeatures.isEmpty && GraphFuzzerGenerator.fixture(forSeed: fixture.seed, features: drawnFeatures).swiftFileContent == fixture.swiftFileContent
		if isDrawnForItsSeed, case .accepted = firstOutcome,
		   let withoutPlace = GraphFuzzerGenerator.fixtureWithoutSecondHolePlace(forSeed: fixture.seed, features: drawnFeatures)
		{
			withoutSecondHolePlaceOutcome = try await (withoutPlace.place, toolOutcome(of: withoutPlace.fixture))
		}
		// A graph drawn with a second path to a type that holds a place is run again without it, which must change nothing
		// but the path's own case (`secondPathFailure`).
		var withoutSecondPath: GraphFuzzerSecondPathRun?
		if isDrawnForItsSeed, case .accepted = firstOutcome,
		   let withoutPath = GraphFuzzerGenerator.fixtureWithoutSecondPath(forSeed: fixture.seed, features: drawnFeatures)
		{
			let (outcome, facts) = try await collectingPlaceFacts(during: { try await toolOutcome(of: withoutPath.fixture) })
			withoutSecondPath = GraphFuzzerSecondPathRun(typeName: withoutPath.typeName, label: withoutPath.label, outcome: outcome, placeFacts: facts)
		}
		// A base corpus graph the tool rejects is run again with each remedy its errors state, each of which must leave no
		// error where the error is (`remedyFailure`).
		let remedyRuns = try await remedyRuns(of: fixture, outcome: firstOutcome)
		// A graph with a hole the tool accepts is run again with each builder surface edit that applies to it, whose
		// readable initializers and mocks the builder surface's parts judge (`sameSupplyFailure` and the parts after it).
		var builderSurfaceRuns = [GraphFuzzerBuilderSurfaceRun]()
		var drawnHolePlaces = [GraphFuzzerDrawnHolePlace]()
		if isDrawnForItsSeed, case .accepted = firstOutcome {
			for edit in GraphFuzzerBuilderSurfaceEdit.allCases {
				guard let edited = GraphFuzzerGenerator.fixture(forSeed: fixture.seed, features: drawnFeatures, builderSurfaceEdit: edit) else { continue }
				let run = try await toolRun(of: edited, listsTransitiveDependencies: edit.listsTransitiveDependencies)
				builderSurfaceRuns.append(GraphFuzzerBuilderSurfaceRun(edit: edit, fixture: edited, outcome: run.outcome, rejectingModuleName: run.rejectingModuleName))
			}
			drawnHolePlaces = GraphFuzzerGenerator.drawnHolePlaces(forSeed: fixture.seed, features: drawnFeatures)
		}
		// A graph in one module the tool accepts is exported by `query graph`, whose suppliers must be what the generated code
		// hands each receive (`querySuppliersFailure`).
		var queryExport: String?
		if fixture.modules == nil, !drawnFeatures.contains(.generateMockPublic), case .accepted = firstOutcome {
			queryExport = try await GraphFuzzerQuerySupplies.export(of: fixture)
		}
		return try await GraphFuzzerToolRuns(
			fixture: fixture,
			firstOutcome: firstOutcome,
			// The second run creates the mock roots in reverse order, so that a construction memo shared between them
			// carries other roots' generators to each, and shares generators between places by a schedule of its seed
			// (`ConstructionSharingSchedule.sharingOracleSchedule(forGraphSeed:)`), and interns in another order, reversed or
			// permuted by its seed (`ConstructionInternerOrder.secondRun(forGraphSeed:)`), which gives every ID another value;
			// it must still give the first run's outcome. A hand mutation that appends a root's interned type ID to its
			// generated code fails seed 0 (reversed) and seed 1 (permuted) of the base corpus with "two runs of the tool differ".
			// It also builds a fill for every place of every seam call, where the first run builds one for the places of a
			// case whose fills would be built alike (`SeamFillSharing`), so a place judged against another place's fill must
			// be judged as against its own.
			secondOutcome: ConstructionMemoOracle.$buildsMockRootsInReverseOrder.withValue(true) {
				try await ConstructionSharingSchedule.$current.withValue(.sharingOracleSchedule(forGraphSeed: fixture.seed)) {
					try await ConstructionInternerOrder.secondRun(forGraphSeed: fixture.seed).applying {
						try await SeamFillSharing.$buildsFillOfEveryPlace.withValue(true) {
							try await toolOutcome(of: fixture)
						}
					}
				}
			},
			cleanSubtreeSkipOffOutcome: cleanSubtreeSkipOffOutcome,
			renamedOutcomes: renamedOutcomes,
			inlineOutcome: inlineOutcome,
			visibleOutcome: visibleOutcome,
			knownRightOutcome: knownRightOutcome,
			multiModuleRuns: multiModuleRuns,
			pluginOutcome: pluginOutcome,
			recomputedSignaturesOutcome: recomputedSignaturesOutcome,
			readTwinOutcome: readTwinOutcome,
			readTwinPluginOutcome: readTwinPluginOutcome,
			valueOracle: valueOracle,
			withoutSecondHolePlaceOutcome: withoutSecondHolePlaceOutcome,
			placeLevelDisagreements: placeLevelDisagreements,
			rootFunctionKeyDisagreements: rootFunctionKeyDisagreements,
			fillsOfCalls: fillsOfCalls,
			placeFacts: placeFacts,
			withoutSecondPath: withoutSecondPath,
			remedyRuns: remedyRuns,
			builderSurfaceRuns: builderSurfaceRuns,
			drawnHolePlaces: drawnHolePlaces,
			queryExport: queryExport,
		)
	}

	/// Runs SafeDITool once over `fixture`, as `executeSafeDIToolTest` runs it for every other generator test.
	/// - Parameters:
	///   - fileNames: The names to give the fixture's files, in its order, or `nil` to name each after the type it
	///     declares, as `executeSafeDIToolTest` does.
	///   - integration: How the tool runs over a graph split across modules.
	///   - listsTransitiveDependencies: Whether each module of a graph split across modules lists every module it depends
	///     on rather than the modules it imports and those its mocks reach, for a build that constructs in a caller what a
	///     seam or public mock would.
	///   - discardingStoredSeamSignatures: Whether each module of a graph split across modules computes the signatures of
	///     the seams it calls from the declarations, rather than reading them from their modules' `.safedi` files.
	static func toolOutcome(of fixture: GraphFuzzerFixture, fileNames: [String]? = nil, integration: MultiModuleIntegration = .moduleInfo, listsTransitiveDependencies: Bool = false, discardingStoredSeamSignatures: Bool = false) async throws -> GraphFuzzerToolOutcome {
		try await toolRun(of: fixture, fileNames: fileNames, integration: integration, listsTransitiveDependencies: listsTransitiveDependencies, discardingStoredSeamSignatures: discardingStoredSeamSignatures).outcome
	}

	/// The tool's outcome for `fixture`, as `toolOutcome(of:fileNames:integration:listsTransitiveDependencies:)` gives it,
	/// with the name of the module whose `generate` rejected a graph split across modules: `nil` where the tool accepts the
	/// graph, or where the graph is in one module, which is then the module that rejects it.
	static func toolRun(of fixture: GraphFuzzerFixture, fileNames: [String]? = nil, integration: MultiModuleIntegration = .moduleInfo, listsTransitiveDependencies: Bool = false, discardingStoredSeamSignatures: Bool = false) async throws -> (outcome: GraphFuzzerToolOutcome, rejectingModuleName: String?) {
		// A stored block that does not read back is reported by the run's harness, which knows no seed (`StoredBlockDecodeChecks`).
		try await StoredBlockDecodeChecks.$runDescription.withValue("graph fuzzer seed \(fixture.seed)") {
			try await toolRunOfGraph(of: fixture, fileNames: fileNames, integration: integration, listsTransitiveDependencies: listsTransitiveDependencies, discardingStoredSeamSignatures: discardingStoredSeamSignatures)
		}
	}

	/// See `toolRun(of:fileNames:integration:listsTransitiveDependencies:discardingStoredSeamSignatures:)`.
	private static func toolRunOfGraph(of fixture: GraphFuzzerFixture, fileNames: [String]?, integration: MultiModuleIntegration, listsTransitiveDependencies: Bool, discardingStoredSeamSignatures: Bool) async throws -> (outcome: GraphFuzzerToolOutcome, rejectingModuleName: String?) {
		if let modules = fixture.modules {
			return try await splitToolRun(of: fixture, modules: modules, fileNames: fileNames ?? fixture.fileNames, integration: integration, listsTransitiveDependencies: listsTransitiveDependencies, discardingStoredSeamSignatures: discardingStoredSeamSignatures)
		}
		var filesToDelete = [URL]()
		defer {
			for fileToDelete in filesToDelete {
				try? FileManager.default.removeItem(at: fileToDelete)
			}
		}
		do {
			let output = try await executeSafeDIToolTest(
				swiftFileContent: fileNames == nil ? fixture.swiftFileContent : [],
				swiftFileContentByFilePath: fileNames.map { Dictionary(uniqueKeysWithValues: zip($0, fixture.swiftFileContent)) } ?? [:],
				buildSwiftOutputDirectory: true,
				filesToDelete: &filesToDelete,
				skipCompileVerification: true,
				activeCompilationConditions: fixture.activeCompilationConditions,
				// The fuzzer's graphs are no test's expectations, so a record run never writes them.
				recordDirectory: nil,
			)
			let normalize = try normalizer(fixtureDirectory: fixtureDirectory(of: fileNames ?? fixture.fileNames, in: output.fixtures, seed: fixture.seed).path)
			return (.accepted(
				generatedFiles: addingSeamCallers(to: (output.generatedFiles ?? [:]).mapValues(normalize), seamTypeAccess: fixture.seamTypeAccess),
				warnings: output.warnings.map { normalize("\($0)") },
			), nil)
		} catch let error as SafeDIToolTestError {
			let directory = try fixtureDirectory(of: fileNames ?? fixture.fileNames, in: error.fixtures, seed: fixture.seed)
			// `executeSafeDIToolTest` schedules the fixture directory for deletion only when `generate` succeeds.
			filesToDelete.append(directory)
			return (.rejected(diagnostics: normalizer(fixtureDirectory: directory.path)("\(error.underlyingError)")), nil)
		} catch {
			// `executeSafeDIToolTest` wraps every error `generate` throws, so this is the harness failing, such as a
			// fixture it could not write: not the tool rejecting the graph.
			throw GraphFuzzerInfrastructureError(description: "The test harness failed for seed \(fixture.seed) before or after SafeDITool ran: \(error)")
		}
	}

	/// Runs SafeDITool over `fixture`, a graph split across modules, as `integration` runs it. As Bazel runs it
	/// (`.moduleInfo`), one `generate` per module, in dependency order, each reading the `.safedi` files of the modules it
	/// depends on and naming its module and package, writes one combined output, which is decomposed into the files one
	/// module writes; as the SwiftPM plugin runs it (`.swiftPackagePlugin`), `scan` and `generate` per module read the
	/// module's own files and its dependencies' and write those files. Each module lists what
	/// `GraphFuzzerFixture.dependencyLists(modules:integration:listsTransitiveDependencies:)` gives it: the modules it
	/// imports and, under `.moduleInfo`, each module beneath whose types its mocks build, or every module it depends on,
	/// with `listsTransitiveDependencies`, as 2.2.0 asked, and where it declares a root, a seam's included, whose tree
	/// reaches a place through a seam beneath the seam's module (`GraphFuzzerFixture.modulesListingEveryModuleBeneath`).
	/// Each generated file is keyed by its module's name and its own (`FuzzFeature/Type+SafeDI.swift`), and the outcome is
	/// the first module's error, if any, with that module's name.
	private static func splitToolRun(of fixture: GraphFuzzerFixture, modules: [GraphFuzzerModule], fileNames: [String], integration: MultiModuleIntegration, listsTransitiveDependencies: Bool, discardingStoredSeamSignatures: Bool) async throws -> (outcome: GraphFuzzerToolOutcome, rejectingModuleName: String?) {
		var filesToDelete = [URL]()
		defer {
			for fileToDelete in filesToDelete {
				try? FileManager.default.removeItem(at: fileToDelete)
			}
		}
		let presentModules = Set(modules)
		let dependencyLists = fixture.dependencyLists(modules: modules, integration: integration, listsTransitiveDependencies: listsTransitiveDependencies)
		let moduleFixtures = GraphFuzzerModule.allCases.filter(presentModules.contains).map { module in
			ModuleFixture(
				name: module.name,
				packageName: module.packageName,
				swiftFileContentByFilePath: Dictionary(uniqueKeysWithValues: modules.indices.filter { modules[$0] == module }.map { (fileNames[$0], fixture.swiftFileContent[$0]) }),
				dependencies: (dependencyLists[module] ?? []).map(\.name),
				omitsPackageName: fixture.modulesOmittingPackageName.contains(module),
			)
		}
		do {
			// The fuzzer's graphs are no test's expectations, so a record run never writes them.
			let output = try await executeSafeDIToolMultiModuleTest(modules: moduleFixtures, integration: integration, compileVerification: .skipped, discardsStoredSeamSignatures: discardingStoredSeamSignatures, filesToDelete: &filesToDelete, recordDirectory: nil)
			let normalize = normalizer(fixtureDirectory: output.fixtureRoot.path)
			var generatedFiles = [String: String]()
			var warnings = [String]()
			for moduleName in output.moduleNames {
				guard let moduleOutput = output.modules[moduleName] else { continue }
				for (outputFileName, contents) in moduleOutput.generatedFiles {
					switch integration {
					case .moduleInfo:
						for (fileName, fileContents) in decomposingCombinedOutput(normalize(contents)) {
							generatedFiles["\(moduleName)/\(fileName)"] = fileContents
						}
					case .swiftPackagePlugin:
						generatedFiles["\(moduleName)/\(outputFileName)"] = normalize(contents)
					}
				}
				warnings += moduleOutput.warnings.map { normalize("\($0)") }
			}
			return (.accepted(
				generatedFiles: addingOverrideClosureCallers(
					to: addingPublicMockCallers(
						to: addingSeamCallers(to: generatedFiles, seamTypeAccess: fixture.seamTypeAccess, modules: presentModules),
						of: fixture,
					),
					of: fixture,
				),
				warnings: warnings,
			), nil)
		} catch let error as SafeDIToolMultiModuleTestError {
			// The harness registers the fixture root for deletion before it writes anything.
			let normalize = normalizer(fixtureDirectory: filesToDelete.first?.path ?? "")
			return (.rejected(diagnostics: normalize("\(error.underlyingError)")), error.moduleName)
		} catch {
			throw GraphFuzzerInfrastructureError(description: "The test harness failed for seed \(fixture.seed) before or after SafeDITool ran: \(error)")
		}
	}

	/// `contents`, a module's combined output, as the files `executeSafeDIToolTest` writes for one module, each with the
	/// combined output's header and imports: each type's extensions, `<Type>+SafeDI.swift`; each type's mock, the
	/// conditional block declaring `mock()`, `<Type>+SafeDIMock.swift`; and the mock configurations, the conditional block
	/// declaring none, `SafeDIMockConfiguration.swift`, which a public mock's module-level configurations open with their
	/// documentation. A combined output declares its files' extensions in the files' path order, which a file-name
	/// reversal reverses; one file per type compares, compiles, and is probed as the per-file outputs of a graph in one
	/// module are.
	static func decomposingCombinedOutput(_ contents: String) -> [String: String] {
		let lines = contents.split(separator: "\n", omittingEmptySubsequences: false)
		/// Whether a block begins at `index`: an extension, or a conditional block whose first declaration is one or a
		/// public mock's module-level configuration.
		func beginsBlock(at index: Int) -> Bool {
			lines[index].hasPrefix("extension ")
				|| beginsPublicConfigurationDeclaration(at: index)
				|| lines[index].hasPrefix("#if ") && lines[(index + 1)...].first { !$0.isEmpty }.map { firstLine in
					firstLine.hasPrefix("extension ") || firstLine.hasPrefix("/// Configuration for how ")
				} == true
		}
		/// Whether an unconditional public mock's module-level configuration, or a forwarder of a default, begins at `index`.
		func beginsPublicConfigurationDeclaration(at index: Int) -> Bool {
			lines[index].hasPrefix("/// Configuration for how ") || lines[index].hasPrefix("@usableFromInline ")
		}
		guard let firstBlock = lines.indices.first(where: beginsBlock(at:)) else { return ["Combined.swift": contents] }
		let header = lines[..<firstBlock].joined(separator: "\n")
		var blocksByFileName = [String: [String]]()
		var index = firstBlock
		while index < lines.count {
			guard beginsBlock(at: index) else {
				index += 1
				continue
			}
			let isConditional = lines[index].hasPrefix("#if ")
			let isForwarder = lines[index].hasPrefix("@usableFromInline ")
			let end = isForwarder ? index : lines[(index + 1)...].firstIndex { isConditional ? $0.hasPrefix("#endif") : $0.hasPrefix("}") } ?? (lines.count - 1)
			let block = lines[index...end]
			let extendedType = block.first { $0.hasPrefix("extension ") }.map { String($0.dropFirst("extension ".count).prefix { $0 != " " && $0 != ":" }) } ?? "Combined"
			let fileName = if beginsPublicConfigurationDeclaration(at: index) {
				"SafeDIMockConfiguration.swift"
			} else if !isConditional {
				"\(extendedType)+SafeDI.swift"
			} else if block.contains(where: { $0.contains("static func mock(") }) {
				"\(extendedType)+SafeDIMock.swift"
			} else {
				"SafeDIMockConfiguration.swift"
			}
			blocksByFileName[fileName, default: []].append(block.joined(separator: "\n"))
			index = end + 1
		}
		return blocksByFileName.mapValues { header + "\n" + $0.joined(separator: "\n\n") + "\n" }
	}

	/// The top-level declarations each module of a split graph generates, by module name, on which the SwiftPM plugin
	/// flow and the module-info flow must agree: every generated file but the oracle's own callers, in blocks that begin
	/// where a line begins as `integrationComparedBlockStarts` say. What the flows spell differently is dropped first:
	/// `#sourceLocation` directives, which only a flow that knows the compiler's spelling of a path emits, the header
	/// lines every generated file opens with, the lines `integrationSpecificCommentLines` begin, and the comments of
	/// `integrationSpecificTrailingComments`. The blocks are
	/// a set, since the plugin repeats a module's imports in every file it writes, where a combined output states them
	/// once.
	static func integrationComparedBlocks(of generatedFiles: [String: String]) -> [String: Set<String>] {
		var blocksByModuleName = [String: Set<String>]()
		for (fileName, contents) in generatedFiles where !fileName.hasSuffix("+SafeDISeamCaller.swift") && !fileName.hasSuffix(publicMockCallerFileSuffix) {
			let moduleName = String(fileName.prefix { $0 != "/" })
			var block = [Substring]()
			func endBlock() {
				let text = block.joined(separator: "\n").trimmingCharacters(in: .whitespacesAndNewlines)
				if !text.isEmpty {
					blocksByModuleName[moduleName, default: []].insert(text)
				}
				block = []
			}
			for line in contents.split(separator: "\n", omittingEmptySubsequences: false) {
				let trimmedLine = line.trimmingCharacters(in: .whitespaces)
				guard !trimmedLine.hasPrefix("#sourceLocation"),
				      !generatedFileHeaderLines.contains(trimmedLine),
				      !integrationSpecificCommentLines.contains(where: { trimmedLine.hasPrefix($0) })
				else { continue }
				let code = integrationSpecificTrailingComments.reduce(line) { code, comment in
					code.range(of: comment).map { code[..<$0.lowerBound] } ?? code
				}
				if integrationComparedBlockStarts.contains(where: { code.hasPrefix($0) }) {
					endBlock()
				}
				block.append(code)
			}
			endBlock()
		}
		// A module whose generated code declares nothing – one beneath the seam's module, which holds no seam or mock – gets
		// a combined output of imports alone from the module-info flow, and no file from the plugin flow.
		return blocksByModuleName.filter { _, blocks in !blocks.allSatisfy(isImportBlock) }
	}

	/// Whether `block` holds only imports and the conditions around them.
	private static func isImportBlock(_ block: String) -> Bool {
		block.split(separator: "\n").allSatisfy { line in
			let trimmedLine = line.trimmingCharacters(in: .whitespaces)
			return trimmedLine.hasPrefix("#if ") || trimmedLine == "#else" || trimmedLine == "#endif" || trimmedLine.split(separator: " ").contains("import")
		}
	}

	/// The first top-level declaration, in module and then text order, that one of the two flows generates and the other
	/// does not (`integrationComparedBlocks(of:)`), described with the flow and the module, or `nil` when they generate
	/// the same declarations.
	///
	/// A compile-time assertion of one decision that only the plugin flow writes in a module is no difference when the
	/// decision's condition is in `conditionsSpelledOnlyInDependencies` for that module: the plugin reads a dependency's
	/// files under the reading module's conditions, so the reading module asserts the decisions it made about the
	/// dependency's blocks, as it asserts a dependency's `@Instantiable` decisions (the Manual's limit on a dependency's
	/// conditions), while the module-info flow reads the dependency's `.safedi` and leaves them to the dependency, which
	/// asserts them under both flows. Every other block either flow alone generates is a difference.
	static func firstDeclarationOneIntegrationGenerates(moduleInfoFiles: [String: String], pluginFiles: [String: String], conditionsSpelledOnlyInDependencies: [String: Set<String>]) -> String? {
		let moduleInfoBlocks = integrationComparedBlocks(of: moduleInfoFiles)
		let pluginBlocks = integrationComparedBlocks(of: pluginFiles)
		return Set(moduleInfoBlocks.keys).union(pluginBlocks.keys).sorted().lazy.compactMap { moduleName -> String? in
			let moduleInfoModuleBlocks = moduleInfoBlocks[moduleName, default: []]
			let pluginModuleBlocks = pluginBlocks[moduleName, default: []]
			let dependencyConditions = conditionsSpelledOnlyInDependencies[moduleName, default: []]
			if let block = moduleInfoModuleBlocks.subtracting(pluginModuleBlocks).sorted().first {
				return "Only the module-info flow generates, in \(moduleName):\n\(block)"
			} else if let block = pluginModuleBlocks.subtracting(moduleInfoModuleBlocks).sorted().first(where: { block in
				compileTimeAssertionCondition(of: block).map { !dependencyConditions.contains($0) } ?? true
			}) {
				return "Only the SwiftPM plugin flow generates, in \(moduleName):\n\(block)"
			} else {
				return nil
			}
		}.first
	}

	/// The condition of the decision `block` asserts, when `block` is the compile-time assertion of one decision that a
	/// generated file opens with – `#if <condition>` with an `#error` saying SafeDI assumed it inactive, or
	/// `#if !(<condition>)` with one saying SafeDI assumed it active, then `#endif` – or `nil`.
	static func compileTimeAssertionCondition(of block: String) -> String? {
		let lines = block.split(separator: "\n", omittingEmptySubsequences: false)
		guard lines.count == 3,
		      lines[2] == "#endif",
		      lines[1].hasPrefix(compileTimeAssertionErrorPrefix),
		      let conditionEnd = lines[1].range(of: "` was ")
		else { return nil }
		let condition = String(lines[1][lines[1].index(lines[1].startIndex, offsetBy: compileTimeAssertionErrorPrefix.count)..<conditionEnd.lowerBound])
		let assumedActive = lines[1][conditionEnd.upperBound...].hasPrefix("active, but it is inactive in this compilation.")
		let assumedInactive = lines[1][conditionEnd.upperBound...].hasPrefix("inactive, but it is active in this compilation.")
		guard assumedActive || assumedInactive, lines[0] == "#if " + (assumedActive ? "!(\(condition))" : condition) else { return nil }
		return condition
	}

	/// How the `#error` of a compile-time assertion of one decision begins, up to the condition it names.
	static let compileTimeAssertionErrorPrefix = "#error(\"SafeDI scanned this module assuming `#if "

	/// How each line that begins a block `integrationComparedBlocks(of:)` compares begins: an extension, a conditional
	/// block, a public mock's module-level configuration or a forwarder of a default, or an import.
	static let integrationComparedBlockStarts = ["extension ", "#if ", "/// Configuration for how ", "@usableFromInline ", "import "]

	/// The lines every generated file opens with, in order.
	static let generatedFileHeaderLines = [
		"// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.",
		"// Any modifications made to this file will be overwritten on subsequent builds.",
		"// Please refrain from editing this file directly.",
	]

	/// The comment lines generated code carries in one flow and not the other: the comment naming the types SafeDI counts
	/// as `public` because it reads no declaration of them, which a run without a target graph writes, since it may not
	/// read every first-party module, and the SwiftPM plugin's flow, which reads them all, does not.
	static let integrationSpecificCommentLines = [unreadTypeCommentPrefix]

	/// How the comment naming the types SafeDI counts as `public` because it reads no declaration of them begins.
	static let unreadTypeCommentPrefix = "// SafeDI counts `"

	/// The trailing comments generated code carries in one flow and not the other: `// Declared at …`, which refers to an
	/// alias's declaration where a flow does not know the compiler's spelling of its path for a `#sourceLocation`
	/// directive, and the comment a seam call carries saying what to do when it does not compile, which each flow words
	/// for its own integration.
	static let integrationSpecificTrailingComments = [" // Declared at ", " // If this line does not compile, add the SafeDI plugin", " // If this line does not compile, compile the code SafeDI generates"]

	/// The failure of a graph whose `SafeDITool generate` output differs between two processes, which seed their
	/// hashing differently, or `nil` when both processes give the same output.
	///
	/// `toolRuns(of:)` runs the tool twice in this process, which shares one hash seed, so it cannot see output
	/// that depends on the iteration order of a `Set` or `Dictionary` of hashed values. This runs the
	/// `SafeDITool` executable twice over the same fixture files and compares its exit status, diagnostics, and
	/// combined output.
	static func crossProcessFailure(of fixture: GraphFuzzerFixture) async throws -> GraphFuzzerFailure? {
		guard let artifacts = SafeDIBuildArtifactLocator.locate() else {
			throw GraphFuzzerInfrastructureError(description: "Could not locate SafeDI build artifacts to find the SafeDITool executable.")
		}
		let toolURL = artifacts.safeDIMacrosToolPath.deletingLastPathComponent().appendingPathComponent("SafeDITool")
		guard FileManager.default.isExecutableFile(atPath: toolURL.path) else {
			throw GraphFuzzerInfrastructureError(description: "No SafeDITool executable at \(toolURL.path). Build the package with `swift build --build-tests`.")
		}
		let directory = TestTemporaryDirectory.root.appendingPathComponent("safedi-graph-fuzzer-processes-\(UUID().uuidString)")
		try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
		defer { try? FileManager.default.removeItem(at: directory) }
		let fixtureFiles = try zip(fixture.fileNames, fixture.swiftFileContent).map { fileName, content in
			let fileURL = directory.appendingPathComponent(fileName.replacingOccurrences(of: "/", with: "_"))
			try content.write(to: fileURL, atomically: true, encoding: .utf8)
			return fileURL
		}
		let inputsFile = directory.appendingPathComponent("inputs.csv")
		try fixtureFiles.map(\.path).joined(separator: ",").write(to: inputsFile, atomically: true, encoding: .utf8)
		var outputs = [String]()
		for run in 0..<2 {
			let outputFile = directory.appendingPathComponent("Generated\(run).swift")
			let result = try await runProcess(toolURL, arguments: ["generate", inputsFile.path, "--combined-output", outputFile.path])
			let output = (try? String(contentsOf: outputFile, encoding: .utf8)) ?? ""
			outputs.append("exit \(result.exitCode)\n\(result.stderr)\n\(output)")
		}
		guard outputs[0] != outputs[1] else { return nil }
		return GraphFuzzerFailure(seed: fixture.seed, kind: .runsDifferAcrossProcesses, details: "First process:\n\(outputs[0])\nSecond process:\n\(outputs[1])")
	}

	/// `generatedFiles` with, for each seam whose initializer the tool generated – a file that holds the enum generated
	/// beside it – a file holding hand-written calls of that initializer: functions that take a tier's parameters and
	/// pass each on. The oracle compiles them with the rest, so a generated initializer a caller outside SafeDI's
	/// generation cannot call fails there. Each function is spelled at the narrower of its tier's access and the seam
	/// type's (`seamTypeAccess`, read from the fixture), as a caller in the seam's module must spell it. In a graph split
	/// across modules, the callers in the seam's module are joined by a caller in each other module of the graph, which
	/// calls the narrowest tier its package can reach. Derived from the generated files, so the renamed graphs' callers
	/// are restored with their files.
	static func addingSeamCallers(to generatedFiles: [String: String], seamTypeAccess: [String: String] = [:], modules: Set<GraphFuzzerModule> = []) -> [String: String] {
		var generatedFiles = generatedFiles
		for (fileName, contents) in generatedFiles where contents.contains("enum __safeDI_") {
			let initializersBySeam = seamInitializersBySeam(inGeneratedFile: contents)
			// One file per seam, beside the file that generated it, so that a file's contents never depend on the order
			// a module's combined output declares its seams in.
			let directory = fileName.contains("/") ? String(fileName.prefix { $0 != "/" }) + "/" : ""
			// The modules the generated file imports, which the types a seam's parameters name may need: a module the seam's
			// module depends on, or `Foundation`.
			let imports = Set(contents.split(separator: "\n").filter { $0.hasPrefix("import ") }.map(String.init)).sorted()
			for (seamTypeName, initializers) in initializersBySeam {
				generatedFiles["\(directory)\(seamTypeName)+SafeDISeamCaller.swift"] = imports.map { $0 + "\n" }.joined() + (imports.isEmpty ? "" : "\n")
					+ seamCaller(named: "\(seamTypeName)SeamCaller", of: seamTypeName, calling: Array(initializers.enumerated()), seamTypeAccess: seamTypeAccess[seamTypeName] ?? "public")
			}
			// The callers in the other modules of a split graph, of each seam the seam's module generated.
			guard fileName.hasPrefix(GraphFuzzerModule.seamModule.name + "/") else { continue }
			for (seamTypeName, initializers) in initializersBySeam {
				let seamAccess = seamTypeAccess[seamTypeName] ?? "public"
				for (module, reachableAccesses, callerName) in [
					(GraphFuzzerModule.samePackageCaller, ["public", "package"], "SamePackageCaller"),
					(GraphFuzzerModule.otherPackageCaller, ["public"], "OtherPackageCaller"),
				] where modules.contains(module) && reachableAccesses.contains(seamAccess) {
					guard let tierIndex = initializers.lastIndex(where: { reachableAccesses.contains($0.access) }) else { continue }
					let callerImports = Set(imports + ["import \(GraphFuzzerModule.seamModule.name)"]).sorted()
					generatedFiles["\(module.name)/\(seamTypeName)+SafeDISeamCaller.swift"] = callerImports.map { $0 + "\n" }.joined() + "\n"
						+ seamCaller(named: "\(seamTypeName)\(callerName)", of: seamTypeName, calling: [(tierIndex, initializers[tierIndex])], seamTypeAccess: seamAccess)
				}
			}
		}
		return generatedFiles
	}

	/// What the name of each file `addingPublicMockCallers(to:of:)` adds ends with.
	static let publicMockCallerFileSuffix = "+SafeDIPublicMockCaller.swift"

	/// `generatedFiles` with, for each hand-written call of a public mock the fixture holds in a file that declares a
	/// `.public` mock – `GraphFuzzerPublicMockDraw.publicMockCallerMarker`, then the caller's module and the call – a file
	/// in that module holding a function that makes the call, `<Type>+SafeDIPublicMockCaller.swift`. The oracle compiles
	/// it with the rest, so a public mock a caller outside SafeDI's generation cannot call, with the builders the draw
	/// expects, fails there. The known-right path declares no `.public` mock, so it gets none. Read from the fixture's
	/// text, so a renamed graph's caller is renamed with it and restored with its files. The draw writes each builder as a
	/// closure over the enum, `{ _ in value }`; where the generated `mock()` takes its builder as a closure that takes
	/// nothing, the call passes `{ value }` instead (`GraphFuzzerPublicMockBuilders.labelsTakingNothing(of:in:)`), as a person writes it.
	static func addingPublicMockCallers(to generatedFiles: [String: String], of fixture: GraphFuzzerFixture) -> [String: String] {
		var generatedFiles = generatedFiles
		for content in fixture.swiftFileContent where content.contains("generateMock: .public") {
			for line in content.split(separator: "\n") where line.hasPrefix(GraphFuzzerPublicMockDraw.publicMockCallerMarker) {
				let moduleAndCall = line.dropFirst(GraphFuzzerPublicMockDraw.publicMockCallerMarker.count)
				guard let colon = moduleAndCall.firstIndex(of: ":"), let callee = moduleAndCall[moduleAndCall.index(after: colon)...].trimmingCharacters(in: .whitespaces).components(separatedBy: ".mock(").first else { continue }
				let moduleName = String(moduleAndCall[..<colon])
				var call = moduleAndCall[moduleAndCall.index(after: colon)...].trimmingCharacters(in: .whitespaces)
				// The draw writes each builder as a closure that ignores the scope it is handed, `<label>: { _ in `. Where the
				// generated `mock()` takes a closure that takes nothing under that label, the call passes one: each builder by its
				// label, however many the mock takes. A builder the mock takes that the call does not pass is left as it is: a
				// builder surface edit gives the mock builders after the draw wrote the call, which the same-supply judgment
				// judges. One the call passes under such a label in another form is a draw this reading does not know. A graph
				// renamed to change an order renames the type names the mock's labels are spelled from but not the call the
				// draw wrote, so where the call passes none of the mock's labels, each builder is converted by its form.
				let labelsTakingNothing = GraphFuzzerPublicMockBuilders.labelsTakingNothing(of: callee, in: generatedFiles)
				let passedLabels = labelsTakingNothing.filter { call.range(of: #"\b\#($0): "#, options: .regularExpression) != nil }
				if passedLabels.isEmpty, !labelsTakingNothing.isEmpty {
					call = call.replacingOccurrences(of: #"(\w+Builder\w*): \{ _ in "#, with: "$1: { ", options: .regularExpression)
				}
				for label in passedLabels {
					if call.range(of: #"\b\#(label): \{ _ in "#, options: .regularExpression) != nil {
						call = call.replacingOccurrences(of: #"\b\#(label): \{ _ in "#, with: "\(label): { ", options: .regularExpression)
					} else {
						Issue.record("The hand-written call of `\(callee)`’s public mock passes `\(label)`, which its `mock()` takes as a closure that takes nothing, in a form the conversion does not read: \(call)")
					}
				}
				// A mock isolated to the main actor through `mockAttributes` is called from a function isolated to it.
				let isolation = declaresMainActorMock(typeNamed: callee, in: content) ? "@MainActor " : ""
				generatedFiles["\(moduleName)/\(callee)\(publicMockCallerFileSuffix)"] = """
				import \(GraphFuzzerModule.seamModule.name)

				#if DEBUG
				public enum \(callee)PublicMockCaller {
				\t\(isolation)public static func call() -> \(callee) {
				\t\t\(call)
				\t}
				}
				#endif

				"""
			}
		}
		return generatedFiles
	}

	/// `generatedFiles` with, for a graph whose call of `OverriddenDetail`'s public mock can hand its override closure a
	/// builder a person writes for each place (`GraphFuzzerPublicMockDrawFeature.overrideClosureCallCanHand`), a file in
	/// `OverriddenScreen`'s module, `<OverriddenScreen>+SafeDIPublicMockCaller.swift`, holding the closure a person writes:
	/// it takes what the consumer's overrides member hands it and passes each on to `OverriddenDetail`'s `mock()`, under the
	/// label of the parameter of that type, so a builder handed without the `@escaping` the called `mock()` takes it with
	/// fails the compile. Every name is read from the generated code – the consumer's from its mock's file name, the called
	/// type's from the member's return type – so a renamed graph's caller is renamed with its files: the graph is chosen by
	/// the member alone, which the consumer's overrides hold exactly where the call can hand it
	/// (`GraphFuzzerToolRuns.publicMockOverrideClosureFailure` judges that), since the draw's features are read by the
	/// unrenamed names. The known-right path declares no `.public` mock, so it gets none.
	static func addingOverrideClosureCallers(to generatedFiles: [String: String], of fixture: GraphFuzzerFixture) -> [String: String] {
		guard fixture.swiftFileContent.contains(where: { $0.contains("OverriddenDetail") && $0.contains("generateMock: .public") }) else { return generatedFiles }
		var generatedFiles = generatedFiles
		let suffix = "OverriddenScreen+SafeDIMock.swift"
		for fileName in generatedFiles.keys.sorted() where fileName.hasSuffix(suffix) {
			guard let contents = generatedFiles[fileName], let slash = fileName.firstIndex(of: "/") else { continue }
			let moduleName = String(fileName[..<slash])
			let screenName = String(fileName[fileName.index(after: slash)...].dropLast("+SafeDIMock.swift".count))
			let lines = contents.split(separator: "\n").map { $0.trimmingCharacters(in: .whitespaces) }
			guard let memberIndex = lines.firstIndex(where: { $0.range(of: #"^(public )?let overriddenDetail(Builder)?: \("#, options: .regularExpression) != nil }),
			      let structLine = lines[..<memberIndex].last(where: { $0.range(of: #"^(public )?struct \w+ \{$"#, options: .regularExpression) != nil }),
			      let member = overrideClosureMember(lines[memberIndex])
			else { continue }
			let structName = structLine.split(separator: " ").dropLast().last.map(String.init) ?? ""
			let mocks = personCalledMockParameters(of: member.returnType, in: generatedFiles)
			guard let arguments = mocks.lazy.compactMap({ overrideClosureArguments(handing: member.parameterTypes, to: $0) }).first else {
				Issue.record("`\(screenName)`’s overrides hand `\(member.returnType)`’s override closure \(member.parameterTypes), which no `mock()` of `\(member.returnType)` a person calls takes: \(mocks)")
				continue
			}
			let parameterNames = member.parameterTypes.indices.map { "overriddenArgument\($0)" }
			let closureParameters = parameterNames.isEmpty ? "" : " \(parameterNames.joined(separator: ", ")) in"
			generatedFiles["\(moduleName)/\(screenName)\(publicMockCallerFileSuffix)"] = """
			import \(GraphFuzzerModule.seamModule.name)

			#if DEBUG
			enum \(screenName)OverrideClosureCaller {
			\tstatic func overrides() -> \(screenName).\(structName) {
			\t\t.init(\(member.label): {\(closureParameters) \(member.returnType).mock(\(arguments)) })
			\t}
			}
			#endif

			"""
		}
		return generatedFiles
	}

	/// The label, the parameter types as written, and the return type of `line`, an overrides member whose type is an
	/// optional closure, `let label: ((A, B) -> R)?`, or `nil` for any other line.
	private static func overrideClosureMember(_ line: String) -> (label: String, parameterTypes: [String], returnType: String)? {
		guard let letRange = line.range(of: "let "), let colon = line[letRange.upperBound...].range(of: ": ") else { return nil }
		let label = String(line[letRange.upperBound..<colon.lowerBound])
		var type = line[colon.upperBound...].trimmingCharacters(in: .whitespaces)
		guard type.hasPrefix("("), type.hasSuffix(")?") else { return nil }
		type = String(type.dropFirst().dropLast(2))
		// The closure may spell attributes, such as `@Sendable`, before its parameters.
		guard let parametersStart = type.firstIndex(of: "(") else { return nil }
		var depth = 0
		var parametersEnd: String.Index?
		for index in type[parametersStart...].indices {
			switch type[index] {
			case "(":
				depth += 1
			case ")":
				depth -= 1
				if depth == 0, parametersEnd == nil {
					parametersEnd = index
				}
			default:
				break
			}
			if parametersEnd != nil {
				break
			}
		}
		guard let parametersEnd, let arrow = type[parametersEnd...].range(of: " -> ") else { return nil }
		let parameterTypes = topLevelParameters(String(type[type.index(after: parametersStart)..<parametersEnd])).map { $0.trimmingCharacters(in: .whitespaces) }
		return (label, parameterTypes, type[arrow.upperBound...].trimmingCharacters(in: .whitespaces))
	}

	/// The parameters of each `mock()` of `mockedType` a person calls in `generatedFiles` – not the one only generated code
	/// calls – `public` ones first, each with its label, its type as written, and whether it has a default.
	private static func personCalledMockParameters(of mockedType: String, in generatedFiles: [String: String]) -> [[(label: String, type: String, hasDefault: Bool)]] {
		var publicMocks = [[(label: String, type: String, hasDefault: Bool)]]()
		var otherMocks = [[(label: String, type: String, hasDefault: Bool)]]()
		for (fileName, contents) in generatedFiles.sorted(by: { $0.key < $1.key }) where !fileName.hasSuffix(publicMockCallerFileSuffix) {
			var extendedType: String?
			var parameters: [(label: String, type: String, hasDefault: Bool)]?
			var isPublic = false
			for line in contents.split(separator: "\n") {
				let trimmed = line.trimmingCharacters(in: .whitespaces)
				if trimmed.hasPrefix("extension "), trimmed.hasSuffix(" {") {
					extendedType = String(trimmed.dropFirst("extension ".count).dropLast(2))
				}
				if extendedType == mockedType, trimmed.hasSuffix("static func mock(") {
					parameters = []
					isPublic = trimmed.hasPrefix("public ")
				} else if let collected = parameters, trimmed.hasPrefix(")") {
					if isPublic {
						publicMocks.append(collected)
					} else {
						otherMocks.append(collected)
					}
					parameters = nil
				} else if parameters != nil, let colon = trimmed.range(of: ": ") {
					let declaredType = trimmed[colon.upperBound...].trimmingCharacters(in: CharacterSet(charactersIn: ", "))
					let defaultRange = declaredType.range(of: " = ")
					parameters?.append((
						String(trimmed[..<colon.lowerBound]),
						defaultRange.map { String(declaredType[..<$0.lowerBound]) } ?? declaredType,
						defaultRange != nil,
					))
				}
			}
		}
		return publicMocks + otherMocks
	}

	/// The arguments of a call of a `mock()` that takes `mockParameters` passing on each of the override closure's
	/// parameters, `overriddenArgument<index>`, under the label of the parameter of its type, in the mock's order, or `nil`
	/// where a parameter of the closure matches none or the mock requires one the closure is not handed. Types are compared
	/// without `@escaping`, which only the missing spelling of distinguishes the defect the call compiles to catch.
	private static func overrideClosureArguments(handing parameterTypes: [String], to mockParameters: [(label: String, type: String, hasDefault: Bool)]) -> String? {
		func unescaped(_ type: String) -> String {
			type.hasPrefix("@escaping ") ? String(type.dropFirst("@escaping ".count)) : type
		}
		var argumentIndexByMockIndex = [Int: Int]()
		for (argumentIndex, parameterType) in parameterTypes.enumerated() {
			guard let mockIndex = mockParameters.indices.first(where: { argumentIndexByMockIndex[$0] == nil && unescaped(mockParameters[$0].type) == unescaped(parameterType) }) else { return nil }
			argumentIndexByMockIndex[mockIndex] = argumentIndex
		}
		var arguments = [String]()
		for (mockIndex, parameter) in mockParameters.enumerated() {
			if let argumentIndex = argumentIndexByMockIndex[mockIndex] {
				arguments.append("\(parameter.label): overriddenArgument\(argumentIndex)")
			} else if !parameter.hasDefault {
				return nil
			}
		}
		return arguments.joined(separator: ", ")
	}

	/// Whether the `@Instantiable` attribute on the line before `typeName`'s class declaration in `content`, a fixture
	/// file, spells `mockAttributes: "@MainActor"`.
	static func declaresMainActorMock(typeNamed typeName: String, in content: String) -> Bool {
		let lines = content.split(separator: "\n", omittingEmptySubsequences: false)
		guard let classIndex = lines.firstIndex(where: { $0.contains("final class \(typeName): ") }), classIndex > 0 else { return false }
		let attribute = lines[classIndex - 1]
		return attribute.hasPrefix("@Instantiable(") && attribute.contains("mockAttributes: \"@MainActor\"")
	}

	/// The generated initializers in `contents` – one seam's generated file, or a module's combined output – of each
	/// seam whose guard enum the file declares, in the order the file declares them, widest tier first, with each
	/// tier's access and parameters, each parameter the text of one as a tier's plain initializer spells it: every
	/// initializer only generated code calls, which every tier has, that an extension of the seam declares as its own
	/// member, not a member of a type nested in it, so each tier appears once whether or not the seam's module generates
	/// plain initializers beside them (`plainSpelling(ofGeneratedOnlyParameter:)`), or, when `keepsGeneratedOnlySpelling`,
	/// as the initializer only generated code calls spells it.
	static func seamInitializers(inGeneratedFile contents: String, keepsGeneratedOnlySpelling: Bool = false) -> [(seamTypeName: String, access: String, parameters: [String])] {
		seamInitializerTiers(inGeneratedFile: contents).map { tier in
			let parameters = if keepsGeneratedOnlySpelling {
				tier.generatedOnlyParameters
			} else {
				tier.readableParameters ?? tier.generatedOnlyParameters.map(plainSpelling(ofGeneratedOnlyParameter:))
			}
			return (tier.seamTypeName, tier.access, parameters.map { callerSpelling(ofParameter: $0, of: tier.seamTypeName) })
		}
	}

	/// The tiers of `contents` whose module generates a readable initializer beside the one only generated code calls,
	/// read as `seamInitializers(inGeneratedFile:keepsGeneratedOnlySpelling:)` reads them, with both initializers'
	/// parameters as code outside the seam's extension spells them (`callerSpelling(ofParameter:of:)`): the readable
	/// initializer a person calls takes, at each position, what the generated-only one takes there.
	static func readableInitializerTiers(inGeneratedFile contents: String) -> [(seamTypeName: String, access: String, readableParameters: [String], generatedOnlyParameters: [String])] {
		seamInitializerTiers(inGeneratedFile: contents).compactMap { tier in
			guard let readableParameters = tier.readableParameters else { return nil }
			return (
				tier.seamTypeName,
				tier.access,
				readableParameters.map { callerSpelling(ofParameter: $0, of: tier.seamTypeName) },
				tier.generatedOnlyParameters.map { callerSpelling(ofParameter: $0, of: tier.seamTypeName) },
			)
		}
	}

	/// Each tier of the generated initializers in `contents`, as `seamInitializers(inGeneratedFile:keepsGeneratedOnlySpelling:)`
	/// reads them: its seam, its access, the parameters of the initializer only generated code calls, and those of the plain
	/// initializer a module that sets `generatePlainDependencyTreeInitializers` declares just before it, or `nil` where the
	/// module declares none, each as the generated file spells it.
	private static func seamInitializerTiers(inGeneratedFile contents: String) -> [(seamTypeName: String, access: String, generatedOnlyParameters: [String], readableParameters: [String]?)] {
		var extendedType: String?
		var guardedTypes = Set<String>()
		var tiers = [(seamTypeName: String, access: String, generatedOnlyParameters: [String], readableParameters: [String]?)]()
		// The plain initializer a module that sets `generatePlainDependencyTreeInitializers` declares just before the
		// initializer only generated code calls of the same tier, which is read for that tier where it exists: a builder
		// the generated-only initializer takes as a builder struct, the plain one takes as a closure that takes nothing.
		var precedingPlainParameters: [String]?
		for line in contents.split(separator: "\n") {
			if line.hasPrefix("extension "), line.hasSuffix(" {") {
				extendedType = String(line.dropFirst("extension ".count).dropLast(2))
				precedingPlainParameters = nil
			} else if line.hasPrefix("}") {
				extendedType = nil
			} else if let extendedType, line.hasPrefix("    "), !line.hasPrefix("     ") {
				let trimmedLine = line.trimmingCharacters(in: .whitespaces)
				if trimmedLine.contains("enum __safeDI_") {
					guardedTypes.insert(extendedType)
				} else if let parametersStart = trimmedLine.range(of: "init("), trimmedLine.hasSuffix(") {") {
					let modifiers = trimmedLine[..<parametersStart.lowerBound].split(separator: " ")
					let access = modifiers.first { ["public", "package", "internal", "fileprivate", "private"].contains($0) }.map(String.init) ?? "internal"
					let parameters = topLevelParameters(String(trimmedLine[parametersStart.upperBound..<trimmedLine.index(trimmedLine.endIndex, offsetBy: -3)]))
					// A tier that takes no argument has one initializer; any other tier's plain initializer takes no prefixed
					// label.
					guard parameters.allSatisfy({ generatedOnlyLabel(of: $0) != nil }) else {
						precedingPlainParameters = parameters
						continue
					}
					let readableParameters = precedingPlainParameters.flatMap { $0.count == parameters.count ? $0 : nil }
					precedingPlainParameters = nil
					tiers.append((extendedType, access, parameters, readableParameters))
				}
			}
		}
		return tiers.filter { guardedTypes.contains($0.seamTypeName) }
	}

	/// The external label of `parameter`, a parameter of an initializer only generated code calls, without its
	/// `__safeDI_` prefix and with backticks only where the label needs them, or `nil` for a parameter without the prefix.
	static func generatedOnlyLabel(of parameter: String) -> String? {
		let trimmed = parameter.trimmingCharacters(in: .whitespaces)
		let isQuoted = trimmed.hasPrefix("`")
		let externalLabel = isQuoted
			? String(trimmed.dropFirst().prefix { $0 != "`" })
			: String(trimmed.prefix { $0 != " " && $0 != ":" })
		guard externalLabel.hasPrefix("__safeDI_") else { return nil }
		let label = String(externalLabel.dropFirst("__safeDI_".count))
		return label.allSatisfy { $0.isLetter || $0.isNumber || $0 == "_" } ? label : "`\(label)`"
	}

	/// `parameter`, a parameter of an initializer only generated code calls, as the tier's plain initializer spells it:
	/// under its label without the prefix, and a deferred parameter's `@autoclosure` as the value it returns.
	private static func plainSpelling(ofGeneratedOnlyParameter parameter: String) -> String {
		guard let label = generatedOnlyLabel(of: parameter), let colon = parameter.range(of: ": ") else { return parameter }
		var type = String(parameter[colon.upperBound...]).trimmingCharacters(in: .whitespaces)
		if type.hasPrefix("@autoclosure @escaping ") {
			type = String(type.dropFirst("@autoclosure @escaping ".count))
			if type.hasPrefix("@Sendable ") {
				type = String(type.dropFirst("@Sendable ".count))
			}
			type = String(type.dropFirst("() -> ".count))
			// A function value a plain initializer stores escapes it.
			if type.hasPrefix("("), type.contains("->"), !type.hasSuffix("?"), !type.hasSuffix("!") {
				type = "@escaping " + type
			}
		}
		return "\(label): \(type)"
	}

	/// `parameter`, a parameter of a generated initializer of `seamTypeName`, as code outside the seam's extension spells
	/// it: a builder for a hole (`userServiceBuilder: @escaping (SafeDIScope_Profile_userService) -> any UserService`) with
	/// its scope struct, which the extension names unqualified, qualified by the seam. Any other parameter as written.
	static func callerSpelling(ofParameter parameter: String, of seamTypeName: String) -> String {
		let trimmed = parameter.trimmingCharacters(in: .whitespaces)
		guard let colon = trimmed.range(of: ": ") else { return trimmed }
		// A seam's carriers and their values structs, which the seam's extension nests, as it nests its scope enums.
		let type = String(trimmed[colon.upperBound...])
			.replacingOccurrences(of: #"(?<![A-Za-z0-9_.])(SafeDI(?:Sendable)?Scope_|__safeDI_[A-Za-z0-9_]*(?:Carrier|Values)[A-Za-z0-9_]*)"#, with: "\(seamTypeName).$1", options: .regularExpression)
		return String(trimmed[..<colon.upperBound]) + type
	}

	/// `seamInitializers(inGeneratedFile:)` without each tier's access.
	static func seamInitializerParameters(inGeneratedFile contents: String) -> [(seamTypeName: String, parameters: [String])] {
		seamInitializers(inGeneratedFile: contents).map { ($0.seamTypeName, $0.parameters) }
	}

	/// `seamInitializers(inGeneratedFile:keepsGeneratedOnlySpelling:)`, each parameter spelled as the initializer only
	/// generated code calls spells it, grouped by seam, in the order the file first declares each.
	private static func seamInitializersBySeam(inGeneratedFile contents: String) -> [(seamTypeName: String, initializers: [(access: String, parameters: [String])])] {
		var grouped = [(seamTypeName: String, initializers: [(access: String, parameters: [String])])]()
		for initializer in seamInitializers(inGeneratedFile: contents, keepsGeneratedOnlySpelling: true) {
			if let index = grouped.firstIndex(where: { $0.seamTypeName == initializer.seamTypeName }) {
				grouped[index].initializers.append((initializer.access, initializer.parameters))
			} else {
				grouped.append((initializer.seamTypeName, [(initializer.access, initializer.parameters)]))
			}
		}
		return grouped
	}

	/// An enum named `callerName` whose functions call each of `tiers` of the seam `seamTypeName`, indexed by the tier's
	/// position among the seam's tiers: for each tier, one call passing every parameter, as every call must, since no
	/// parameter has a default, spelled at the narrower of the tier's access and the seam type's. The call is of the
	/// initializer every generated call calls, each parameter of the function taken as that initializer takes it: a
	/// deferred one as an `@autoclosure`, which the call passes on by calling it.
	private static func seamCaller(named callerName: String, of seamTypeName: String, calling tiers: [(offset: Int, element: (access: String, parameters: [String]))], seamTypeAccess: String) -> String {
		let accessOrder = ["private", "fileprivate", "internal", "package", "public"]
		var functions = [String]()
		for (index, tier) in tiers {
			let access = [tier.access, seamTypeAccess].min { (accessOrder.firstIndex(of: $0) ?? 2) < (accessOrder.firstIndex(of: $1) ?? 2) } ?? "internal"
			var parameters = [String]()
			var arguments = [String]()
			for parameter in tier.parameters {
				guard let label = generatedOnlyLabel(of: parameter), let colon = parameter.range(of: ": ") else { continue }
				let type = String(parameter[colon.upperBound...]).trimmingCharacters(in: .whitespaces)
				let trimmed = parameter.trimmingCharacters(in: .whitespaces)
				let externalLabel = trimmed.hasPrefix("`")
					? "`" + trimmed.dropFirst().prefix { $0 != "`" } + "`"
					: String(trimmed.prefix { $0 != " " && $0 != ":" })
				parameters.append("\(label): \(type)")
				arguments.append("\(externalLabel): \(label)\(type.hasPrefix("@autoclosure") ? "()" : "")")
			}
			functions.append("""
			    \(access) static func callTier\(index)(\(parameters.joined(separator: ", "))) -> \(seamTypeName) {
			        \(seamTypeName)(\(arguments.joined(separator: ", ")))
			    }
			""")
		}
		return """
		public enum \(callerName) {
		\(functions.joined(separator: "\n"))
		}

		"""
	}

	/// `parameters`, the text between an initializer's parentheses, split at the commas outside any brackets. The `>`
	/// of a function type's `->` closes no bracket.
	static func topLevelParameters(_ parameters: String) -> [String] {
		var topLevelParameters = [String]()
		var current = ""
		var depth = 0
		for character in parameters {
			switch character {
			case "<", "(", "[":
				depth += 1
				current.append(character)
			case ">" where current.last == "-":
				current.append(character)
			case ">", ")", "]":
				depth -= 1
				current.append(character)
			case "," where depth == 0:
				topLevelParameters.append(current)
				current = ""
			default:
				current.append(character)
			}
		}
		if !current.trimmingCharacters(in: .whitespaces).isEmpty {
			topLevelParameters.append(current)
		}
		return topLevelParameters
	}

	/// The directory the harness wrote a single-module fixture's files into, a directory of its own under the temporary
	/// directory: the directory of the first of `fileNames`, the names the fixture gives its files.
	/// - Throws: `GraphFuzzerInfrastructureError` when the harness wrote no file of that name, or wrote it anywhere but
	///   in a directory under the tests' temporary directory. The oracle deletes a rejected graph's fixture directory, and the
	///   directory of a file the harness did not write – the empty path – was the working directory.
	private static func fixtureDirectory(of fileNames: [String], in fixtures: FixturePaths, seed: UInt64) throws -> URL {
		guard let fileName = fileNames.first, let path = fixtures.writtenPath(of: fileName) else {
			throw GraphFuzzerInfrastructureError(description: "The test harness wrote no fixture named \(fileNames.first ?? "(none)") for seed \(seed): the fixture names its files apart from the names the harness gives them.")
		}
		let directory = URL(fileURLWithPath: path).deletingLastPathComponent()
		let temporaryDirectoryComponents = TestTemporaryDirectory.root.resolvingSymlinksInPath().pathComponents
		let directoryComponents = directory.resolvingSymlinksInPath().pathComponents
		guard directoryComponents.count > temporaryDirectoryComponents.count, directoryComponents.starts(with: temporaryDirectoryComponents) else {
			throw GraphFuzzerInfrastructureError(description: "The test harness wrote seed \(seed)'s fixture \(path) outside a directory of its own under the tests' temporary directory.")
		}
		return directory
	}

	/// Replaces each path to the fixture directory, from the path's start through the directory's last component, a fresh
	/// UUID each run, with `<fixture-directory>`, however the path is spelled: as the harness wrote it, resolved, or with or
	/// without a leading `/private`, since every spelling ends in that component. The directories above it are no part of
	/// what the oracle compares, and a renaming must not rewrite them when it is undone: a macOS runner's temporary
	/// directory, `/var/folders/h5/t85nd…/T`, holds `t8`, which undoing a label reversal reads as a label.
	/// The path appears in generated code only in `#sourceLocation` paths and comments, so the code still compiles.
	static func normalizer(fixtureDirectory: String) -> (String) -> String {
		let uniqueComponent = (fixtureDirectory as NSString).lastPathComponent
		guard !uniqueComponent.isEmpty else { return { $0 } }
		// A path starts after whitespace, a quote, a backtick or an opening parenthesis, as the tool's diagnostics and
		// `#sourceLocation` directives spell it.
		let pattern = #"(?:[^\s"'`(]*/)?"# + NSRegularExpression.escapedPattern(for: uniqueComponent)
		return { text in
			guard text.contains(uniqueComponent) else { return text }
			return text.replacingOccurrences(of: pattern, with: "<fixture-directory>", options: .regularExpression)
		}
	}

	/// Compiles each graph's fixture, with the generated code when the tool accepted it, and returns the failure
	/// of each graph that does not compile, or whose generated code draws a compiler warning, keyed by seed.
	///
	/// Every graph in one module, and the seam's module of every graph split across modules, compile in one `swiftc`
	/// invocation, as `verifyGeneratedCodeCompiles` compiles one test's fixture and output, as the module
	/// `GraphFuzzerModule.seamModule` in its package; distinct type-name prefixes keep the graphs apart. The split
	/// graphs' callers then compile by module, in dependency order, each module of every graph in one invocation
	/// against the modules before it. The graphs whose modules without a package (`modulesOmittingPackageName`)
	/// differ compile apart, each such module without `-package-name`. When an invocation fails, each error is attributed to a graph by the prefix in
	/// its file name. Those graphs fail, and the rest are compiled again without them, because a type error stops the
	/// compiler before the SIL passes that report errors such as a closure that captures a later local; a graph that
	/// fails in one module is left out of the modules after it. A failing graph is then compiled without its
	/// generated code, module by module, to tell a generator defect from a fixture the fuzzer got wrong. A graph that
	/// compiles fails when a compile it passed reports a warning in its generated code – the seam callers among it –
	/// that its fixture does not draw in that module, nor, for a missing `any`, in a module that module imports, as
	/// `verifyModulesCompile` fails a test (`warningsOnlyGeneratedCodeDraws`, `warnings(_:excludingExistentialAnyMessagesIn:)`).
	/// Every compile enables `ExistentialAny` (`existentialAnyFeature`), so generated code that drops an `any` its fixture
	/// spells fails the graph.
	/// Each graph's hand-written calls `C` of its seams' readable initializers
	/// (`GraphFuzzerBuilderSurface.addingBuilderCalls(to:seamTypeAccess:modules:)`) compile with its generated code; a graph
	/// whose every error is in them is compiled again without them, and fails as `builderCallDoesNotCompile` only where its
	/// own code then compiles and draws no warning.
	/// - Parameter definesDebug: Whether to compile as a debug build, which defines `DEBUG`, or as a release build, which
	///   defines no condition, so that mock-only content and generated mocks are not compiled.
	static func compilationFailures(of toolRuns: [GraphFuzzerToolRuns], definesDebug: Bool = true) async throws -> [UInt64: GraphFuzzerFailure] {
		guard !toolRuns.isEmpty else { return [:] }
		guard let artifacts = SafeDIBuildArtifactLocator.locate() else {
			throw GraphFuzzerInfrastructureError(
				description: "Could not locate SafeDI build artifacts for compilation verification. Build the package before running the fuzzer.",
			)
		}
		var filesToDelete = [URL]()
		defer {
			for fileToDelete in filesToDelete {
				try? FileManager.default.removeItem(at: fileToDelete)
			}
		}
		let fixtureDirectory = TestTemporaryDirectory.root.appendingPathComponent("safedi-graph-fuzzer-\(UUID().uuidString)")
		try FileManager.default.createDirectory(at: fixtureDirectory, withIntermediateDirectories: true)
		filesToDelete.append(fixtureDirectory)

		// The graphs compiled together, keyed by their modules without a package, in the order each set is first met.
		var packageConfigurations = [Set<GraphFuzzerModule>]()
		var combinedUnitsByConfigurationAndModule = [Set<GraphFuzzerModule>: [GraphFuzzerModule: [CompilationUnit]]]()
		var inputOnlyUnitsBySeed = [UInt64: [(module: GraphFuzzerModule, unit: CompilationUnit)]]()
		var modulesWithoutPackageBySeed = [UInt64: Set<GraphFuzzerModule>]()
		var seedsWithGeneratedCode = Set<UInt64>()
		for runs in toolRuns {
			let modulesWithoutPackage = runs.fixture.modulesOmittingPackageName
			modulesWithoutPackageBySeed[runs.fixture.seed] = modulesWithoutPackage
			if combinedUnitsByConfigurationAndModule[modulesWithoutPackage] == nil {
				packageConfigurations.append(modulesWithoutPackage)
				combinedUnitsByConfigurationAndModule[modulesWithoutPackage] = [:]
			}
			let fileModules = runs.fixture.modules ?? Array(repeating: .seamModule, count: runs.fixture.swiftFileContent.count)
			// The hand-written calls `C` of each seam's readable initializer compile with the generated code; the outcomes the
			// other oracles compare hold none.
			let generatedFilesWithCalls = GraphFuzzerBuilderSurface.addingBuilderCalls(to: runs.generatedFiles, seamTypeAccess: runs.fixture.seamTypeAccess, modules: Set(runs.fixture.modules ?? []))
			for module in GraphFuzzerModule.allCases where fileModules.contains(module) {
				let moduleDirectory = fixtureDirectory.appendingPathComponent(module.name)
				try FileManager.default.createDirectory(at: moduleDirectory, withIntermediateDirectories: true)
				let fixtureFiles = try zip(zip(runs.fixture.fileNames, runs.fixture.swiftFileContent), fileModules).filter { $0.1 == module }.map { file, _ in
					// A file name that names a directory, as a `SafeDIConfiguration.swift` does, is flattened, so that the
					// files of the graphs one invocation compiles keep names of their own.
					let fileURL = moduleDirectory.appendingPathComponent(file.0.replacingOccurrences(of: "/", with: "_"))
					try file.1.write(to: fileURL, atomically: true, encoding: .utf8)
					return fileURL
				}
				// A graph in one module compiles every generated file there; a split graph's are keyed by module. The mock
				// configuration file has the same name in every graph, so name each file after its graph's prefix.
				var generatedFiles = [String: String]()
				for (fileName, contents) in generatedFilesWithCalls {
					let moduleFileName: String
					if runs.fixture.modules == nil {
						moduleFileName = fileName
					} else if fileName.hasPrefix(module.name + "/") {
						moduleFileName = String(fileName.dropFirst(module.name.count + 1))
					} else {
						continue
					}
					let stagedFileName = moduleFileName.hasPrefix(runs.fixture.typeNamePrefix) ? moduleFileName : runs.fixture.typeNamePrefix + moduleFileName
					generatedFiles[stagedFileName] = contents
				}
				let combined = try stageCompileSources(inputSwiftFiles: fixtureFiles, generatedFiles: generatedFiles, filesToDelete: &filesToDelete)
				combinedUnitsByConfigurationAndModule[modulesWithoutPackage, default: [:]][module, default: []].append(CompilationUnit(
					seed: runs.fixture.seed,
					inputFiles: combined.inputFiles,
					generatedFiles: combined.generatedFiles.sorted { $0.path < $1.path },
				))
				inputOnlyUnitsBySeed[runs.fixture.seed, default: []].append((module, CompilationUnit(seed: runs.fixture.seed, inputFiles: combined.inputFiles, generatedFiles: [])))
				if !generatedFiles.isEmpty {
					seedsWithGeneratedCode.insert(runs.fixture.seed)
				}
			}
		}

		// Each module of every graph, in dependency order, each graph left out of the modules after one it fails in.
		var combinedFailures = [UInt64: UnitDiagnostics]()
		var builderCallFailures = [UInt64: UnitDiagnostics]()
		var generatedCodeWarningsByModule = [UInt64: [GraphFuzzerModule: [String]]]()
		var inputWarningMessagesByModule = [UInt64: [GraphFuzzerModule: Set<String>]]()
		for (configurationIndex, modulesWithoutPackage) in packageConfigurations.enumerated() {
			let combinedUnitsByModule = combinedUnitsByConfigurationAndModule[modulesWithoutPackage] ?? [:]
			var moduleOutputDirectories = [GraphFuzzerModule: URL]()
			let laterModulesAreCompiled = combinedUnitsByModule.keys.contains { $0 != .seamModule }
			for module in GraphFuzzerModule.allCases {
				let units = (combinedUnitsByModule[module] ?? []).filter { combinedFailures[$0.seed] == nil }
				guard !units.isEmpty else { continue }
				let outputDirectory = fixtureDirectory.appendingPathComponent("compiled-\(configurationIndex)-\(module.name)")
				try FileManager.default.createDirectory(at: outputDirectory, withIntermediateDirectories: true)
				let moduleCompilation = try await compilation(
					of: units,
					outputDirectory: outputDirectory,
					artifacts: artifacts,
					module: module,
					hasPackage: !modulesWithoutPackage.contains(module),
					emitsModule: laterModulesAreCompiled,
					moduleSearchPaths: module.transitiveDependencies.compactMap { moduleOutputDirectories[$0] },
					definesDebug: definesDebug,
				)
				moduleOutputDirectories[module] = outputDirectory
				combinedFailures.merge(moduleCompilation.failures) { first, _ in first }
				builderCallFailures.merge(moduleCompilation.builderCallFailures) { first, _ in first }
				for (seed, warnings) in moduleCompilation.generatedCodeWarnings {
					generatedCodeWarningsByModule[seed, default: [:]][module] = warnings
				}
				for (seed, messages) in moduleCompilation.inputWarningMessages {
					inputWarningMessagesByModule[seed, default: [:]][module] = messages
				}
			}
		}
		// A missing `any` that a graph's fixture draws in a module another of its modules imports is the fixture's wherever
		// that module's generated code copies its spelling. Every other warning is generated code's own.
		var generatedCodeWarnings = [UInt64: [String]]()
		for (seed, warningsByModule) in generatedCodeWarningsByModule {
			let inputWarningMessages = inputWarningMessagesByModule[seed] ?? [:]
			var remainingWarnings = [String]()
			for module in GraphFuzzerModule.allCases {
				if let moduleWarnings = warningsByModule[module] {
					let messagesDependenciesDraw = module.transitiveDependencies.reduce(into: Set<String>()) { messages, dependency in
						messages.formUnion(inputWarningMessages[dependency] ?? [])
					}
					remainingWarnings += warnings(moduleWarnings, excludingExistentialAnyMessagesIn: messagesDependenciesDraw)
				}
			}
			if !remainingWarnings.isEmpty {
				generatedCodeWarnings[seed] = remainingWarnings
			}
		}
		// Each failing graph's fixture alone, module by module. These units hold no generated code, so they record no
		// warnings.
		var inputOnlyFailures = [UInt64: UnitDiagnostics]()
		for seed in combinedFailures.keys.sorted() where seedsWithGeneratedCode.contains(seed) {
			let seedDirectory = fixtureDirectory.appendingPathComponent("inputs-only-\(seed)")
			var seedModuleDirectories = [GraphFuzzerModule: URL]()
			for (module, unit) in inputOnlyUnitsBySeed[seed] ?? [] {
				let outputDirectory = seedDirectory.appendingPathComponent(module.name)
				try FileManager.default.createDirectory(at: outputDirectory, withIntermediateDirectories: true)
				let unitCompilation = try await compilation(
					of: [unit],
					outputDirectory: outputDirectory,
					artifacts: artifacts,
					module: module,
					hasPackage: modulesWithoutPackageBySeed[seed]?.contains(module) != true,
					emitsModule: true,
					moduleSearchPaths: module.transitiveDependencies.compactMap { seedModuleDirectories[$0] },
					definesDebug: definesDebug,
				)
				seedModuleDirectories[module] = outputDirectory
				if let failure = unitCompilation.failures[seed] {
					inputOnlyFailures[seed] = failure
					break
				}
			}
		}
		var failures = [UInt64: GraphFuzzerFailure]()
		let configurationNote = definesDebug ? "" : "Compiled as a release build, without `DEBUG`:\n"
		for (seed, warnings) in generatedCodeWarnings where combinedFailures[seed] == nil {
			failures[seed] = GraphFuzzerFailure(seed: seed, kind: .generatedCodeDrawsWarning, details: configurationNote + warnings.joined(separator: "\n"))
		}
		for (seed, diagnostics) in combinedFailures {
			// A graph the tool rejected is compiled without generated code, so its failure is the fixture's own.
			let fixtureFails = !seedsWithGeneratedCode.contains(seed) || inputOnlyFailures[seed] != nil
			let kind: GraphFuzzerFailure.Kind = if fixtureFails {
				.fixtureDoesNotCompile
			} else if diagnostics.isCompilerCrash {
				.compilerCrashedOnGeneratedCode
			} else {
				.generatedCodeDoesNotCompile
			}
			failures[seed] = GraphFuzzerFailure(seed: seed, kind: kind, details: configurationNote + (inputOnlyFailures[seed] ?? diagnostics).text)
		}
		// A graph whose code compiles, without its hand-written calls where they failed, and draws no warning.
		for (seed, diagnostics) in builderCallFailures where failures[seed] == nil {
			failures[seed] = GraphFuzzerFailure(seed: seed, kind: .builderCallDoesNotCompile, details: configurationNote + diagnostics.text)
		}
		return failures
	}

	private struct CompilationUnit {
		let seed: UInt64
		let inputFiles: [URL]
		let generatedFiles: [URL]

		var sources: [URL] {
			inputFiles + generatedFiles
		}

		/// Whether the unit holds a hand-written call `C` of a seam's readable initializer
		/// (`GraphFuzzerBuilderSurface.addingBuilderCalls(to:seamTypeAccess:modules:)`).
		var holdsBuilderCalls: Bool {
			generatedFiles.contains { $0.lastPathComponent.hasSuffix(GraphFuzzerBuilderSurface.builderCallFileSuffix) }
		}

		/// The unit without its hand-written calls `C`, so that its own code compiles as it would without them.
		var withoutBuilderCalls: CompilationUnit {
			CompilationUnit(seed: seed, inputFiles: inputFiles, generatedFiles: generatedFiles.filter { !$0.lastPathComponent.hasSuffix(GraphFuzzerBuilderSurface.builderCallFileSuffix) })
		}

		/// Whether `fileName` belongs to this unit: a fixture staged as `input_<index>_<prefix>…`, a generated file
		/// named `<prefix>…`, or a fixture named in a `#sourceLocation` directive.
		func contains(fileName: Substring) -> Bool {
			let typeNamePrefix = GraphFuzzerFixture.typeNamePrefix(forSeed: seed)
			return fileName.hasPrefix(typeNamePrefix) || fileName.contains("_\(typeNamePrefix)")
		}
	}

	/// Why a unit failed to compile: its compiler errors, or a summary of the compiler's crash.
	private struct UnitDiagnostics {
		let text: String
		let isCompilerCrash: Bool

		init(standardError: String) {
			if let crash = GraphFuzzerCompilerCrash(standardError: standardError) {
				text = crash.summary
				isCompilerCrash = true
			} else {
				text = standardError
				isCompilerCrash = false
			}
		}

		init(errorLines: [Substring]) {
			text = errorLines.joined(separator: "\n")
			isCompilerCrash = false
		}
	}

	/// How a set of units compiled: why each unit that fails to compile fails, and the warnings each other unit's
	/// generated code draws, each keyed by seed.
	private struct UnitsCompilation {
		var failures = [UInt64: UnitDiagnostics]()
		/// Why each unit's hand-written calls `C` fail to compile, where nothing else of the unit reports an error.
		var builderCallFailures = [UInt64: UnitDiagnostics]()
		var generatedCodeWarnings = [UInt64: [String]]()
		/// The messages of the warnings each unit's fixture draws, which its graph's generated code in a module that imports
		/// this one may draw too (`warnings(_:excludingExistentialAnyMessagesIn:)`).
		var inputWarningMessages = [UInt64: Set<String>]()

		/// Records the warnings `unit`'s generated code draws in `compilerOutput`, the output of a compile that
		/// `unit` passed, which reports every warning in `unit`'s files, and those its fixture draws.
		mutating func recordGeneratedCodeWarnings(of unit: CompilationUnit, inCompilerOutput compilerOutput: String) throws {
			inputWarningMessages[unit.seed, default: []].formUnion(warningMessagesInputsDraw(inCompilerOutput: compilerOutput, inputFiles: unit.inputFiles))
			let warnings = try warningsOnlyGeneratedCodeDraws(
				inCompilerOutput: compilerOutput,
				generatedFiles: unit.generatedFiles,
				inputFiles: unit.inputFiles,
			)
			guard !warnings.isEmpty else { return }
			generatedCodeWarnings[unit.seed] = warnings
		}
	}

	/// Compiles `units` together, then again without each unit an error is attributed to, until the rest compile.
	/// A unit's warnings are read from the last compile it is part of, the one that passes, so a warning reported
	/// only by a SIL pass that a type error elsewhere stopped is still read.
	private static func compilation(
		of units: [CompilationUnit],
		outputDirectory: URL,
		artifacts: SafeDIBuildArtifacts,
		module: GraphFuzzerModule,
		hasPackage: Bool,
		emitsModule: Bool,
		moduleSearchPaths: [URL],
		definesDebug: Bool,
	) async throws -> UnitsCompilation {
		func compile(_ units: [CompilationUnit]) async throws -> SwiftCompileResult {
			try await compileSwift(
				sources: units.flatMap(\.sources),
				outputDirectory: outputDirectory,
				artifacts: artifacts,
				moduleName: module.name,
				packageName: hasPackage ? module.packageName : nil,
				emitsModule: emitsModule,
				moduleSearchPaths: moduleSearchPaths,
				definesDebug: definesDebug,
				upcomingFeatures: [existentialAnyFeature],
			)
		}
		var remainingUnits = units
		var compilation = UnitsCompilation()
		while !remainingUnits.isEmpty {
			let result = try await compile(remainingUnits)
			guard result.exitCode != 0 else {
				for unit in remainingUnits {
					try compilation.recordGeneratedCodeWarnings(of: unit, inCompilerOutput: result.stderr)
				}
				break
			}
			let errorLines = result.stderr.split(separator: "\n").filter { $0.contains(": error: ") }
			let crash = GraphFuzzerCompilerCrash(standardError: result.stderr)
			var attributedSeeds = Set<UInt64>()
			// The graphs whose every error is in a hand-written call `C`: compiled again without their calls, so that what
			// their own code reports, which a type error in a call may have stopped, is still read.
			var seedsWithFailingBuilderCalls = Set<UInt64>()
			for unit in remainingUnits {
				let unitErrorLines = errorLines.filter { line in
					unit.contains(fileName: Self.fileName(beginning: line))
				}
				if let crash, let fileName = crash.fileName, unit.contains(fileName: Substring(fileName)) {
					attributedSeeds.insert(unit.seed)
					compilation.failures[unit.seed] = UnitDiagnostics(standardError: result.stderr)
				} else if unit.holdsBuilderCalls, !unitErrorLines.isEmpty, unitErrorLines.allSatisfy({ Self.fileName(beginning: $0).hasSuffix(GraphFuzzerBuilderSurface.builderCallFileSuffix) }) {
					seedsWithFailingBuilderCalls.insert(unit.seed)
					compilation.builderCallFailures[unit.seed] = UnitDiagnostics(errorLines: unitErrorLines)
				} else if !unitErrorLines.isEmpty {
					attributedSeeds.insert(unit.seed)
					compilation.failures[unit.seed] = UnitDiagnostics(errorLines: unitErrorLines)
				}
			}
			if !seedsWithFailingBuilderCalls.isEmpty {
				remainingUnits = remainingUnits.filter { !attributedSeeds.contains($0.seed) }.map { seedsWithFailingBuilderCalls.contains($0.seed) ? $0.withoutBuilderCalls : $0 }
			} else if attributedSeeds.isEmpty, remainingUnits.count == 1 {
				compilation.failures[remainingUnits[0].seed] = UnitDiagnostics(standardError: result.stderr)
				break
			} else if attributedSeeds.isEmpty {
				// Nothing names a graph, so compile each graph on its own to find the failing ones.
				var compilingUnits = [CompilationUnit]()
				for unit in remainingUnits {
					let unitResult = try await compile([unit])
					if unitResult.exitCode != 0 {
						compilation.failures[unit.seed] = UnitDiagnostics(standardError: unitResult.stderr)
					} else {
						try compilation.recordGeneratedCodeWarnings(of: unit, inCompilerOutput: unitResult.stderr)
						compilingUnits.append(unit)
					}
				}
				// The modules compiled after this one import the graphs that compile, together.
				if emitsModule, !compilingUnits.isEmpty {
					let result = try await compile(compilingUnits)
					if result.exitCode != 0 {
						for unit in compilingUnits {
							compilation.failures[unit.seed] = UnitDiagnostics(standardError: result.stderr)
						}
					}
				}
				break
			} else {
				remainingUnits.removeAll { attributedSeeds.contains($0.seed) }
			}
		}
		return compilation
	}

	/// The file name of the location that begins `line`, a line of the compiler's output: its last path component.
	private static func fileName(beginning line: Substring) -> Substring {
		line.prefix { $0 != ":" }.split(separator: "/").last ?? ""
	}
}

struct GraphFuzzerInfrastructureError: Error, CustomStringConvertible {
	let description: String
}

/// Where a bracketed run of generated text ends. It uses no API newer than the package's platforms, so feature detection,
/// which reads builder functions with it, compiles for every platform the package supports.
enum GeneratedTextDelimiters {
	/// The index just past the delimiter that closes the one open before `start`, counting `(`, `[` and `{` alike.
	static func closingDelimiterEnd(in source: NSString, after start: Int) -> Int {
		var depth = 1
		var end = start
		while end < source.length, depth > 0 {
			switch source.character(at: end) {
			case 0x28, 0x5B, 0x7B: // ( [ {
				depth += 1
			case 0x29, 0x5D, 0x7D: // ) ] }
				depth -= 1
			default:
				break
			}
			end += 1
		}
		return end
	}
}
